//
//  NearbySim.swift — AUTOGENERATED from the PC server sim (SimCore.swift +
//  World.swift, 2026-08-23), types renamed with a Srv prefix so the
//  authoritative server simulation compiles INSIDE the app next to the
//  offline game. Powers "Host Nearby Game": your iPad runs the exact same
//  60Hz world the PC server runs — same physics, same bots, same protocol.
//  DO NOT EDIT BY HAND — regenerate with gen_nearbysim.py after sim changes.
//

import Foundation

//
//  SimCore.swift — authoritative server port of the macro-io client simulation.
//
//  Every constant and formula in this file is a 1:1 port of the client build
//  (macro-io v24): radius = sqrt(mass) * 6.3245, speed = 650 / mass^0.23,
//  eat rule 1.25x + overlap thresholds, split/eject/virus/merge maths, decay.
//  CGFloat is replaced by Double (identical on 64-bit), SwiftUI state by plain
//  structs. Rendering-only work (deformation, sprites, camera) stays client-side.
//


// MARK: - Math

struct SrvVec2: Equatable, Codable {
    var x: Double
    var y: Double
    static let zero = SrvVec2(x: 0, y: 0)
    init(x: Double, y: Double) { self.x = x; self.y = y }

    @inline(__always) func normalized() -> SrvVec2 {
        let m = (x * x + y * y).squareRoot()
        guard m > 0 else { return .zero }
        return SrvVec2(x: x / m, y: y / m)
    }
    @inline(__always) func dist(_ o: SrvVec2) -> Double {
        let dx = x - o.x, dy = y - o.y
        return (dx * dx + dy * dy).squareRoot()
    }
    @inline(__always) func distSq(_ o: SrvVec2) -> Double {
        let dx = x - o.x, dy = y - o.y
        return dx * dx + dy * dy
    }
}

@inline(__always)
func srvGridRange(_ a: Int, _ b: Int) -> ClosedRange<Int> { a <= b ? a...b : b...a }

@inline(__always)
func srvLerpFactor(base: Double, dt: Double) -> Double { 1.0 - pow(1.0 - base, dt * 60.0) }

struct SrvGridKey: Hashable { let x: Int; let y: Int }

// MARK: - Constants (client parity)

enum SrvRules {
    static let worldSize: Double = 11000
    static let foodCount = 4500
    static let virusCount = 80
    static let tokenCount = 200
    static let maxPlayerMass: Double = 22500
    static let maxCellsPerOwner = 16
    static let radiusFactor: Double = 6.3245          // sqrt(mass) * this
    static let minSplitMass: Double = 36
    static let minEjectMass: Double = 32
    static let ejectPelletMass: Double = 16
    static let splitEjectionForce: Double = 26
    static let eatMassRatio: Double = 4.0 / 3.0
    static let virusBaseMass: Double = 220
    static let virusSplitThreshold: Double = 220 + 7 * 14
    static let virusPopMinMass: Double = 133
    static let decayRate: Double = 0.002              // 0.2%/s above mass 10
    static let baseAnimationFactor: Double = 0.15
    static let foodMass: Double = 1
    static let tokenMass: Double = 4
    static let foodPaletteCount = 9
}

@inline(__always) func radiusForMass(_ m: Double) -> Double {
    (max(m, 0)).squareRoot() * SrvRules.radiusFactor
}
@inline(__always) func speedForMass(_ m: Double) -> Double {
    650 / pow(max(m, 1), 0.23)
}

// MARK: - Entities

enum SrvBotSkillTier: UInt8, CaseIterable, Codable {
    case rookie, casual, skilled, expert, elite
    var multiplier: Double {
        switch self {
        case .rookie: return 0.62
        case .casual: return 0.82
        case .skilled: return 1.00
        case .expert: return 1.22
        case .elite: return 1.48
        }
    }
    static func randomWeighted() -> SrvBotSkillTier {
        let roll = Int.random(in: 0..<100)
        if roll < 12 { return .rookie }
        if roll < 43 { return .casual }
        if roll < 80 { return .skilled }
        if roll < 96 { return .expert }
        return .elite
    }
}

enum SrvBotMode: UInt8 { case wander, forage, hunt, flee, regroup, feedPlayer, hold, trick, travel }

struct SrvCell {
    let id: UInt32
    let ownerID: UInt32

    var position: SrvVec2
    var mass: Double            // animated (rendered) mass — follows targetMass
    var targetMass: Double
    var massToAbsorb: Double = 0
    var velocity: SrvVec2 = .zero

    var mergeTimer: Double = 30
    var canMerge = false
    var splitTimer: Double = 0
    var splitImmunityTimer: Double = 0
    var immuneToCellID: UInt32? = nil
    var isMerging = false
    var mergeTargetID: UInt32? = nil
    var massFontHalved = false
    /// v5: world time this cell was created by a voluntary split (-1000 =
    /// not split-born). Split-run detection only counts absorbing FRESH
    /// split pieces, so ordinary teammate eats never register as cycles.
    var splitBornAt: Double = -1000

    // cached
    var cachedRadius: Double
    var cachedSpeed: Double
    private var cachedMovementMass: Double

    // AI
    var aiMovementDirection: SrvVec2 = .zero
    var aiThinkTimer: Double = 0
    var aiSteerTarget: SrvVec2? = nil
    var aiMode: SrvBotMode = .wander
    var aiFleeing = false
    var aiSplitCooldown: Double = 0
    var aiFeedCooldown: Double = 0
    var aiChangeDirectionTimer: Double = 0
    var aiTargetPosition: SrvVec2? = nil

    init(id: UInt32, ownerID: UInt32, position: SrvVec2, mass: Double, targetMass: Double,
         velocity: SrvVec2 = .zero, mergeTimer: Double = 30, splitTimer: Double = 0) {
        self.id = id
        self.ownerID = ownerID
        self.position = position
        self.mass = mass
        self.targetMass = targetMass
        self.velocity = velocity
        self.mergeTimer = mergeTimer
        self.splitTimer = splitTimer
        self.cachedRadius = radiusForMass(mass)
        self.cachedSpeed = speedForMass(mass)
        self.cachedMovementMass = mass
    }

    @inline(__always) mutating func refreshCache() {
        cachedRadius = radiusForMass(mass)
        let threshold = max(0.5, cachedMovementMass * 0.004)
        if abs(mass - cachedMovementMass) >= threshold {
            cachedSpeed = speedForMass(mass)
            cachedMovementMass = mass
        }
    }
}

/// Per-owner identity: a human player or a bot "player".
final class SrvOwner {
    enum Kind { case human, classicBot, feedBot, rlBot }
    let id: UInt32
    var kind: Kind
    var name: String
    var skinName: String?          // "1"..."387" or nil
    var colorIndex: Int            // palette index; client resolves exact Color
    var level: Int?                // league badge
    /// v4 parties: sanitized 6-char code shared by humans who joined the same
    /// party. Pure metadata relayed to clients (teammate rings/pfp/leaderboard);
    /// gameplay rules are identical to offline teaming (friendly fire stays on).
    var party: String = ""
    /// v5.1: identity slot inside a party (party teammate bots only) - lets a
    /// respawned bot reclaim the same persistent name/skin/color/level.
    var partySlot: Int? = nil
    var aiAggression: Double
    var aiCaution: Double
    var skillTier: SrvBotSkillTier
    var rlPolicy: MLPPolicy? = nil
    var rl2Policy: GRUPolicy? = nil
    /// v3: scripted expert teacher drives this .rlBot owner instead of a policy.
    var expertBrain = false
    /// v5.6: drill-mode puppet — scripted by DrillDirector, excluded from
    /// roster refill counts; every policy controller skips it (all brains nil).
    var drillPuppet = false
    /// v5.8: personal feeder (mod-menu feed bots online). When set, this
    /// .feedBot owner hunts down THAT human owner and all-in splits into
    /// them; nil = classic CLI feeder pool (nearest human).
    var feedTarget: UInt32? = nil
    /// v3.5: PPO league learner — controller samples stochastic actions and
    /// reports transitions to the world's RL3Collector.
    var rl3Collect = false
    /// v4: actions arrive from the external (Python) trainer via the bridge.
    var rl4External = false
    /// v4: latest external action (squashed [0,1]), applied on think cadence.
    var rl4Action: [Double]? = nil
    /// v4: serving-side Python-trained policy.
    var rl4Policy: RL4Policy? = nil
    // stats
    var kills: Int = 0
    var maxMass: Double = 0
    var bornAt: Double = 0
    var diedAt: Double? = nil
    // RL 1.5 evaluation stats (also harmless for humans/classic bots).
    var splitActions: Int = 0
    var ejectedPellets: Int = 0
    /// v5.6.7: W-press ROUNDS (not pellets — a multi-cell owner emits several
    /// pellets per round). The BC recorder uses the per-step round rate to
    /// label macro-speed feeding; pellet counts can't distinguish one press
    /// by a 4-cell player from a 4-press macro burst by a single cell.
    var ejectRounds: Int = 0
    var virusShots: Int = 0
    /// v4.2: times one of my cells was shattered by a virus (pop that split).
    var virusPops: Int = 0
    /// v4.2: enemy cells shattered by a virus I shot.
    var virusHits: Int = 0
    /// v4.3: world time of this owner's most recent voluntary split.
    var lastSplitAt: Double = -1000
    /// v4.3: kills landed within the split-kill window after a split.
    var splitKills: Int = 0
    /// v4.3: own pellets that landed inside a virus (dense shot progress).
    var virusFedPellets: Int = 0
    /// v4.3: own pellets re-collected shortly after a split (macro-split trick).
    var selfRecollects: Int = 0
    /// v4.3: remaining recollect credits for the current split window (anti-farm).
    var recollectBudget: Int = 0
    /// v4.3.2: centre-feed bursts executed (stop 0.2s, then feed inward).
    var centreFeeds: Int = 0
    /// v4.15 consolidation: own pellets eaten by own LARGEST cell while the
    /// owner is split (>1 cell) — the mechanical signature of the pro
    /// centre-feed consolidation trick (recombine mass without the timer).
    var consolidationFeeds: Int = 0
    /// v4.7: pellets landed on a virus with a poppable enemy in the cone
    /// beyond it (the pellet's own travel direction) — an *aimed* shot pellet.
    var virusAimedPellets: Int = 0
    /// v8.2 scripted-bot quality telemetry. An ejected pellet is "resolved"
    /// only when it reaches the concrete receiver/victim/virus named by the
    /// committed action. Pellets left behind are failed mechanics, regardless
    /// of whether a later stranger happens to eat them.
    var botMacroPellets: Int = 0
    var botMacroResolved: Int = 0
    var botMacroOrphaned: Int = 0
    /// v4.7: accumulated aim-staged virus-shot shaping credit. Escalates with
    /// chain progress inside one virus; consumed as a reward delta by the
    /// RL4 bridge. Reward-side only — never touches serving.
    var virusAimCredit: Double = 0
    /// v4.7: pellets ejected while a split-kill target was actually on
    /// (same maths as the tactical executor) — a *charging* pellet. The
    /// macro→split trick staged the same way the virus chain is.
    var splitChargePellets: Int = 0
    /// v6.0: policy splits fired with NO eatable prospect in double-split
    /// reach, no teammate nearby, and no threat worth fleeing — the "split
    /// for no reason" vice (spawn splits included). Counted by the actuator,
    /// priced by the RL4 bridge, measured by the exam.
    var noTargetSplits: Int = 0
    /// v6.5: executor two-hop chains armed (hop #1 of a doublesplit fired
    /// because the kill maths worked at 1.0–1.75× reach). Telemetry.
    var chainSplits: Int = 0
    /// v4.3.3: last squashed action vector from Swift-side v4 serving —
    /// probe telemetry only (how close each intent sits to its gate).
    var rl4LastServeAction: [Double]? = nil
    // MARK: v5 team stats (all zero/no-op for partyless owners)
    /// v5: own ejected pellets eaten by a PARTY TEAMMATE (feeding the partner).
    var teamFeedPellets: Int = 0
    /// v5: subset of teamFeedPellets where the receiver was the clearly
    /// BIGGER partner (≥1.15× the feeder) — the "feed the carry" meta. Only
    /// this subset earns reward credit, so two equal bots cannot ping-pong
    /// pellets for free income.
    var teamFeedCarryPellets: Int = 0
    /// v5: teammate cells absorbed (friendly eats are logistics, not kills).
    var friendlyAbsorbs: Int = 0
    /// v5: completed split-run alternations (A splits→B absorbs→B splits→A
    /// absorbs). Counted on BOTH members. Telemetry — includes in-place cycles.
    var splitRunCycles: Int = 0
    /// v5: split-run cycles that also passed the displacement gate (real map
    /// travel, not in-place mass ping-pong) — the reward-credited subset.
    var splitRunCredited: Int = 0
    /// v5: kills landed with a party teammate near the victim (double attack).
    var teamAssistKills: Int = 0

    init(id: UInt32, kind: Kind, name: String, skinName: String?, colorIndex: Int, level: Int?) {
        self.id = id
        self.kind = kind
        self.name = name
        self.skinName = skinName
        self.colorIndex = colorIndex
        self.level = level
        var seed = SystemRandomNumberGenerator()
        let s1 = Double(seed.next() % 1000) / 1000.0
        let s2 = Double(seed.next() % 1000) / 1000.0
        self.aiAggression = 0.25 + s1 * 0.75
        self.aiCaution = 0.30 + s2 * 0.70
        self.skillTier = kind == .human ? .skilled : SrvBotSkillTier.randomWeighted()
    }

    var isBot: Bool { kind != .human }
}

