// MARK: - Spatial index (port of SrvCellIndex, food grid, virus grid)

struct SrvCellSnapshot {
    let id: UInt32
    let ownerID: UInt32
    let x: Double, y: Double
    let vx: Double, vy: Double
    let mass: Double
    let radius: Double
    let solidRadius: Double
    let isBot: Bool
    let isFeedBot: Bool
    let index: Int
}

final class SrvCellIndex {
    private var grid: [SrvGridKey: [Int]] = [:]
    private(set) var items: [SrvCellSnapshot] = []
    private let bucket: Double = 700
    private var maxRadius: Double = 0

    func rebuild(cells: [SrvCell], owners: [UInt32: SrvOwner]) {
        grid.removeAll(keepingCapacity: true)
        items.removeAll(keepingCapacity: true)
        items.reserveCapacity(cells.count)
        maxRadius = 0
        for (i, c) in cells.enumerated() {
            let owner = owners[c.ownerID]
            let r = c.cachedRadius
            let snap = SrvCellSnapshot(id: c.id, ownerID: c.ownerID,
                                    x: c.position.x, y: c.position.y,
                                    vx: c.velocity.x, vy: c.velocity.y,
                                    mass: c.mass, radius: r, solidRadius: r,
                                    isBot: owner?.isBot ?? true,
                                    isFeedBot: owner?.kind == .feedBot,
                                    index: i)
            let key = SrvGridKey(x: Int(c.position.x / bucket), y: Int(c.position.y / bucket))
            grid[key, default: []].append(items.count)
            items.append(snap)
            if r > maxRadius { maxRadius = r }
        }
    }

    func forEach(near point: SrvVec2, radius: Double, _ body: (SrvCellSnapshot) -> Void) {
        let reach = radius + maxRadius
        let minX = Int((point.x - reach) / bucket), maxX = Int((point.x + reach) / bucket)
        let minY = Int((point.y - reach) / bucket), maxY = Int((point.y + reach) / bucket)
        for gx in srvGridRange(minX, maxX) {
            for gy in srvGridRange(minY, maxY) {
                guard let idxs = grid[SrvGridKey(x: gx, y: gy)] else { continue }
                for i in idxs { body(items[i]) }
            }
        }
    }
}

final class SrvFoodGrid {
    var grid: [SrvGridKey: [SrvFood]] = [:]
    let gridSize: Double = 300
    var count = 0

    func add(_ f: SrvFood) {
        let key = SrvGridKey(x: Int(f.position.x / gridSize), y: Int(f.position.y / gridSize))
        grid[key, default: []].append(f)
        count += 1
    }

    /// Client-parity spawn: pick least-crowded of 5 samples.
    func spawnPosition() -> SrvVec2 {
        var bestPos = SrvVec2.zero
        var minNeighbors = Int.max
        for _ in 0..<5 {
            let pos = SrvVec2(x: .random(in: 0...SrvRules.worldSize), y: .random(in: 0...SrvRules.worldSize))
            let key = SrvGridKey(x: Int(pos.x / gridSize), y: Int(pos.y / gridSize))
            let n = grid[key]?.count ?? 0
            if n < minNeighbors { minNeighbors = n; bestPos = pos }
        }
        return bestPos
    }

    func bestFoodCluster(near point: SrvVec2, searchBuckets: Int = 3) -> SrvVec2? {
        let cx = Int(point.x / gridSize), cy = Int(point.y / gridSize)
        var bestScore = 0.0
        var best: SrvVec2? = nil
        for gx in (cx - searchBuckets)...(cx + searchBuckets) {
            for gy in (cy - searchBuckets)...(cy + searchBuckets) {
                guard let bucket = grid[SrvGridKey(x: gx, y: gy)], bucket.count > 2 else { continue }
                let centre = SrvVec2(x: (Double(gx) + 0.5) * gridSize, y: (Double(gy) + 0.5) * gridSize)
                let dist = max(centre.dist(point), gridSize)
                let score = Double(bucket.count) / dist
                if score > bestScore { bestScore = score; best = centre }
            }
        }
        return best
    }

    /// Directional pellet density, used by the RL feature extractor.
    func density(around point: SrvVec2, direction: SrvVec2, buckets: Int = 3) -> Double {
        let probe = SrvVec2(x: point.x + direction.x * gridSize * 2, y: point.y + direction.y * gridSize * 2)
        let cx = Int(probe.x / gridSize), cy = Int(probe.y / gridSize)
        var total = 0
        for gx in (cx - 1)...(cx + 1) {
            for gy in (cy - 1)...(cy + 1) {
                total += grid[SrvGridKey(x: gx, y: gy)]?.count ?? 0
            }
        }
        return Double(total)
    }

    /// Eats pellets under a cell. Returns eaten pellet ids.
    func checkCollisions(cell: inout SrvCell) -> [UInt32] {
        let r = cell.cachedRadius
        let rSq = r * r
        let minX = Int((cell.position.x - r) / gridSize), maxX = Int((cell.position.x + r) / gridSize)
        let minY = Int((cell.position.y - r) / gridSize), maxY = Int((cell.position.y + r) / gridSize)
        var eaten: [UInt32] = []
        for x in srvGridRange(minX, maxX) {
            for y in srvGridRange(minY, maxY) {
                let key = SrvGridKey(x: x, y: y)
                guard var bucket = grid[key] else { continue }
                let start = bucket.count
                var i = bucket.count - 1
                while i >= 0 {
                    let f = bucket[i]
                    let dx = cell.position.x - f.position.x
                    if dx < -r || dx > r { i -= 1; continue }
                    let dy = cell.position.y - f.position.y
                    if dy < -r || dy > r { i -= 1; continue }
                    if dx * dx + dy * dy < rSq {
                        cell.targetMass += 1
                        eaten.append(f.id)
                        bucket.swapAt(i, bucket.count - 1)
                        bucket.removeLast()
                    }
                    i -= 1
                }
                if bucket.count != start {
                    count -= start - bucket.count
                    if bucket.isEmpty { grid.removeValue(forKey: key) } else { grid[key] = bucket }
                }
            }
        }
        return eaten
    }
}


//
//  SrvWorld.swift — the authoritative game world. Direct port of the client's
//  GAME TICK pipeline (movement → self-collisions → AI → cell-vs-cell → food →
//  tokens → viruses → ejected mass → absorption → state/decay → merging).
//


struct SrvWorldSettings {
    var botCount = 25
    var feedBotCount = 0
    var botStartMass: Double = 132
    var randomizeBotStartMass = false
    var playerStartMass: Double = 294
    var botSkill: Double = 1.0                 // 0.4 dumb ... 1.6 ruthless
    var rlBotCount = 0
    var rlCheckpoint: String? = nil
    /// v3: scripted expert teacher bots (see Expert.swift)
    var expertBotCount = 0
    /// Training-mode overrides
    var spawnFoodOnStart = true
    var maxCellsPerOwner = SrvRules.maxCellsPerOwner
    init() {}
}

final class SrvWorld {
    var settings: SrvWorldSettings
    var owners: [UInt32: SrvOwner] = [:]
    var cells: [SrvCell] = []
    var viruses: [SrvVirus] = []
    var tokens: [SrvToken] = []
    let foodGrid = SrvFoodGrid()
    var activeEjected: [SrvEjected] = []
    var staticEjectedGrid: [SrvGridKey: [SrvEjected]] = [:]
    let ejectedGridSize: Double = 500
    /// Scripted-bot pellets under a committed receiver contract. SrvBotMind
    /// registers every volley; collision or expiry closes the contract.
    struct BotMacroTrace {
        enum Goal { case ownCell(UInt32), enemyOwner(UInt32), virus(UInt32), splitRecollect }
        var ownerID: UInt32
        var goal: Goal
        var expiresAt: Double
    }
    var botMacroTraces: [UInt32: BotMacroTrace] = [:]
    var botMacroByGoal: [String: (total: Int, resolved: Int, orphaned: Int)] = [:]

    private func botMacroGoalName(_ goal: BotMacroTrace.Goal) -> String {
        switch goal {
        case .ownCell: return "ownCell"
        case .enemyOwner: return "enemy"
        case .virus: return "virus"
        case .splitRecollect: return "splitRecollect"
        }
    }

    var inputs: [UInt32: SrvPlayerInput] = [:]     // humans only
    private(set) var events: [SrvSimEvent] = []
    private(set) var time: Double = 0
    private(set) var tick: UInt64 = 0

    var initialBotFillActive = true
    /// v5.1: lobby-style mass fill for RL bots too. Re-armed whenever the RL
    /// bot target count increases (rlbots/rl4bots/leaguebots), cleared once
    /// the fill completes - respawns after that use normal small masses.
    var rlBotFillActive = false
    /// Trainer worlds keep dead owners so end-of-episode fitness can be read.
    var pruneDeadOwners = true
    private var nextEntityID: UInt32 = 1
    private var pendingBotSplits: [(ownerID: UInt32, direction: SrvVec2, target: SrvVec2?)] = []
    /// v8: utility-tree brain for classic bots (SrvBotMind.swift).
    let botMind = SrvBotMind()
    private var botPreyFocus: [UInt32: UInt32] = [:]
    /// Flock-centre anchors for stopped bots (RL centre-feed) — mirrors the human pause anchor.
    var botStopAnchors: [UInt32: SrvVec2] = [:]
    private let cellIndex = SrvCellIndex()
    /// v4 bridge: fresh spatial index for observation building between steps.
    func rebuiltIndex() -> SrvCellIndex {
        cellIndex.rebuild(cells: cells, owners: owners)
        return cellIndex
    }
    /// Deterministic BotExam helper: reproduces the exact owner aggregation
    /// used by the live classic-bot update without exposing simulation internals.
    func botOwnerFrame(_ oid: UInt32) -> BotOwnerFrame? {
        var frame: BotOwnerFrame? = nil
        for i in cells.indices where cells[i].ownerID == oid {
            let c = cells[i]
            if var f = frame {
                f.mass += c.mass
                f.weightedX += c.position.x * c.mass
                f.weightedY += c.position.y * c.mass
                f.count += 1
                if cells[f.brainIndex].mass < c.mass { f.brainIndex = i }
                frame = f
            } else {
                let tier = owners[oid]?.skillTier.multiplier ?? 1
                frame = BotOwnerFrame(brainIndex: i, mass: c.mass,
                                      weightedX: c.position.x * c.mass,
                                      weightedY: c.position.y * c.mass,
                                      count: 1,
                                      skill: min(2.25, max(0.30, settings.botSkill * tier)))
            }
        }
        return frame
    }
    private var rlController: RLBotController? = nil
    private var rl2Controller: RL2BotController? = nil
    var rlPolicyProvider: (() -> MLPPolicy)? = nil
    var rl2PolicyProvider: (() -> GRUPolicy)? = nil
    var rl4PolicyProvider: (() -> RL4Policy)? = nil
    /// v5: hosted-game party teammate bots — party code → (how many to keep
    /// alive, which checkpoint drives them). Maintained by maintainBotRoster.
    var partyBots: [String: (target: Int, policy: RL4Policy)] = [:]
    /// v5.1: stable identities for party teammate bots - slot i of a party
    /// keeps its name/skin/color/level across deaths, so the teammate stays
    /// recognizable. Kept even at `partybots 0` so re-adding restores them.
    var partyBotIdentities: [String: [(name: String, skin: String?, color: Int, level: Int?)]] = [:]
    /// v5.8: mod-menu feed bots in online games — requesting human owner →
    /// (how many personal feeders to keep alive, their name/skin). Maintained
    /// by maintainBotRoster; entry culled when the target owner is gone.
    var personalFeeders: [UInt32: (count: Int, name: String, skin: String?)] = [:]

    /// v5.8: set/replace/clear a player's personal feeder squad.
    func setPersonalFeeders(for ownerID: UInt32, count: Int, name: String, skin: String?) {
        let clamped = max(0, min(25, count))
        if clamped == 0 {
            personalFeeders.removeValue(forKey: ownerID)
            // cull the squad now — its owners get swept as dead next tick
            let squad = Set(owners.values.filter { $0.kind == .feedBot && $0.feedTarget == ownerID }.map { $0.id })
            if !squad.isEmpty { cells.removeAll { squad.contains($0.ownerID) } }
        } else {
            let trimmedName = name.isEmpty ? "Feeder" : String(name.prefix(24))
            personalFeeders[ownerID] = (count: clamped, name: trimmedName,
                                        skin: (skin?.isEmpty ?? true) ? nil : skin)
        }
    }
    /// Nonzero only in v2 training worlds. Live bots are deterministic apart
    /// from human-like reaction timing; training bots explore rare mechanics.
    var rl2Exploration: Double = 0
    /// v3.6 training: per-action prices charged to PPO learners (0 = free).
    var rl3SplitCost = 0.0
    var rl3FeedCostPerPress = 0.0
    /// v3.6 training: accrued action costs per learner, drained by the
    /// rollout loop into negative rewards.
    var rl3ActionCostAccrued: [UInt32: Double] = [:]
    /// V2.3: records human players into RL2 demo trajectories when enabled.
    var humanRecorder: RL4HumanRecorder? = nil   // v5.5: v4-native BC recorder
    var drillDirector: DrillDirector? = nil      // v5.6: practice scenarios
    /// V3.5 PPO league: collects (obs, sampled action) transitions for owners
    /// flagged `rl3Collect`, sampling actions from a Gaussian in raw space.
    var rl3Collector: RL3Collector? = nil
    /// Per-dimension sampling std-dev (raw pre-squash space) for rl3 learners.
    var rl3SampleStd: [Double]? = nil
    /// Fixed decision cadence for rl3 learners (uniform steps for GAE).
    var rl3FixedThink: Double? = nil
    /// v4 training: disable the legacy prey-ahead split assist so the policy
    /// must learn to pull the trigger itself.
    var rl4NoSplitAssist = false
    /// v6.2.1 spawn grace: for the first N seconds of a life, NO-REASON
    /// splits (no eatable target, no threat, no teammate — the ones counted
    /// as noTargetSplits) are swallowed. Kill-splits and tactical splits are
    /// never delayed: "I didn't want a delay before being able to split, I
    /// just didn't want random guaranteed splitting at spawn" (Hudson).
    var spawnSplitGrace = 2.5

    /// v4.5 "trigger discipline": buttons are macro-actions. A press executes
    /// a SMALL, competently-aimed action (the net learns WHEN, the actuator
    /// handles HOW): feed = 1 eject round per decision, centre press forces
    /// the stop itself, virus press auto-aims at the target virus, and the
    /// split executor runs in training exactly as it does at serve. Set for
    /// all v4.5+ training envs; serving derives it from the checkpoint.
    var rl4ButtonsV2 = false

    /// v6.0 serve personality: N copies of one deterministic net share
    /// identical attractors and pile into the same map region. A fixed
    /// per-owner aim rotation (±7°) decorrelates the flock without touching
    /// skill (split/feed aim stays executor-owned). Serve-path only; the
    /// exam turns it off for clean measurement.
    var rl4PersonalityJitter = true

    /// v6.4.1 serve-time distribution matching: PPO optimizes the STOCHASTIC
    /// policy (raw action + gaussian std ~0.20, then squash). Serving the
    /// deterministic mean is a train/serve mismatch — the same one that
    /// motivated calibrated button thresholds, but for the continuous dims.
    /// Symptom (Hudson, 2026-08-18): lobbies of identical served bots stand
    /// still a lot — a calm-state mean throttle below the 0.10 stop line,
    /// plus a deterministic GRU fixed-point, freezes them; in training the
    /// sampling noise keeps the same net moving. Serving therefore samples
    /// dims 0-2 (aim x/y, throttle) with the checkpoint's own trained std
    /// (cont_std in the export; 0.20 for older checkpoints). Buttons keep
    /// their calibrated thresholds. The exam turns this off for clean,
    /// comparable measurement; `rl4noise on|off` A/Bs it in the host console.
    var rl4ServeNoise = true

    init(settings: SrvWorldSettings) {
        self.settings = settings
        if settings.spawnFoodOnStart {
            for _ in 0..<SrvRules.foodCount { spawnFood() }
            for _ in 0..<SrvRules.virusCount { viruses.append(spawnVirusSafely()) }
            for _ in 0..<SrvRules.tokenCount { tokens.append(spawnToken()) }
        }
        if settings.rlBotCount > 0 { rlController = RLBotController() }
    }

    func newID() -> UInt32 { defer { nextEntityID &+= 1 }; return nextEntityID }

    /// v5.6: drill director lives outside this file but must emit sim events
    /// (events is private(set) so ordinary code cannot inject fake ones).
    func drillAppendEvent(_ e: SrvSimEvent) { events.append(e) }

    func drainEvents() -> [SrvSimEvent] {
        let out = events
        events.removeAll(keepingCapacity: true)
        return out
    }

    // MARK: - Spawning

    @discardableResult
    func spawnFood() -> SrvFood {
        let f = SrvFood(id: newID(), position: foodGrid.spawnPosition(),
                     colorIndex: UInt8(Int.random(in: 0..<SrvRules.foodPaletteCount)))
        foodGrid.add(f)
        return f
    }

    func spawnVirus() -> SrvVirus {
        let margin = SrvRules.virusBaseMass.squareRoot() * 5.3
        return SrvVirus(id: newID(), position: SrvVec2(x: .random(in: margin...(SrvRules.worldSize - margin)),
                                                 y: .random(in: margin...(SrvRules.worldSize - margin))))
    }

    func spawnVirusSafely() -> SrvVirus {
        var fallback = spawnVirus()
        outer: for _ in 0..<48 {
            let candidate = spawnVirus()
            fallback = candidate
            if containsEjected(near: candidate.position, radius: candidate.radius + 40) { continue }
            let virusClearance = candidate.radius * 2 + 30
            for v in viruses where v.position.distSq(candidate.position) < virusClearance * virusClearance { continue outer }
            for c in cells {
                let clearance = candidate.radius + c.cachedRadius + 80
                if c.position.distSq(candidate.position) < clearance * clearance { continue outer }
            }
            return candidate
        }
        return fallback
    }

    func spawnToken() -> SrvToken {
        SrvToken(id: newID(), position: SrvVec2(x: .random(in: 26...(SrvRules.worldSize - 26)),
                                          y: .random(in: 26...(SrvRules.worldSize - 26))))
    }

    /// Spawn a human player owner + first cell at a virus-safe position.
    /// Spawn mass: 9 + league level when the player has one, otherwise 80.
    @discardableResult
    func spawnHuman(name: String, skinName: String?, startMass: Double? = nil, level: Int? = nil,
                    party: String = "") -> SrvOwner {
        let ownerID = newID()
        let colorIndex = Int.random(in: 0..<8)
        let owner = SrvOwner(id: ownerID, kind: .human, name: name, skinName: skinName,
                          colorIndex: colorIndex, level: level)
        owner.party = party
        owner.bornAt = time
        owners[ownerID] = owner
        inputs[ownerID] = SrvPlayerInput()
        let mass = startMass ?? (level.map { Double(9 + $0) } ?? 80.0)
        cells.append(SrvCell(id: newID(), ownerID: ownerID,
                          position: safeSpawnPosition(radius: radiusForMass(mass)),
                          mass: mass, targetMass: mass))
        events.append(.ownerJoined(ownerID: ownerID))
        return owner
    }

    func safeSpawnPosition(radius: Double) -> SrvVec2 {
        let ws = SrvRules.worldSize
        for _ in 0..<50 {
            let candidate = SrvVec2(x: .random(in: (radius + 50)...(ws - radius - 50)),
                                 y: .random(in: (radius + 50)...(ws - radius - 50)))
            var bad = false
            for v in viruses {
                if candidate.dist(v.position) < v.radius + radius + 400 { bad = true; break }
            }
            if !bad {
                // also keep clear of cells that could instantly eat this spawn
                for c in cells where c.mass * 0.8 > radius * radius / 40 {
                    if candidate.dist(c.position) < c.cachedRadius + radius + 200 { bad = true; break }
                }
            }
            if !bad { return candidate }
        }
        return SrvVec2(x: ws / 2, y: ws / 2)
    }

    @discardableResult
    func spawnBot(kind: SrvOwner.Kind, mass explicitMass: Double? = nil,
                  expert: Bool = false, lobbyFill: Bool = false,
                  feedTarget: UInt32? = nil) -> SrvOwner {
        let spawnMass: Double
        if let m = explicitMass {
            spawnMass = m
        } else if settings.randomizeBotStartMass {
            if initialBotFillActive || lobbyFill {
                let roll = Double.random(in: 0...1)
                spawnMass = 40 + pow(roll, 2.3) * (10000 - 40)
            } else {
                spawnMass = .random(in: 40...140)
            }
        } else {
            spawnMass = settings.botStartMass
        }
        let ownerID = newID()
        let useSkin = Int.random(in: 1...100) <= 90
        let level: Int? = Int.random(in: 1...100) <= 15 ? Int.random(in: 1...150) : nil
        let owner = SrvOwner(id: ownerID, kind: kind,
                          name: kind == .feedBot ? "Feeder" : (srvBotNames.randomElement() ?? "Bot"),
                          skinName: useSkin ? String(Int.random(in: 1...387)) : nil,
                          colorIndex: Int.random(in: 0..<SrvRules.foodPaletteCount),
                          level: level)
        owner.bornAt = time
        if kind == .rlBot {
            if expert {
                owner.expertBrain = true
            } else if let provider = rl4PolicyProvider { owner.rl4Policy = provider() }
            else if let provider = rl2PolicyProvider { owner.rl2Policy = provider() }
            else { owner.rlPolicy = rlPolicyProvider?() }
        }
        owners[ownerID] = owner
        // v5.8: personal feeders spawn on a ring near their target (they are
        // meant to reach the player quickly), everyone else far from humans.
        var spawnPos = botSpawnPosition(radius: radiusForMass(spawnMass))
        if let target = feedTarget {
            owner.feedTarget = target
            if let centre = ownerCentre(target) {
                let ws = SrvRules.worldSize
                let angle = Double.random(in: 0..<(2 * .pi))
                let dist = Double.random(in: 1800...2800)
                let r = radiusForMass(spawnMass)
                spawnPos = SrvVec2(x: min(ws - r, max(r, centre.x + cos(angle) * dist)),
                                y: min(ws - r, max(r, centre.y + sin(angle) * dist)))
            }
        }
        cells.append(SrvCell(id: newID(), ownerID: ownerID,
                          position: spawnPos,
                          mass: spawnMass, targetMass: spawnMass))
        events.append(.ownerJoined(ownerID: ownerID))
        return owner
    }

    func botSpawnPosition(radius: Double) -> SrvVec2 {
        let ws = SrvRules.worldSize
        // keep spawns away from human players (client parity: distance > sqrt(totalMass)*10)
        var humanCentres: [(SrvVec2, Double)] = []
        for (oid, owner) in owners where owner.kind == .human {
            var total = 0.0, wx = 0.0, wy = 0.0
            for c in cells where c.ownerID == oid { total += c.mass; wx += c.position.x * c.mass; wy += c.position.y * c.mass }
            if total > 0 { humanCentres.append((SrvVec2(x: wx / total, y: wy / total), total.squareRoot() * 10)) }
        }
        for _ in 0..<10 {
            let p = SrvVec2(x: .random(in: radius...(ws - radius)), y: .random(in: radius...(ws - radius)))
            var ok = true
            for (centre, safe) in humanCentres where p.dist(centre) <= safe { ok = false; break }
            if ok { return p }
        }
        return SrvVec2(x: .random(in: 0...ws), y: .random(in: 0...ws))
    }

    // MARK: - SrvOwner helpers

    func ownerCells(_ ownerID: UInt32) -> [Int] {
        var out: [Int] = []
        for (i, c) in cells.enumerated() where c.ownerID == ownerID { out.append(i) }
        return out
    }

    func ownerCellCount(_ ownerID: UInt32) -> Int {
        var n = 0
        for c in cells where c.ownerID == ownerID { n += 1 }
        return n
    }
    func ownerTotalMass(_ ownerID: UInt32) -> Double {
        var total = 0.0
        for c in cells where c.ownerID == ownerID { total += c.targetMass }
        return total
    }

    func ownerCentre(_ ownerID: UInt32) -> SrvVec2? {
        var total = 0.0, wx = 0.0, wy = 0.0
        for c in cells where c.ownerID == ownerID {
            total += c.mass; wx += c.position.x * c.mass; wy += c.position.y * c.mass
        }
        guard total > 0 else { return nil }
        return SrvVec2(x: wx / total, y: wy / total)
    }

    // MARK: - Player actions (called from network layer / bot brains)

    func requestSplit(ownerID: UInt32) {
        guard let owner = owners[ownerID] else { return }
        let indices = ownerCells(ownerID)
        guard indices.count < settings.maxCellsPerOwner,
              indices.contains(where: { cells[$0].targetMass >= SrvRules.minSplitMass }) else { return }

        let input = inputs[ownerID] ?? SrvPlayerInput()
        guard let centre = ownerCentre(ownerID) else { return }

        if owner.kind == .human && input.centerAim {
            executeSplit(ownerID: ownerID, direction: .zero, toward: centre)
            return
        }
        var dir: SrvVec2
        if input.joystickDragging, input.lastDirection != .zero {
            dir = input.lastDirection.normalized()
        } else {
            guard let first = indices.first else { return }
            let toCentre = SrvVec2(x: centre.x - cells[first].position.x, y: centre.y - cells[first].position.y)
            dir = (abs(toCentre.x) < 0.1 && abs(toCentre.y) < 0.1) ? SrvVec2(x: 0, y: 1) : toCentre.normalized()
        }
        executeSplit(ownerID: ownerID, direction: dir)
    }

    /// UNIVERSAL SPLIT SYSTEM — exact port.
    func executeSplit(ownerID: UInt32, direction: SrvVec2, toward targetPoint: SrvVec2? = nil) {
        let ws = SrvRules.worldSize
        var splitDirection = direction.normalized()
        if splitDirection == .zero && targetPoint == nil { splitDirection = SrvVec2(x: 0, y: 1) }
        var newCells: [SrvCell] = []

        var eligible: [(index: Int, mass: Double)] = []
        for i in cells.indices where cells[i].ownerID == ownerID {
            eligible.append((i, cells[i].mass))
        }
        eligible.sort { $0.mass > $1.mass }
        let currentCount = eligible.count

        for item in eligible {
            guard currentCount + newCells.count < settings.maxCellsPerOwner,
                  cells[item.index].targetMass >= SrvRules.minSplitMass else { continue }
            let index = item.index
            let newMass = cells[index].targetMass / 2
            let dynamicMergeTime = 30.0 + newMass * 0.02
            let visualRadius = radiusForMass(newMass)
            var launchDirection = splitDirection
            if let targetPoint = targetPoint {
                let tv = SrvVec2(x: targetPoint.x - cells[index].position.x,
                              y: targetPoint.y - cells[index].position.y)
                launchDirection = (abs(tv.x) >= 0.1 || abs(tv.y) >= 0.1) ? tv.normalized() : .zero
            }
            let spawnOffset = visualRadius * 0.4
            var spawnPos = cells[index].position
            spawnPos.x += launchDirection.x * spawnOffset
            spawnPos.y += launchDirection.y * spawnOffset
            let physicsRadius = visualRadius * 0.55
            spawnPos.x = min(ws - physicsRadius, max(physicsRadius, spawnPos.x))
            spawnPos.y = min(ws - physicsRadius, max(physicsRadius, spawnPos.y))

            var newCell = SrvCell(id: newID(), ownerID: ownerID, position: spawnPos,
                               mass: newMass, targetMass: newMass,
                               velocity: cells[index].velocity,
                               mergeTimer: dynamicMergeTime, splitTimer: 1.0)
            newCell.splitImmunityTimer = 0.2
            newCell.immuneToCellID = cells[index].id
            newCell.splitBornAt = time   // v5: split-run detection window
            if cells[index].targetMass >= 4000 { newCell.massFontHalved = true }

            cells[index].targetMass = newMass
            cells[index].mergeTimer = dynamicMergeTime
            cells[index].canMerge = false

            newCell.velocity.x += launchDirection.x * SrvRules.splitEjectionForce
            newCell.velocity.y += launchDirection.y * SrvRules.splitEjectionForce
            newCells.append(newCell)
        }
        if !newCells.isEmpty, let o = owners[ownerID] {
            o.splitActions += 1
            // v4.3: open the split-kill / recollect credit window.
            o.lastSplitAt = time
            o.recollectBudget = 8
        }
        cells.append(contentsOf: newCells)
    }

    enum EjectAim {
        case parallel(SrvVec2)
        case converge(SrvVec2)
        case centerConverge(SrvVec2)
    }

    /// Player W press(es). `times` = number of presses in the message (macro bursts).
    func requestEject(ownerID: UInt32, times: Int) {
        guard owners[ownerID]?.kind == .human else { return }
        let input = inputs[ownerID] ?? SrvPlayerInput()
        let indices = ownerCells(ownerID)
        guard !indices.isEmpty else { return }
        guard input.centerAim || input.lastDirection != .zero else { return }

        let joy = input.lastDirection
        let magnitude = (joy.x * joy.x + joy.y * joy.y).squareRoot()
        let isParallel = !input.centerAim && magnitude > 65.0 * 0.9

        guard let centre = ownerCentre(ownerID) else { return }
        var targetPoint = centre
        if !isParallel && !input.centerAim {
            // flock radius (client parity)
            var minX = cells[indices[0]].position.x, maxX = minX
            var minY = cells[indices[0]].position.y, maxY = minY
            for i in indices {
                let c = cells[i], r = c.cachedRadius
                minX = min(minX, c.position.x - r); maxX = max(maxX, c.position.x + r)
                minY = min(minY, c.position.y - r); maxY = max(maxY, c.position.y + r)
            }
            let flockRadius = max(maxX - minX, maxY - minY) / 2
            var dist = magnitude * 15.0
            dist = max(dist, flockRadius + 50)
            let dirNorm = joy.normalized()
            targetPoint.x += dirNorm.x * dist
            targetPoint.y += dirNorm.y * dist
        }
        let aim: EjectAim = isParallel ? .parallel(joy) : (input.centerAim ? .centerConverge(centre) : .converge(targetPoint))
        let capped = min(max(times, 1), 60)
        var emitted = 0
        for _ in 0..<capped {
            for i in indices where cells[i].targetMass >= SrvRules.minEjectMass {
                if emitEjected(from: i, aim: aim) {
                    cells[i].targetMass -= SrvRules.ejectPelletMass
                    emitted += 1
                }
            }
        }
        owners[ownerID]?.ejectedPellets += emitted   // stats + v2.3 recording
        if emitted > 0 { owners[ownerID]?.ejectRounds += capped }   // v5.6.7 macro-rate stat
        if emitted > 0, splitChargeTargetExists(ownerID: ownerID) {
            owners[ownerID]?.splitChargePellets += emitted   // v4.7 split-charge
        }
    }

    /// One shared pellet trajectory generator (exact port of emitEjectedMass).
    @discardableResult
    func emitEjected(from cellIndex: Int, aim: EjectAim, distanceScale: Double = 1.0) -> Bool {
        let cell = cells[cellIndex]
        let baseDirection: SrvVec2
        switch aim {
        case .parallel(let d): baseDirection = d.normalized()
        case .converge(let t):
            baseDirection = SrvVec2(x: t.x - cell.position.x, y: t.y - cell.position.y).normalized()
        case .centerConverge(let t):
            let inward = SrvVec2(x: t.x - cell.position.x, y: t.y - cell.position.y).normalized()
            baseDirection = inward == .zero ? SrvVec2(x: 0, y: 1) : inward
        }
        guard baseDirection != .zero else { return false }

        // Client parity (v25 eject overhaul): spread + trail follow the targetMass
        // rim while the pellet still SPAWNS on the drawn (mass) rim; the travel is
        // trimmed by half the drawn rim's overhang so pellet k of a fast macro dump
        // lands exactly where a slow macro's pellet k lands - equally long trails.
        let baseSpread = 0.17
        let solidRadius = min(cell.cachedRadius, max(cell.targetMass, 0).squareRoot() * SrvRules.radiusFactor)
        let sizeRatio = 100.0 / max(100.0, solidRadius)
        let dynamicSpread = baseSpread * sizeRatio.squareRoot()
        let baseAngle = atan2(baseDirection.y, baseDirection.x)
        let spreadJitter = Double.random(in: -dynamicSpread...dynamicSpread)
        let travelAngle = baseAngle + spreadJitter
        let travelDirection = SrvVec2(x: cos(travelAngle), y: sin(travelAngle)).normalized()
        let startPosition = SrvVec2(x: cell.position.x + travelDirection.x * (cell.cachedRadius + 1),
                                 y: cell.position.y + travelDirection.y * (cell.cachedRadius + 1))
        let rimOverhang = cell.cachedRadius - solidRadius
        let distanceJitter = Double.random(in: -50...50)
        let travelDistance = max(30.0, (200.0 + distanceJitter) * min(1.6, max(0.30, distanceScale)) - rimOverhang * 0.5)

        var pellet = SrvEjected(id: newID(), ownerID: cell.ownerID,
                             position: borderSafeEjectedPosition(startPosition),
                             direction: travelDirection,
                             currentSpeed: travelDistance * 5.0,
                             creationTime: time)
        pellet.sourceCellID = cell.id   // v4.16: grace blocks only the source
        pellet.isStatic = false
        activeEjected.append(pellet)
        events.append(.ejectedAdded(pellets: [pellet]))
        return true
    }

    /// Bot W presses (exact port of ejectMassFromBotOwner).
    @discardableResult
    func ejectMassFromBotOwner(_ ownerID: UInt32, toward target: SrvVec2,
                               burstPresses: Int, reserveMass: Double,
                               parallelDirection: SrvVec2? = nil,
                               centerConverge: Bool = false,
                               excludeNear: SrvVec2? = nil,
                               onlyNear: SrvVec2? = nil,
                               speedScale: Double = 1.0) -> Int {
        guard burstPresses > 0 else { return 0 }
        var ownerIndices: [Int] = []
        var availableMass = 0.0
        for i in cells.indices where cells[i].ownerID == ownerID {
            availableMass += cells[i].targetMass
            ownerIndices.append(i)
        }
        // v5.3: centre feed is the CONSOLIDATION trick - pumping the small
        // cells' mass into the receiver. With a single cell it degenerates
        // into an eject/re-eat loop, so it is simply not available.
        if centerConverge, ownerIndices.count < 2 { return 0 }
        let aim: EjectAim = centerConverge
            ? .centerConverge(target)
            : (parallelDirection.map { .parallel($0) } ?? .converge(target))
        var emitted = 0
        for _ in 0..<burstPresses {
            // v4.15 consolidation: the RECEIVER cell (centre-feed target)
            // must not eject at itself — its inward vector is zero and the
            // (0,1) fallback would spray mass upward for nothing.
            let eligible = ownerIndices.filter { idx in
                guard cells[idx].targetMass >= SrvRules.minEjectMass else { return false }
                if let ex = excludeNear, cells[idx].position.distSq(ex) < 4 { return false }
                if let only = onlyNear, cells[idx].position.distSq(only) >= 4 { return false }
                return true
            }
            guard !eligible.isEmpty else { break }
            let roundCost = Double(eligible.count) * SrvRules.ejectPelletMass
            guard availableMass - roundCost >= reserveMass else { break }
            var emittedThisPress = 0
            for index in eligible where emitEjected(from: index, aim: aim, distanceScale: speedScale) {
                cells[index].targetMass -= SrvRules.ejectPelletMass
                availableMass -= SrvRules.ejectPelletMass
                emitted += 1
                emittedThisPress += 1
            }
            if emittedThisPress == 0 { break }
        }
        owners[ownerID]?.ejectedPellets += emitted
        if emitted > 0, splitChargeTargetExists(ownerID: ownerID) {
            owners[ownerID]?.splitChargePellets += emitted   // v4.7 split-charge
        }
        return emitted
    }

    /// Same ALL-CELLS player W physics, but returns pellet IDs so SrvBotMind can
    /// prove the committed receiver actually got the volley. There is no
    /// per-cell selection: every eligible owner cell still fires.
    @discardableResult
    func ejectMassFromBotOwnerTracked(_ ownerID: UInt32, toward target: SrvVec2,
                                      burstPresses: Int, reserveMass: Double,
                                      centerConverge: Bool = false,
                                      speedScale: Double = 1.0) -> [UInt32] {
        guard burstPresses > 0 else { return [] }
        let ownerIndices = cells.indices.filter {
            cells[$0].ownerID == ownerID && cells[$0].targetMass >= SrvRules.minEjectMass
        }
        if centerConverge, ownerIndices.count < 2 { return [] }
        // Player W still fires from every ELIGIBLE cell. For a consolidation
        // receiver, "eligible" is determined by geometry: a cell already on
        // the target has zero inward vector and cannot emit. This fixes the
        // old bot-only fallback that made the receiving cell spray upward.
        let firingIndices = ownerIndices.filter {
            !centerConverge || cells[$0].position.distSq(target) >= 4
        }
        guard !firingIndices.isEmpty else { return [] }
        let aim: EjectAim = centerConverge ? .centerConverge(target) : .converge(target)
        var available = ownerIndices.reduce(0.0) { $0 + cells[$1].targetMass }
        var ids: [UInt32] = []
        for _ in 0..<burstPresses {
            let eligible = firingIndices.filter { cells[$0].targetMass >= SrvRules.minEjectMass }
            guard !eligible.isEmpty,
                  available - Double(eligible.count) * SrvRules.ejectPelletMass >= reserveMass else { break }
            var fired = 0
            for i in eligible {
                let pelletID = nextEntityID
                if emitEjected(from: i, aim: aim, distanceScale: speedScale) {
                    cells[i].targetMass -= SrvRules.ejectPelletMass
                    available -= SrvRules.ejectPelletMass
                    ids.append(pelletID)
                    fired += 1
                }
            }
            if fired == 0 { break }
        }
        owners[ownerID]?.ejectedPellets += ids.count
        return ids
    }

    // MARK: - SrvEjected helpers

    private let ejectedRenderedRadius: Double = 4.0 * 6.3245
    private let ejectedStrokeHalf: Double = 4.0

    @inline(__always)
    func borderSafeEjectedPosition(_ p: SrvVec2) -> SrvVec2 {
        let minC = ejectedRenderedRadius + ejectedStrokeHalf
        let maxC = SrvRules.worldSize - (ejectedRenderedRadius * 0.8 + ejectedStrokeHalf)
        return SrvVec2(x: min(maxC, max(minC, p.x)), y: min(maxC, max(minC, p.y)))
    }

    func containsEjected(near point: SrvVec2, radius: Double) -> Bool {
        let rSq = radius * radius
        for m in activeEjected where m.position.distSq(point) < rSq { return true }
        let minX = Int((point.x - radius) / ejectedGridSize), maxX = Int((point.x + radius) / ejectedGridSize)
        let minY = Int((point.y - radius) / ejectedGridSize), maxY = Int((point.y + radius) / ejectedGridSize)
        for x in srvGridRange(minX, maxX) {
            for y in srvGridRange(minY, maxY) {
                guard let bucket = staticEjectedGrid[SrvGridKey(x: x, y: y)] else { continue }
                for m in bucket where m.position.distSq(point) < rSq { return true }
            }
        }
        return false
    }

    func registerBotMacro(ids: [UInt32], ownerID: UInt32,
                          goal: BotMacroTrace.Goal, ttl: Double = 4.0) {
        guard !ids.isEmpty else { return }
        owners[ownerID]?.botMacroPellets += ids.count
        let name = botMacroGoalName(goal)
        var m = botMacroByGoal[name] ?? (0, 0, 0)
        m.total += ids.count; botMacroByGoal[name] = m
        let trace = BotMacroTrace(ownerID: ownerID, goal: goal, expiresAt: time + ttl)
        for id in ids { botMacroTraces[id] = trace }
    }

    private func resolveBotMacro(_ pelletID: UInt32, eaterOwner: UInt32?,
                                 eaterCell: UInt32? = nil, virusID: UInt32? = nil) {
        guard let t = botMacroTraces.removeValue(forKey: pelletID) else { return }
        let ok: Bool
        switch t.goal {
        case .ownCell(let cellID): ok = eaterOwner == t.ownerID && eaterCell == cellID
        case .enemyOwner(let enemy): ok = eaterOwner == enemy
        case .virus(let virus): ok = virusID == virus
        case .splitRecollect:
            ok = eaterOwner == t.ownerID &&
                 (owners[t.ownerID].map { time - $0.lastSplitAt < 2.8 } ?? false)
        }
        let name = botMacroGoalName(t.goal)
        if ok {
            owners[t.ownerID]?.botMacroResolved += 1
            var m = botMacroByGoal[name] ?? (0, 0, 0)
            m.resolved += 1; botMacroByGoal[name] = m
        }
        else if eaterOwner == t.ownerID {
            // Another own piece catching the same committed consolidation
            // volley is neutral, not "orphaned"; it still never left the bot.
            return
        } else {
            owners[t.ownerID]?.botMacroOrphaned += 1
            var m = botMacroByGoal[name] ?? (0, 0, 0)
            m.orphaned += 1; botMacroByGoal[name] = m
        }
    }

    private func expireBotMacroTraces() {
        guard !botMacroTraces.isEmpty else { return }
        let expired = botMacroTraces.filter { $0.value.expiresAt <= time }
        for (id, trace) in expired {
            botMacroTraces.removeValue(forKey: id)
            // If the pellet still sits near any owner cell, the common cursor
            // is following through and it remains recoverable. Only mass
            // genuinely left behind counts as an orphaned mechanic.
            var pelletPos: SrvVec2? = activeEjected.first(where: { $0.id == id })?.position
            if pelletPos == nil {
                outer: for bucket in staticEjectedGrid.values {
                    if let p = bucket.first(where: { $0.id == id })?.position {
                        pelletPos = p; break outer
                    }
                }
            }
            let recoverable = pelletPos.map { p in
                cells.contains { $0.ownerID == trace.ownerID &&
                    $0.position.dist(p) < $0.cachedRadius + 600 }
            } ?? false
            // A receiver-contract expiry is unresolved, but not automatically
            // an orphan. "Orphaned" means the mass is observably left behind;
            // recoverable/consumed-by-an-own-sibling remains neutral.
            if !recoverable && pelletPos != nil {
                owners[trace.ownerID]?.botMacroOrphaned += 1
                let name = botMacroGoalName(trace.goal)
                var m = botMacroByGoal[name] ?? (0, 0, 0)
                m.orphaned += 1; botMacroByGoal[name] = m
            }
        }
    }

    func nearestStaticEjected(near point: SrvVec2, radius: Double) -> SrvVec2? {
        var best: SrvVec2? = nil
        var bestDistSq = radius * radius
        let minX = Int((point.x - radius) / ejectedGridSize), maxX = Int((point.x + radius) / ejectedGridSize)
        let minY = Int((point.y - radius) / ejectedGridSize), maxY = Int((point.y + radius) / ejectedGridSize)
        for x in srvGridRange(minX, maxX) {
            for y in srvGridRange(minY, maxY) {
                guard let bucket = staticEjectedGrid[SrvGridKey(x: x, y: y)], !bucket.isEmpty else { continue }
                let probe = bucket[bucket.count / 2].position
                let distSq = probe.distSq(point)
                let weighted = distSq / Double(max(1, min(bucket.count, 40)))
                if weighted < bestDistSq { bestDistSq = weighted; best = probe }
            }
        }
        return best
    }

    func nearestToken(near point: SrvVec2, radius: Double) -> SrvVec2? {
        var best: SrvVec2? = nil
        var bestSq = radius * radius
        for t in tokens {
            let dsq = t.position.distSq(point)
            if dsq < bestSq { bestSq = dsq; best = t.position }
        }
        return best
    }

    func nearestVirus(near point: SrvVec2, radius: Double) -> SrvVirus? {
        var best: SrvVirus? = nil
        var bestSq = radius * radius
        for v in viruses {
            let dsq = v.position.distSq(point)
            if dsq < bestSq { bestSq = dsq; best = v }
        }
        return best
    }

    // MARK: - TICK

    func step(dt: Double) {
        time += dt
        tick &+= 1

        // bot roster maintenance
        maintainBotRoster()

        // apply bot splits queued from last plan
        for cmd in pendingBotSplits {
            executeSplit(ownerID: cmd.ownerID, direction: cmd.direction, toward: cmd.target)
        }
        pendingBotSplits.removeAll(keepingCapacity: true)

        // v5.6: drill scenarios drive puppets / stage setups before movement.
        drillDirector?.update(world: self, dt: dt)

        moveHumans(dt: dt)
        moveBots(dt: dt)
        moveViruses(dt: dt)
        updateVirusMasses(dt: dt)

        handleSelfCollisions()

        cellIndex.rebuild(cells: cells, owners: owners)
        updateClassicBotAI(dt: dt, index: cellIndex)
        // v3 fix: controllers are created unconditionally. The old
        // settings-gated creation left manually spawned RL bots BRAINLESS in
        // every ES rollout/eval world (rlBotCount stays 0 there) — the ES
        // gradient was noise over paralyzed candidates.
        if rlController == nil { rlController = RLBotController() }
        if rl2Controller == nil { rl2Controller = RL2BotController() }
        rlController?.update(world: self, index: cellIndex, dt: dt)
        rl2Controller?.update(world: self, index: cellIndex, dt: dt)
        humanRecorder?.update(world: self, index: cellIndex, dt: dt)

        let topologyChanged = handleCellVsCellCollisions(index: cellIndex)

        handleFoodCollisions()
        if topologyChanged { cellIndex.rebuild(cells: cells, owners: owners) }
        handleTokenCollisions(index: cellIndex)
        handleVirusCollisions(index: cellIndex)
        handleEjectedCollisions(index: cellIndex)
        expireBotMacroTraces()

        updateMassAbsorption(dt: dt)
        updateEjectedFlight(dt: dt)
        updateCellState(dt: dt)
        handleCellMerging(dt: dt)

        // stats
        for (oid, owner) in owners where owner.diedAt == nil {
            let m = ownerTotalMass(oid)
            if m > owner.maxMass { owner.maxMass = m }
        }
    }

    private func maintainBotRoster() {
        var classic = 0, feed = 0, rl = 0, expert = 0
        var partyCounts: [String: Int] = [:]
        var personalFeedCounts: [UInt32: Int] = [:]   // v5.8: target → live feeders
        var liveOwners = Set<UInt32>()
        for c in cells { liveOwners.insert(c.ownerID) }
        for (oid, owner) in owners {
            if liveOwners.contains(oid) {
                switch owner.kind {
                case .classicBot: classic += 1
                case .feedBot:
                    if let t = owner.feedTarget { personalFeedCounts[t, default: 0] += 1 }
                    else { feed += 1 }
                case .rlBot:
                    if owner.drillPuppet { break }   // v5.6: never refilled
                    if owner.expertBrain { expert += 1 }
                    else if !owner.party.isEmpty, partyBots[owner.party] != nil {
                        // v5: party teammates run their own roster, separate
                        // from the plain `rl4bots` pool.
                        partyCounts[owner.party, default: 0] += 1
                    } else { rl += 1 }
                case .human: break
                }
            } else if owner.diedAt == nil {
                owner.diedAt = time
                events.append(.ownerDied(ownerID: oid))
            }
        }
        if classic < settings.botCount { spawnBot(kind: .classicBot) }
        else if initialBotFillActive { initialBotFillActive = false }
        if feed < settings.feedBotCount { spawnBot(kind: .feedBot, mass: .random(in: 48...137)) }
        // v5.8: personal feeder squads (mod-menu feed bots online).
        for (target, req) in personalFeeders {
            guard let t = owners[target], t.diedAt == nil, t.kind == .human else {
                setPersonalFeeders(for: target, count: 0, name: "", skin: nil)
                continue
            }
            let have = personalFeedCounts[target, default: 0]
            if have < req.count {
                let o = spawnBot(kind: .feedBot, mass: .random(in: 48...137), feedTarget: target)
                o.name = req.name
                o.skinName = req.skin
            } else if have > req.count {
                if let victim = owners.values.first(where: {
                    $0.kind == .feedBot && $0.feedTarget == target && liveOwners.contains($0.id)
                }) {
                    cells.removeAll { $0.ownerID == victim.id }
                }
            }
        }
        if rl < settings.rlBotCount { spawnBot(kind: .rlBot, lobbyFill: rlBotFillActive) }
        else if rlBotFillActive { rlBotFillActive = false }
        if expert < settings.expertBotCount { spawnBot(kind: .rlBot, expert: true) }
        // v5: keep each party's teammate-bot count topped up (dying party
        // bots respawn INTO the party, with the party's own checkpoint).
        for (code, entry) in partyBots {
            let have = partyCounts[code, default: 0]
            if have < entry.target {
                let o = spawnBot(kind: .rlBot)
                o.party = code
                o.rl4Policy = entry.policy
                o.rlPolicy = nil
                o.rl2Policy = nil
                // v5.1: reuse the first free identity slot so the teammate
                // keeps the same name/skin/color/level across respawns.
                var usedSlots = Set<Int>()
                for other in owners.values
                where other.id != o.id && other.kind == .rlBot && other.party == code
                    && other.diedAt == nil {
                    if let slot = other.partySlot { usedSlots.insert(slot) }
                }
                var slot = 0
                while usedSlots.contains(slot) { slot += 1 }
                o.partySlot = slot
                var idents = partyBotIdentities[code] ?? []
                while idents.count <= slot {
                    idents.append((name: srvBotNames.randomElement() ?? "Bot",
                                   skin: String(Int.random(in: 1...387)),
                                   color: Int.random(in: 0..<SrvRules.foodPaletteCount),
                                   level: Int.random(in: 1...100) <= 50 ? Int.random(in: 20...150) : nil))
                }
                partyBotIdentities[code] = idents
                let ident = idents[slot]
                o.name = ident.name
                o.skinName = ident.skin
                o.colorIndex = ident.color
                o.level = ident.level
            } else if have > entry.target {
                // trim one per tick, cells only — the roster sweep above
                // marks the owner dead next tick.
                if let victim = owners.values.first(where: {
                    $0.kind == .rlBot && !$0.expertBrain && $0.party == code
                        && liveOwners.contains($0.id)
                }) {
                    cells.removeAll { $0.ownerID == victim.id }
                }
            }
        }
        // prune long-dead owners (bots and departed humans) so owner meta stays small
        guard pruneDeadOwners else { return }
        for (oid, owner) in owners {
            if let diedAt = owner.diedAt, time - diedAt > 60 {
                owners.removeValue(forKey: oid)
                botMind.forget(oid)
            } else if owner.kind == .human, owner.diedAt == nil, !liveOwners.contains(oid), time - owner.bornAt > 5 {
                owner.diedAt = time      // disconnected human: cells removed without death event
            }
        }
    }

    // MARK: movement

    private func moveHumans(dt: Double) {
        let ws = SrvRules.worldSize
        let timeScale = dt * 60.0
        for (ownerID, input) in inputs {
            guard owners[ownerID]?.kind == .human else { continue }
            var joystickTargetPoint: SrvVec2? = nil
            var globalDirectionNorm = SrvVec2.zero
            if input.joystickDragging {
                let joyMagnitude = (input.joystick.x * input.joystick.x + input.joystick.y * input.joystick.y).squareRoot()
                let fraction = min(max(joyMagnitude / 65.0, 0), 1)
                if joyMagnitude > 0 {
                    globalDirectionNorm = SrvVec2(x: input.joystick.x / joyMagnitude, y: input.joystick.y / joyMagnitude)
                }
                guard let centre = ownerCentre(ownerID) else { continue }
                if fraction > 0.95 {
                    joystickTargetPoint = SrvVec2(x: centre.x + globalDirectionNorm.x * 100000,
                                               y: centre.y + globalDirectionNorm.y * 100000)
                } else {
                    let curve = fraction * fraction
                    let targetDistance = 50 + (1500.0 - 50) * curve
                    joystickTargetPoint = SrvVec2(x: centre.x + globalDirectionNorm.x * targetDistance,
                                               y: centre.y + globalDirectionNorm.y * targetDistance)
                }
            }

            var idToIndex: [UInt32: Int] = [:]
            let needsImmunityMap = cells.contains { $0.ownerID == ownerID && $0.splitImmunityTimer <= 0 && $0.immuneToCellID != nil }
            if needsImmunityMap {
                for i in cells.indices { idToIndex[cells[i].id] = i }
            }

            for i in cells.indices where cells[i].ownerID == ownerID {
                tickImmunity(i: i, idToIndex: idToIndex, dt: dt)
                let distanceThisFrame = cells[i].cachedSpeed * dt
                if input.joystickDragging, let target = joystickTargetPoint {
                    let dir = SrvVec2(x: target.x - cells[i].position.x, y: target.y - cells[i].position.y)
                    let dist = (dir.x * dir.x + dir.y * dir.y).squareRoot()
                    let moveDir = dist > 5 ? dir.normalized() : globalDirectionNorm
                    cells[i].position.x += moveDir.x * distanceThisFrame
                    cells[i].position.y += moveDir.y * distanceThisFrame
                } else if let anchor = input.anchor {
                    let dir = SrvVec2(x: anchor.x - cells[i].position.x, y: anchor.y - cells[i].position.y)
                    let dist = (dir.x * dir.x + dir.y * dir.y).squareRoot()
                    if dist > 1 {
                        let n = dir.normalized()
                        let travel = min(distanceThisFrame, dist)
                        cells[i].position.x += n.x * travel
                        cells[i].position.y += n.y * travel
                    }
                }
                applySharedKinematics(i: i, timeScale: timeScale, dt: dt, ws: ws)
            }
            // anchor follows the (moving) flock centre like the client does after merges
            if input.anchor != nil, let centre = ownerCentre(ownerID) {
                inputs[ownerID]?.anchor = centre
            }
        }
    }

    private func tickImmunity(i: Int, idToIndex: [UInt32: Int], dt: Double) {
        if cells[i].splitImmunityTimer > 0 {
            cells[i].splitImmunityTimer -= dt
            if cells[i].splitImmunityTimer <= 0 { cells[i].immuneToCellID = nil }
        } else if let targetID = cells[i].immuneToCellID {
            if let tIdx = idToIndex[targetID], tIdx < cells.count {
                let target = cells[tIdx]
                let totalR = cells[i].cachedRadius + target.cachedRadius
                if cells[i].position.distSq(target.position) > totalR * totalR {
                    cells[i].immuneToCellID = nil
                }
            } else {
                cells[i].immuneToCellID = nil
            }
        }
    }

    @inline(__always)
    private func applySharedKinematics(i: Int, timeScale: Double, dt: Double, ws: Double) {
        cells[i].position.x += cells[i].velocity.x * timeScale
        cells[i].position.y += cells[i].velocity.y * timeScale
        let decayFactor = pow(0.92, timeScale)
        let splitDecayFactor = pow(0.96, timeScale)
        if cells[i].splitTimer > 0 {
            cells[i].velocity.x *= splitDecayFactor
            cells[i].velocity.y *= splitDecayFactor
            cells[i].splitTimer -= dt
        } else {
            cells[i].velocity.x *= decayFactor
            cells[i].velocity.y *= decayFactor
        }
        let hardPhysicsRadius = cells[i].cachedRadius * 0.55
        if cells[i].position.x < hardPhysicsRadius { cells[i].position.x = hardPhysicsRadius; cells[i].velocity.x = 0 }
        else if cells[i].position.x > ws - hardPhysicsRadius { cells[i].position.x = ws - hardPhysicsRadius; cells[i].velocity.x = 0 }
        if cells[i].position.y < hardPhysicsRadius { cells[i].position.y = hardPhysicsRadius; cells[i].velocity.y = 0 }
        else if cells[i].position.y > ws - hardPhysicsRadius { cells[i].position.y = ws - hardPhysicsRadius; cells[i].velocity.y = 0 }
    }

    private func moveBots(dt: Double) {
        let ws = SrvRules.worldSize
        let timeScale = dt * 60.0
        var idToIndex: [UInt32: Int] = [:]
        let needsMap = cells.contains { owners[$0.ownerID]?.isBot == true && $0.splitImmunityTimer <= 0 && $0.immuneToCellID != nil }
        if needsMap { for i in cells.indices { idToIndex[cells[i].id] = i } }

        for i in cells.indices where owners[cells[i].ownerID]?.isBot == true {
            tickImmunity(i: i, idToIndex: idToIndex, dt: dt)
            let distanceThisFrame = cells[i].cachedSpeed * dt
            if let anchor = botStopAnchors[cells[i].ownerID] {
                // Stopped bot (e.g. RL centre-feed): converge on the flock
                // centre exactly like a paused human player's anchor.
                let dir = SrvVec2(x: anchor.x - cells[i].position.x, y: anchor.y - cells[i].position.y)
                let dist = (dir.x * dir.x + dir.y * dir.y).squareRoot()
                if dist > 1 {
                    let n = dir.normalized()
                    let travel = min(distanceThisFrame, dist)
                    cells[i].position.x += n.x * travel
                    cells[i].position.y += n.y * travel
                }
            } else {
                let moveDir = cells[i].aiMovementDirection.normalized()
                cells[i].position.x += moveDir.x * distanceThisFrame
                cells[i].position.y += moveDir.y * distanceThisFrame
            }
            applySharedKinematics(i: i, timeScale: timeScale, dt: dt, ws: ws)
        }
        // anchors follow the (moving) flock centre, matching the human path
        for oid in botStopAnchors.keys {
            botStopAnchors[oid] = ownerCentre(oid) ?? botStopAnchors[oid]
        }
    }

    @discardableResult
    private func moveViruses(dt: Double) -> Bool {
        let ws = SrvRules.worldSize
        let timeScale = dt * 60.0
        var movedAny = false
        for i in viruses.indices where viruses[i].velocity != .zero {
            movedAny = true
            viruses[i].position.x += viruses[i].velocity.x * dt
            viruses[i].position.y += viruses[i].velocity.y * dt
            let decay = pow(0.95, timeScale)
            viruses[i].velocity.x *= decay
            viruses[i].velocity.y *= decay
            if abs(viruses[i].velocity.x) < 5 && abs(viruses[i].velocity.y) < 5 { viruses[i].velocity = .zero }
            let r = viruses[i].radius
            viruses[i].position.x = max(r, min(ws - r, viruses[i].position.x))
            viruses[i].position.y = max(r, min(ws - r, viruses[i].position.y))
        }
        if movedAny { events.append(.virusesChanged) }
        return movedAny
    }

    private func updateVirusMasses(dt: Double) {
        let t = srvLerpFactor(base: SrvRules.baseAnimationFactor, dt: dt)
        for i in viruses.indices where abs(viruses[i].targetMass - viruses[i].mass) > 0.001 {
            viruses[i].mass += (viruses[i].targetMass - viruses[i].mass) * t
        }
    }

    // MARK: self collisions (same-owner push apart)

    private func handleSelfCollisions() {
        guard cells.count > 1 else { return }
        var groups: [UInt32: [Int]] = [:]
        var radii = [Double](repeating: 0, count: cells.count)
        for i in cells.indices {
            groups[cells[i].ownerID, default: []].append(i)
            radii[i] = cells[i].cachedRadius
        }
        for _ in 0..<2 {
            var resolvedAny = false
            for (_, indices) in groups {
                guard indices.count > 1 else { continue }
                for a in 0..<indices.count {
                    for b in (a + 1)..<indices.count {
                        let idx1 = indices[a], idx2 = indices[b]
                        guard cells[idx1].mergeTimer > 0 || cells[idx2].mergeTimer > 0 else { continue }
                        let totalRadius = radii[idx1] + radii[idx2]
                        let dx = cells[idx2].position.x - cells[idx1].position.x
                        if dx < -totalRadius || dx > totalRadius { continue }
                        let dy = cells[idx2].position.y - cells[idx1].position.y
                        if dy < -totalRadius || dy > totalRadius { continue }
                        let distSq = dx * dx + dy * dy
                        guard distSq < totalRadius * totalRadius else { continue }
                        resolvedAny = true
                        var distance = distSq.squareRoot()
                        var safeDx = dx, safeDy = dy
                        if distance == 0 { distance = 1; safeDx = 1; safeDy = 0 }
                        let overlap = totalRadius - distance
                        let dirX = safeDx / distance, dirY = safeDy / distance
                        let totalMass = cells[idx1].mass + cells[idx2].mass
                        guard totalMass > 0 else { continue }
                        let maxTimer = min(max(max(cells[idx1].splitTimer, cells[idx2].splitTimer), 0), 1)
                        let resolutionForce = 1.0 - maxTimer * 0.95
                        let actualPush = overlap * resolutionForce
                        // v5.8: a piece fully ENGULFED by a bigger cell used to
                        // shove it around (overlap ≈ both radii → even a tiny
                        // mass share moved the giant fast). Contained piece now
                        // slides out on its own; the big cell holds its ground.
                        let contained = distance + min(radii[idx1], radii[idx2])
                            <= max(radii[idx1], radii[idx2])
                        if contained {
                            if radii[idx1] >= radii[idx2] {
                                cells[idx2].position.x += dirX * actualPush
                                cells[idx2].position.y += dirY * actualPush
                            } else {
                                cells[idx1].position.x -= dirX * actualPush
                                cells[idx1].position.y -= dirY * actualPush
                            }
                        } else {
                            let pushback1 = (cells[idx2].mass / totalMass) * actualPush
                            let pushback2 = (cells[idx1].mass / totalMass) * actualPush
                            cells[idx1].position.x -= dirX * pushback1
                            cells[idx1].position.y -= dirY * pushback1
                            cells[idx2].position.x += dirX * pushback2
                            cells[idx2].position.y += dirY * pushback2
                        }
                    }
                }
            }
            if !resolvedAny { break }
        }
    }

    // MARK: cell vs cell

    @discardableResult
    private func handleCellVsCellCollisions(index: SrvCellIndex) -> Bool {
        var toRemove = Set<Int>()
        var eaterByVictimID: [UInt32: UInt32] = [:]
        var eatenMassByVictimID: [UInt32: Double] = [:]
        var victimIndexByID: [UInt32: Int] = [:]

        for eater in index.items {
            if toRemove.contains(eater.index) { continue }
            index.forEach(near: SrvVec2(x: eater.x, y: eater.y), radius: eater.radius) { victim in
                if victim.id == eater.id || victim.ownerID == eater.ownerID { return }
                if eater.mass <= victim.mass * SrvRules.eatMassRatio { return }
                if toRemove.contains(victim.index) { return }
                // immunity between fresh split pieces and their source
                if let immune = cells[victim.index].immuneToCellID, immune == eater.id,
                   cells[victim.index].splitImmunityTimer > 0 { return }
                if let immune = cells[eater.index].immuneToCellID, immune == victim.id,
                   cells[eater.index].splitImmunityTimer > 0 { return }

                let overlapFactor: Double = 0.5
                let threshold = eater.solidRadius - victim.solidRadius * overlapFactor
                if threshold <= 0 { return }
                let dx = eater.x - victim.x
                if dx < -threshold || dx > threshold { return }
                let dy = eater.y - victim.y
                if dy < -threshold || dy > threshold { return }
                if dx * dx + dy * dy >= threshold * threshold { return }

                eaterByVictimID[victim.id] = eater.id
                eatenMassByVictimID[victim.id] = victim.mass
                victimIndexByID[victim.id] = victim.index
                toRemove.insert(victim.index)
            }
        }

        guard !eaterByVictimID.isEmpty else { return false }

        func terminalEater(startingAt eaterID: UInt32) -> UInt32 {
            var terminal = eaterID
            var hops = eaterByVictimID.count + 1
            while hops > 0, let next = eaterByVictimID[terminal] {
                terminal = next
                hops -= 1
            }
            return terminal
        }

        var snapshotsByID: [UInt32: SrvCellSnapshot] = [:]
        for s in index.items { snapshotsByID[s.id] = s }

        var terminalGains: [UInt32: Double] = [:]
        for (victimID, immediate) in eaterByVictimID {
            let terminalID = terminalEater(startingAt: immediate)
            terminalGains[terminalID, default: 0] += eatenMassByVictimID[victimID] ?? 0
            // kill stats
            if let t = snapshotsByID[terminalID], let owner = owners[t.ownerID],
               let v = snapshotsByID[victimID] {
                let victimOwner = owners[v.ownerID]
                // v5: absorbing a PARTY TEAMMATE's cell is logistics (split
                // running, trick splits, the cannon), never a kill. Kill and
                // split-kill credit is gated to non-party victims so team
                // reward can't be farmed by eating your partner.
                let friendly = v.ownerID != t.ownerID
                    && !owner.party.isEmpty
                    && victimOwner?.party == owner.party
                if friendly {
                    owner.friendlyAbsorbs += 1
                    // v5 split-run detection: only FRESH split pieces count.
                    let bornAt = v.index < cells.count && cells[v.index].id == victimID
                        ? cells[v.index].splitBornAt : -1000
                    if time - bornAt < 2.5 {
                        noteSplitRunAbsorb(party: owner.party,
                                           feeder: v.ownerID, eater: t.ownerID,
                                           pos: SrvVec2(x: v.x, y: v.y))
                    }
                } else if v.ownerID != t.ownerID {
                    owner.kills += 1
                    // v4.3: a kill shortly after splitting is a landed split-kill —
                    // the behavior worth extra credit (timing AND aim were right).
                    if time - owner.lastSplitAt < 1.25 { owner.splitKills += 1 }
                    // v5: double attack — teammate close to the victim at the kill.
                    if !owner.party.isEmpty {
                        let vPos = SrvVec2(x: v.x, y: v.y)
                        for (moid, mate) in owners
                        where moid != t.ownerID && mate.party == owner.party && mate.diedAt == nil {
                            if let mc = ownerCentre(moid), mc.dist(vPos) < 900 {
                                owner.teamAssistKills += 1
                                break
                            }
                        }
                    }
                }
            }
            events.append(.cellEaten(cellID: victimID, eaterCellID: terminalID))
        }
        for (terminalID, mass) in terminalGains {
            guard let terminal = snapshotsByID[terminalID], terminal.index < cells.count,
                  !toRemove.contains(terminal.index) else { continue }
            cells[terminal.index].targetMass += mass
        }

        for i in toRemove.sorted(by: >) where i < cells.count {
            cells.remove(at: i)
        }
        return true
    }

    // MARK: food / tokens / viruses / ejected

    private func handleFoodCollisions() {
        var eatenIDs: [UInt32] = []
        for i in cells.indices {
            eatenIDs.append(contentsOf: foodGrid.checkCollisions(cell: &cells[i]))
        }
        guard !eatenIDs.isEmpty else { return }
        events.append(.foodRemoved(ids: eatenIDs))
        var added: [SrvFood] = []
        for _ in 0..<eatenIDs.count { added.append(spawnFood()) }
        events.append(.foodAdded(food: added))
    }

    private func handleTokenCollisions(index: SrvCellIndex) {
        guard !tokens.isEmpty else { return }
        var collected: [Int] = []
        for (tokenIdx, token) in tokens.enumerated() {
            var taken = false
            index.forEach(near: token.position, radius: 1) { c in
                if taken { return }
                let eatDistance = max(0, c.radius - 3)
                if eatDistance <= 0 { return }
                let dx = c.x - token.position.x
                if dx < -eatDistance || dx > eatDistance { return }
                let dy = c.y - token.position.y
                if dy < -eatDistance || dy > eatDistance { return }
                if dx * dx + dy * dy < eatDistance * eatDistance {
                    if c.index < cells.count { cells[c.index].targetMass += SrvRules.tokenMass }
                    taken = true
                }
            }
            if taken { collected.append(tokenIdx) }
        }
        guard !collected.isEmpty else { return }
        var removedIDs: [UInt32] = []
        for i in collected.sorted(by: >) where i < tokens.count {
            removedIDs.append(tokens[i].id)
            tokens.remove(at: i)
        }
        events.append(.tokensRemoved(ids: removedIDs))
        var added: [SrvToken] = []
        while tokens.count < SrvRules.tokenCount {
            let t = spawnToken()
            tokens.append(t)
            added.append(t)
        }
        events.append(.tokensAdded(tokens: added))
    }

    /// Client-parity virus split-mass distribution.
    func calculateVirusSplitMass(mass: Double, maxSplits: Int) -> [Double] {
        let playerMinSize = 32.0
        let minMass = playerMinSize * playerMinSize / 100
        let throwSize = playerMinSize + 12
        let throwMass = throwSize * throwSize / 100
        var curMass = mass
        var maxCount = maxSplits
        while maxCount > 1 && (curMass / Double(maxCount - 1)) < throwMass { maxCount = maxCount / 2 }
        if maxCount < 2 { return [mass] }
        let splitMassBase = curMass / Double(maxCount)
        if splitMassBase < minMass { return [mass] }
        var masses: [Double] = []
        if maxCount < 3 || maxCount < maxSplits || (curMass / throwMass) <= 30 {
            for _ in 0..<maxCount { masses.append(splitMassBase) }
            return masses
        }
        var restCount = maxCount
        while restCount > 2 {
            let sMass = curMass / 2
            if sMass <= throwMass { break }
            let maxSafety = curMass - throwMass * Double(restCount - 1)
            if maxSafety <= throwMass || sMass >= maxSafety { break }
            masses.append(sMass); curMass -= sMass; restCount -= 1
        }
        var sMass = curMass / 4
        if sMass > throwMass {
            while restCount > 2 {
                let maxSafety = curMass - throwMass * Double(restCount - 1)
                if maxSafety <= throwMass || sMass >= maxSafety { break }
                masses.append(sMass); curMass -= sMass; restCount -= 1
            }
        }
        sMass = curMass / 8
        if sMass > throwMass {
            while restCount > 2 {
                let maxSafety = curMass - throwMass * Double(restCount - 1)
                if maxSafety <= throwMass || sMass >= maxSafety { break }
                masses.append(sMass); curMass -= sMass; restCount -= 1
            }
        }
        if restCount > 1 {
            sMass = curMass - throwMass * Double(restCount - 1)
            if sMass > throwMass {
                masses.append(sMass); curMass -= sMass; restCount -= 1
            }
        }
        if restCount > 0 {
            sMass = curMass / Double(restCount)
            while restCount > 0 { masses.append(sMass); restCount -= 1 }
        }
        return masses
    }

    private func handleVirusCollisions(index: SrvCellIndex) {
        guard !viruses.isEmpty else { return }
        var virusIndicesToRemove: [Int] = []
        var splitActions: [(cellID: UInt32, massDistribution: [Double])] = []
        var poppedCellIDs = Set<UInt32>()

        for (virusIdx, virus) in viruses.enumerated() {
            var popped = false
            index.forEach(near: virus.position, radius: 1) { c in
                if popped || c.mass < SrvRules.virusPopMinMass || poppedCellIDs.contains(c.id) { return }
                let dx = c.x - virus.position.x
                if dx < -c.radius || dx > c.radius { return }
                let dy = c.y - virus.position.y
                if dy < -c.radius || dy > c.radius { return }
                guard dx * dx + dy * dy < c.radius * c.radius else { return }
                popped = true
                poppedCellIDs.insert(c.id)
                guard c.index < cells.count else { return }
                let ownerID = c.ownerID
                let newTotalMass = cells[c.index].targetMass + 100
                var ownerCellCount = 0
                for cc in cells where cc.ownerID == ownerID { ownerCellCount += 1 }
                let maxSplits = settings.maxCellsPerOwner - ownerCellCount + 1
                var masses = calculateVirusSplitMass(mass: newTotalMass, maxSplits: maxSplits)
                if owners[ownerID]?.kind == .human, masses.count > 1 {
                    var mix: [Double] = [masses[0]]
                    for k in stride(from: 1, to: masses.count, by: 2) { mix.append(masses[k]) }
                    for k in stride(from: 2, to: masses.count, by: 2) { mix.append(masses[k]) }
                    masses = mix
                }
                splitActions.append((cellID: c.id, massDistribution: masses))
                // v4.2 stats: a pop that actually shatters is a mistake for
                // the victim (unless deliberate) and a play for the shooter.
                if masses.count > 1 {
                    owners[ownerID]?.virusPops += 1
                    if let sid = virus.shooterID, sid != ownerID {
                        owners[sid]?.virusHits += 1
                    }
                }
            }
            if popped { virusIndicesToRemove.append(virusIdx) }
        }

        if !virusIndicesToRemove.isEmpty {
            for i in virusIndicesToRemove.sorted(by: >) where i < viruses.count {
                viruses.remove(at: i)
            }
            while viruses.count < SrvRules.virusCount { viruses.append(spawnVirusSafely()) }
            events.append(.virusesChanged)
        }

        for action in splitActions {
            guard let cellIdx = cells.firstIndex(where: { $0.id == action.cellID }) else { continue }
            let massList = action.massDistribution
            let poppedHalvesFont = cells[cellIdx].targetMass + 100 >= 4000
            cells[cellIdx].targetMass = massList[0]
            guard massList.count > 1 else { continue }
            var angle = Double.random(in: 0...(2 * .pi))
            let step = (2 * Double.pi) / Double(massList.count - 1)
            for k in 1..<massList.count {
                let mass = massList[k]
                let dynamicMergeTime = 30.0 + mass * 0.02
                let direction = SrvVec2(x: cos(angle), y: sin(angle))
                let speed = 20.0
                var newCell = SrvCell(id: newID(), ownerID: cells[cellIdx].ownerID,
                                   position: cells[cellIdx].position,
                                   mass: mass * 0.5, targetMass: mass,
                                   velocity: SrvVec2(x: direction.x * speed, y: direction.y * speed),
                                   mergeTimer: dynamicMergeTime, splitTimer: 1.0)
                newCell.splitImmunityTimer = 0.2
                newCell.immuneToCellID = cells[cellIdx].id
                newCell.massFontHalved = poppedHalvesFont
                cells.append(newCell)
                angle += step
                if angle >= 2 * .pi { angle -= 2 * .pi }
            }
        }
    }

    /// v4.7: is there a poppable enemy in the cone beyond this virus, roughly
    /// where a launched virus would fly (the pellet's travel direction)?
    /// This is what makes a virus-feed pellet an *aimed* pellet: virus between
    /// me and a target, not a pellet dumped into strategic nothing.
    func aimedEnemyBeyondVirus(virusPos: SrvVec2, shooter: UInt32,
                               direction: SrvVec2) -> Bool {
        let dir = direction.normalized()
        guard dir != .zero else { return false }
        var found = false
        // Launched viruses fly ~1200 u/s and decay; ~1400 is the lethal reach.
        cellIndex.forEach(near: virusPos, radius: 1400) { c in
            if found || c.ownerID == shooter { return }
            if c.mass < SrvRules.virusPopMinMass { return }   // can't be popped
            let dx = c.x - virusPos.x, dy = c.y - virusPos.y
            let d = (dx * dx + dy * dy).squareRoot()
            if d < 40 || d > 1400 { return }
            // cos 35° ≈ 0.82 — generous cone, launch aim is coarse anyway.
            if (dx * dir.x + dy * dir.y) / d > 0.82 { found = true }
        }
        return found
    }

    /// v4.7: split-charge — true when a split-kill is currently ON for this
    /// owner, using the same maths as the tactical executor (largest cell's
    /// half can eat a foe inside split reach, and no bigger foe endangers
    /// the halves). Ejecting mass only "charges" the macro→split trick when
    /// there is actually something to split onto; pellets counted here stage
    /// the combo credit the same way aimed pellets stage the virus chain.
    func splitChargeTargetExists(ownerID: UInt32) -> Bool {
        var largest = 0.0
        var largestPos = SrvVec2.zero
        var cellCount = 0
        for c in cells where c.ownerID == ownerID {
            if c.mass > largest { largest = c.mass; largestPos = c.position }
            cellCount += 1
        }
        guard cellCount > 0, cellCount <= 8, largest >= 70 else { return false }
        let half = largest / 2
        let reach = radiusForMass(largest) * 3.6 + 220
        var found = false
        for c in cells where c.ownerID != ownerID {
            let d = c.position.dist(largestPos)
            if d < 1400, c.mass > half * SrvRules.eatMassRatio, c.mass > largest * 0.9 {
                return false   // endangered: a foe could eat our halves
            }
            if half > c.mass * SrvRules.eatMassRatio, c.mass >= 12,
               d > 60, d < reach * 0.92 {
                found = true
            }
            // v6.5: the executor doublesplit chain charges at two-hop range
            // (macro doublesplit) — a victim a QUARTER of us still clearly
            // eats, parked past single-split reach, is an armed target too.
            // Same maths as the chain's arm gate in RL2.think().
            if cellCount <= 2, largest >= 170,
               largest / 4 > c.mass * SrvRules.eatMassRatio * 1.1,
               c.mass >= 12, d > 60, d < reach * 1.75 {
                found = true
            }
        }
        return found
    }

    private func feedVirusAndLaunchIfReady(at virusIndex: Int, with mass: SrvEjected,
                                           launched: inout [SrvVirus]) {
        guard virusIndex >= 0, virusIndex < viruses.count else { return }
        let launchRadius = viruses[virusIndex].radius
        viruses[virusIndex].targetMass += mass.mass
        viruses[virusIndex].fedMass += mass.mass
        // v4.3: dense shot progress — every pellet that lands in a virus counts,
        // not just the 7th that launches it (sparse credit never emerged).
        owners[mass.ownerID]?.virusFedPellets += 1
        // v4.7: aim-staged shot shaping. The 0.6 launch / 2.0 hit jackpots sit
        // on the far side of a 7-pellet chain the policy has never completed
        // (gen-16560 probe: 0.00 shots/min) — an unreachable lottery prices
        // the button at zero and PPO bleeds it out. Bridge the gap: a pellet
        // landed on a virus WITH a poppable enemy in the cone beyond it pays
        // an escalating chain credit (0.10 + 0.05·pelletsBanked). Unaimed
        // pellets keep only the flat v4.3 credit. Not farmable into a loop:
        // "farming" this means repeatedly firing viruses at enemies, which is
        // exactly the behavior we're buying. Credit accrues here (world knows
        // geometry); the RL4 bridge converts deltas into reward.
        if let o = owners[mass.ownerID], o.rl3Collect || o.rl4External {
            if aimedEnemyBeyondVirus(virusPos: viruses[virusIndex].position,
                                     shooter: mass.ownerID,
                                     direction: mass.direction) {
                o.virusAimedPellets += 1
                let banked = min(7.0, viruses[virusIndex].fedMass / SrvRules.ejectPelletMass)
                o.virusAimCredit += 0.10 + 0.05 * banked
            }
        } else if owners[mass.ownerID] != nil,
                  aimedEnemyBeyondVirus(virusPos: viruses[virusIndex].position,
                                        shooter: mass.ownerID,
                                        direction: mass.direction) {
            // Non-training owners still count the stat (probe visibility).
            owners[mass.ownerID]?.virusAimedPellets += 1
        }
        events.append(.virusesChanged)
        guard viruses[virusIndex].targetMass >= SrvRules.virusSplitThreshold else { return }
        viruses[virusIndex].mass = SrvRules.virusBaseMass
        viruses[virusIndex].targetMass = SrvRules.virusBaseMass
        viruses[virusIndex].fedMass = 0
        let n = mass.direction.normalized()
        let shootDirection = n == .zero ? SrvVec2(x: 0, y: 1) : n
        let offset = launchRadius + 60
        var newVirus = SrvVirus(id: newID(), position: SrvVec2(x: viruses[virusIndex].position.x + shootDirection.x * offset,
                                                         y: viruses[virusIndex].position.y + shootDirection.y * offset))
        newVirus.velocity = SrvVec2(x: shootDirection.x * 1200, y: shootDirection.y * 1200)
        newVirus.shooterID = mass.ownerID
        launched.append(newVirus)
        owners[mass.ownerID]?.virusShots += 1
    }

    /// v4.15 consolidation: own pellet eaten by own LARGEST cell while the
    /// owner is split — the mechanical signature of the pro centre-feed
    /// consolidation trick. Pure stat (probe visibility); the reward side is
    /// the potential-based φ shaping in RL4, which pays the mass MOVE itself
    /// and therefore cannot be farmed by eject/re-eat loops (φ only rises
    /// when the largest cell's share of total mass actually grows).
    private func creditConsolidationFeed(eaterCellIndex: Int, pelletOwner: UInt32,
                                         sourceCellID: UInt32 = 0) {
        guard eaterCellIndex >= 0, eaterCellIndex < cells.count else { return }
        let eater = cells[eaterCellIndex]
        guard eater.ownerID == pelletOwner, let o = owners[pelletOwner] else { return }
        // v4.16: a cell re-eating a pellet it ejected itself is recycling,
        // not consolidation — no stat credit.
        if sourceCellID != 0, eater.id == sourceCellID { return }
        var count = 0
        var largest = 0.0
        for c in cells where c.ownerID == pelletOwner {
            count += 1
            largest = max(largest, c.mass)
        }
        guard count > 1, eater.mass >= largest * 0.999 else { return }
        o.consolidationFeeds += 1
    }

    // v5.3: the v4.16 "largest cell eats own immune pellets instantly"
    // exception is GONE. Humans (client parity) have the 1.0s grace block
    // every own cell, so bots were playing by softer rules. Consolidation
    // still works: centre-feed pellets settle on the receiver and are
    // absorbed the moment the grace lapses (~1s), exactly like a real
    // player's centre feed.

    /// v4.3: credit re-collecting your own pellet shortly after a split
    /// (the macro-then-split trick: eject forward, split onto the pellets,
    /// the front half regains the mass). Budgeted per split so the reward
    /// can't be farmed by eject/re-eat loops.
    private func creditSelfRecollect(eater: UInt32, pelletOwner: UInt32) {
        guard eater == pelletOwner, let o = owners[eater],
              time - o.lastSplitAt < 2.5, o.recollectBudget > 0 else { return }
        o.recollectBudget -= 1
        o.selfRecollects += 1
    }

    /// v5: own pellet eaten by a party TEAMMATE — feeding the partner. Pure
    /// stat; the reward side (RL4 bridge) budgets the credit per time window
    /// so eject/re-eat loops can't farm it (and under the shared team reward
    /// the mass transfer itself is neutral anyway).
    private func creditTeamFeed(eaterCellIndex: Int, pelletOwner: UInt32) {
        guard eaterCellIndex >= 0, eaterCellIndex < cells.count else { return }
        let eaterOwnerID = cells[eaterCellIndex].ownerID
        guard eaterOwnerID != pelletOwner,
              let feeder = owners[pelletOwner], let receiver = owners[eaterOwnerID],
              !feeder.party.isEmpty, feeder.party == receiver.party else { return }
        feeder.teamFeedPellets += 1
        if ownerTotalMass(eaterOwnerID) >= ownerTotalMass(pelletOwner) * 1.15 {
            feeder.teamFeedCarryPellets += 1
        }
    }

    // MARK: v5 split-run detection (per party)
    //
    // Split running: A splits forward, B absorbs A's fresh pieces; then B
    // splits forward and A absorbs B's pieces. One completed ALTERNATION
    // (roles swapped within the window) = one cycle, counted on both members.
    // The credited subset additionally requires real displacement between the
    // two absorb events — in-place mass ping-pong produces cycles but no
    // credit, so the reward can't be farmed by circling on the spot.
    private struct SplitRunEvent {
        var feeder: UInt32      // the owner who split (pieces got eaten)
        var eater: UInt32       // the teammate who absorbed them
        var time: Double
        var pos: SrvVec2
    }
    private var splitRunLast: [String: SplitRunEvent] = [:]
    private var splitRunCycleAt: [String: Double] = [:]

    private func noteSplitRunAbsorb(party: String, feeder: UInt32, eater: UInt32, pos: SrvVec2) {
        defer {
            splitRunLast[party] = SplitRunEvent(feeder: feeder, eater: eater,
                                                time: time, pos: pos)
        }
        guard let prev = splitRunLast[party],
              prev.feeder == eater, prev.eater == feeder,   // roles alternated
              time - prev.time < 4.0,
              time - (splitRunCycleAt[party] ?? -1000) > 1.5 else { return }
        splitRunCycleAt[party] = time
        owners[feeder]?.splitRunCycles += 1
        owners[eater]?.splitRunCycles += 1
        if pos.dist(prev.pos) > 450 {   // moved — real split running
            owners[feeder]?.splitRunCredited += 1
            owners[eater]?.splitRunCredited += 1
        }
    }

    private func handleEjectedCollisions(index: SrvCellIndex) {
        let gracePeriod = 1.0
        var launched: [SrvVirus] = []
        var removedIDs: [UInt32] = []

        // 1. flying pellets vs cells, then viruses
        var i = activeEjected.count - 1
        while i >= 0 {
            let mass = activeEjected[i]
            let isImmune = (time - mass.creationTime) < gracePeriod
            var eaten = false
            index.forEach(near: mass.position, radius: 1) { c in
                if eaten { return }
                // Player parity: the 1.0s grace blocks EVERY own cell,
                // exactly like the offline client. Consolidation still works:
                // the pellets settle on the receiver and are absorbed when the
                // grace lapses; sourceCellID stays stat-only (recycling denial).
                if isImmune && c.ownerID == mass.ownerID { return }
                // v5.8: a sub-21-mass cell can never re-eat its own pellet
                if c.ownerID == mass.ownerID && c.mass < 21 { return }
                // v5.9.3: pickup needs ~30% of the pellet's circle covered
                // (chord rule: reach = R_cell + 8.1, pellet r ≈ 25.3) — a rim
                // graze no longer consumes. Mass is credited instantly at this
                // trigger; the magnet slide, shrink and fade stay cosmetic.
                let reach = c.radius + 8.1
                let dx = mass.position.x - c.x
                if dx < -reach || dx > reach { return }
                let dy = mass.position.y - c.y
                if dy < -reach || dy > reach { return }
                if dx * dx + dy * dy < reach * reach {
                    if c.index < cells.count { cells[c.index].massToAbsorb += mass.mass }
                    creditSelfRecollect(eater: c.ownerID, pelletOwner: mass.ownerID)
                    creditConsolidationFeed(eaterCellIndex: c.index, pelletOwner: mass.ownerID,
                                            sourceCellID: mass.sourceCellID)
                    creditTeamFeed(eaterCellIndex: c.index, pelletOwner: mass.ownerID)
                    resolveBotMacro(mass.id, eaterOwner: c.ownerID, eaterCell: c.id)
                    eaten = true
                }
            }
            if !eaten, !viruses.isEmpty {
                for (vIdx, virus) in viruses.enumerated() {
                    let vr = virus.radius
                    let dx = mass.position.x - virus.position.x
                    if dx < -vr || dx > vr { continue }
                    let dy = mass.position.y - virus.position.y
                    if dy < -vr || dy > vr { continue }
                    let virusRadiusSq = virus.mass * 28.09
                    if dx * dx + dy * dy < virusRadiusSq {
                        resolveBotMacro(mass.id, eaterOwner: nil, virusID: virus.id)
                        feedVirusAndLaunchIfReady(at: vIdx, with: mass, launched: &launched)
                        eaten = true
                        break
                    }
                }
            }
            if eaten {
                removedIDs.append(mass.id)
                activeEjected.swapAt(i, activeEjected.count - 1)
                activeEjected.removeLast()
            }
            i -= 1
        }

        // 2. settled pellets vs cells (buckets near cells only)
        if !staticEjectedGrid.isEmpty {
            var keysNearCells = Set<SrvGridKey>()
            for c in index.items {
                let minX = Int((c.x - c.radius) / ejectedGridSize), maxX = Int((c.x + c.radius) / ejectedGridSize)
                let minY = Int((c.y - c.radius) / ejectedGridSize), maxY = Int((c.y + c.radius) / ejectedGridSize)
                for x in srvGridRange(minX, maxX) {
                    for y in srvGridRange(minY, maxY) { keysNearCells.insert(SrvGridKey(x: x, y: y)) }
                }
            }
            for key in keysNearCells {
                guard var bucket = staticEjectedGrid[key], !bucket.isEmpty else { continue }
                var changed = false
                var j = bucket.count - 1
                while j >= 0 {
                    let mass = bucket[j]
                    let isImmune = (time - mass.creationTime) < gracePeriod
                    var eaten = false
                    index.forEach(near: mass.position, radius: 1) { c in
                        if eaten { return }
                        // Player parity: the 1.0s grace blocks EVERY own cell,
                // exactly like the offline client. Consolidation still works:
                // the pellets settle on the receiver and are absorbed when the
                // grace lapses; sourceCellID stays stat-only (recycling denial).
                if isImmune && c.ownerID == mass.ownerID { return }
                        // v5.8: a sub-21-mass cell can never re-eat its own pellet
                        if c.ownerID == mass.ownerID && c.mass < 21 { return }
                        // v5.9.3: ~30% pellet coverage required (reach = R_cell + 8.1)
                        let reach = c.radius + 8.1
                        let dx = mass.position.x - c.x
                        if dx < -reach || dx > reach { return }
                        let dy = mass.position.y - c.y
                        if dy < -reach || dy > reach { return }
                        if dx * dx + dy * dy < reach * reach {
                            if c.index < cells.count { cells[c.index].massToAbsorb += mass.mass }
                            creditSelfRecollect(eater: c.ownerID, pelletOwner: mass.ownerID)
                            creditConsolidationFeed(eaterCellIndex: c.index, pelletOwner: mass.ownerID,
                                                    sourceCellID: mass.sourceCellID)
                            creditTeamFeed(eaterCellIndex: c.index, pelletOwner: mass.ownerID)
                            resolveBotMacro(mass.id, eaterOwner: c.ownerID, eaterCell: c.id)
                            eaten = true
                        }
                    }
                    if eaten {
                        removedIDs.append(mass.id)
                        bucket.swapAt(j, bucket.count - 1)
                        bucket.removeLast()
                        changed = true
                    }
                    j -= 1
                }
                if changed {
                    if bucket.isEmpty { staticEjectedGrid.removeValue(forKey: key) }
                    else { staticEjectedGrid[key] = bucket }
                }
            }
        }

        // 3. viruses swallow settled pellets
        var v = viruses.count - 1
        while v >= 0 {
            let vPos = viruses[v].position
            let vRad = viruses[v].radius
            let vRadSq = vRad * vRad
            let minX = Int((vPos.x - vRad) / ejectedGridSize), maxX = Int((vPos.x + vRad) / ejectedGridSize)
            let minY = Int((vPos.y - vRad) / ejectedGridSize), maxY = Int((vPos.y + vRad) / ejectedGridSize)
            for x in srvGridRange(minX, maxX) {
                for y in srvGridRange(minY, maxY) {
                    let key = SrvGridKey(x: x, y: y)
                    guard var bucket = staticEjectedGrid[key] else { continue }
                    var changed = false
                    var j = bucket.count - 1
                    while j >= 0 {
                        let mass = bucket[j]
                        let dx = mass.position.x - vPos.x
                        if dx < -vRad || dx > vRad { j -= 1; continue }
                        let dy = mass.position.y - vPos.y
                        if dy < -vRad || dy > vRad { j -= 1; continue }
                        if dx * dx + dy * dy < vRadSq {
                            feedVirusAndLaunchIfReady(at: v, with: mass, launched: &launched)
                            removedIDs.append(mass.id)
                            bucket.swapAt(j, bucket.count - 1)
                            bucket.removeLast()
                            changed = true
                        }
                        j -= 1
                    }
                    if changed {
                        if bucket.isEmpty { staticEjectedGrid.removeValue(forKey: key) }
                        else { staticEjectedGrid[key] = bucket }
                    }
                }
            }
            v -= 1
        }

        if !launched.isEmpty {
            viruses.append(contentsOf: launched)
            events.append(.virusesChanged)
        }
        if !removedIDs.isEmpty { events.append(.ejectedRemoved(ids: removedIDs)) }
    }

    /// v5.8.9: remove every ejected pellet inside a bubble (drill staging
    /// sweeps leftover spray out of the arena — with touch capture the staged
    /// pieces would otherwise hoover it instantly and skew the rep's masses
    /// and the recorded data). Emits ejectedRemoved so online clients prune.
    func removeEjected(near point: SrvVec2, radius: Double) {
        var removed: [UInt32] = []
        activeEjected.removeAll { m in
            if m.position.dist(point) < radius { removed.append(m.id); return true }
            return false
        }
        for (key, bucket) in staticEjectedGrid {
            var b = bucket
            b.removeAll { m in
                if m.position.dist(point) < radius { removed.append(m.id); return true }
                return false
            }
            if b.count != bucket.count {
                if b.isEmpty { staticEjectedGrid.removeValue(forKey: key) }
                else { staticEjectedGrid[key] = b }
            }
        }
        if !removed.isEmpty { events.append(.ejectedRemoved(ids: removed)) }
    }

    private func updateEjectedFlight(dt: Double) {
        let timeScale = dt * 60.0
        let decay = pow(0.96, timeScale)
        var i = activeEjected.count - 1
        while i >= 0 {
            let distanceStep = activeEjected[i].currentSpeed * dt
            activeEjected[i].position.x += activeEjected[i].direction.x * distanceStep
            activeEjected[i].position.y += activeEjected[i].direction.y * distanceStep
            let unclamped = activeEjected[i].position
            activeEjected[i].position = borderSafeEjectedPosition(unclamped)
            let hitV = activeEjected[i].position.x != unclamped.x
            let hitH = activeEjected[i].position.y != unclamped.y
            activeEjected[i].currentSpeed *= decay
            if hitV || hitH {
                var tangent = activeEjected[i].direction
                if hitV { tangent.x = 0 }
                if hitH { tangent.y = 0 }
                let retained = (tangent.x * tangent.x + tangent.y * tangent.y).squareRoot()
                if retained > 0.001 {
                    activeEjected[i].direction = tangent.normalized()
                    activeEjected[i].currentSpeed *= min(1, retained)
                } else {
                    activeEjected[i].currentSpeed = 0
                }
            }
            if activeEjected[i].currentSpeed <= 10.0 {
                activeEjected[i].isStatic = true
                let key = SrvGridKey(x: Int(activeEjected[i].position.x / ejectedGridSize),
                                  y: Int(activeEjected[i].position.y / ejectedGridSize))
                staticEjectedGrid[key, default: []].append(activeEjected[i])
                activeEjected.swapAt(i, activeEjected.count - 1)
                activeEjected.removeLast()
            }
            i -= 1
        }
    }

    private func updateMassAbsorption(dt: Double) {
        let absorptionRate = srvLerpFactor(base: 0.15, dt: dt)
        for i in cells.indices where cells[i].massToAbsorb > 0 {
            let add = cells[i].massToAbsorb * absorptionRate
            cells[i].targetMass += add
            cells[i].massToAbsorb -= add
            if cells[i].massToAbsorb < 0.1 { cells[i].massToAbsorb = 0 }
        }
    }

    private func updateCellState(dt: Double) {
        let animFactor = srvLerpFactor(base: SrvRules.baseAnimationFactor, dt: dt)
        let decayFactor = 1.0 - srvLerpFactor(base: 0.1, dt: dt)
        for i in cells.indices {
            if cells[i].targetMass > 10 {
                // Exact IPA adapted decay from agar.io (0x10004b8a4 + 0x10004bfc8):
                // t = clamp((sqrt(mass) - 20) / (150 - 20), 0, 1), rate = 0.99998 + (0.99922 - 0.99998) * t
                let massSqrt = cells[i].targetMass.squareRoot()
                let t = min(1.0, max(0.0, (massSqrt - 20.0) / 130.0))
                let rate = 0.99998 + (0.99922 - 0.99998) * t
                cells[i].targetMass *= pow(rate, 100.0 * dt)
            }
            if cells[i].mergeTimer > 0 {
                cells[i].mergeTimer -= dt
                if cells[i].mergeTimer <= 0 { cells[i].canMerge = true; cells[i].mergeTimer = 0 }
            } else {
                cells[i].canMerge = true
            }
            // v5.8 soft cap, v5.8.2 fix: the animated mass lerps toward the
            // target, so if the target decays immediately the visible mass
            // never climbs more than ~300 over the cap no matter the bite.
            // Now the full spike HOLDS until the animated mass has climbed
            // most of it (so a 30k bite really shows ~28k+), then the excess
            // burns off fast (~0.1s) with the mass snapped down along with it.
            if cells[i].targetMass > SrvRules.maxPlayerMass {
                let excess = cells[i].targetMass - SrvRules.maxPlayerMass
                if cells[i].mass >= SrvRules.maxPlayerMass + excess * 0.6 {
                    // v5.8.4: snappier deflate — excess halves every tick and the
                    // animated mass is yanked down with it (~0.1s descent).
                    cells[i].targetMass = SrvRules.maxPlayerMass + excess * pow(1e-18, dt)
                    cells[i].mass += (cells[i].targetMass - cells[i].mass) * srvLerpFactor(base: 0.5, dt: dt)
                }
            }
            if owners[cells[i].ownerID]?.isBot == true && cells[i].mass > 500 {
                cells[i].targetMass *= (1.0 - 0.0001 * dt)
            }
            cells[i].mass += (cells[i].targetMass - cells[i].mass) * animFactor
            if cells[i].isMerging {
                cells[i].mass *= decayFactor
            }
            cells[i].refreshCache()
        }
        var i = cells.count - 1
        while i >= 0 {
            if cells[i].isMerging && cells[i].mass < 1 {
                cells.remove(at: i)
            }
            i -= 1
        }
    }

    private func handleCellMerging(dt: Double) {
        guard cells.count > 1 else { return }
        var groups: [UInt32: [Int]] = [:]
        var hasMerging = false
        for i in cells.indices {
            if cells[i].isMerging { hasMerging = true }
            else if cells[i].mergeTimer <= 0 && cells[i].canMerge {
                groups[cells[i].ownerID, default: []].append(i)
            }
        }
        if groups.isEmpty && !hasMerging { return }

        var mergedMasses: [UInt32: Double] = [:]
        for (_, groupIndices) in groups {
            guard groupIndices.count > 1 else { continue }
            for first in 0..<(groupIndices.count - 1) {
                let a = groupIndices[first]
                if cells[a].isMerging { continue }
                for second in (first + 1)..<groupIndices.count {
                    let b = groupIndices[second]
                    if cells[a].isMerging || cells[b].isMerging { continue }
                    let bigIdx = cells[a].mass >= cells[b].mass ? a : b
                    let smallIdx = bigIdx == a ? b : a
                    let threshold = cells[bigIdx].cachedRadius - cells[smallIdx].cachedRadius * 0.3
                    guard threshold > 0 else { continue }
                    let dx = cells[smallIdx].position.x - cells[bigIdx].position.x
                    if dx < -threshold || dx > threshold { continue }
                    let dy = cells[smallIdx].position.y - cells[bigIdx].position.y
                    if dy < -threshold || dy > threshold { continue }
                    if dx * dx + dy * dy >= threshold * threshold { continue }
                    let bigID = cells[bigIdx].id
                    cells[smallIdx].isMerging = true
                    cells[smallIdx].mergeTargetID = bigID
                    mergedMasses[bigID, default: 0] += cells[smallIdx].targetMass
                    cells[smallIdx].targetMass = 0
                    hasMerging = true
                }
            }
        }
        if !mergedMasses.isEmpty {
            var indexByID: [UInt32: Int] = [:]
            for i in cells.indices { indexByID[cells[i].id] = i }
            for (id, mass) in mergedMasses {
                if let index = indexByID[id] {
                    // v5.8: no hard clamp — the soft cap decays the overshoot
                    cells[index].targetMass += mass
                }
            }
        }
        if hasMerging {
            let mergeSpeedFactor = srvLerpFactor(base: 0.25, dt: dt)
            var positions: [UInt32: SrvVec2] = [:]
            for c in cells { positions[c.id] = c.position }
            var i = cells.count - 1
            while i >= 0 {
                if cells[i].isMerging {
                    if let targetID = cells[i].mergeTargetID, let targetPos = positions[targetID] {
                        let dx = targetPos.x - cells[i].position.x
                        let dy = targetPos.y - cells[i].position.y
                        if dx * dx + dy * dy < 25 {
                            cells.remove(at: i)
                        } else {
                            cells[i].position.x += dx * mergeSpeedFactor
                            cells[i].position.y += dy * mergeSpeedFactor
                            cells[i].mass *= (1.0 - mergeSpeedFactor)
                            cells[i].refreshCache()
                        }
                    } else {
                        cells.remove(at: i)
                    }
                }
                i -= 1
            }
        }
    }

    // MARK: - Classic bot brain (port of the v24 rewritten brain, solo core)

    struct BotOwnerFrame {
        var brainIndex: Int
        var mass: Double
        var weightedX: Double
        var weightedY: Double
        var count: Int
        var skill: Double
    }

    /// v3: last action emitted by the RL2/expert controller for an owner
    /// (exact labels for expert demo collection and DAgger prev-action chains).
    func rl2BotLastAction(_ ownerID: UInt32) -> [Double]? {
        rl2Controller?.lastAction(ownerID)
    }

    /// v6.2.1: wipe an owner's recurrent policy state (fresh mind). Used by
    /// the exam between reps so each rep is an independent measurement.
    func resetBotMind(_ ownerID: UInt32) {
        rl2Controller?.resetState(ownerID)
    }

    /// v4.3: an optional target point makes EVERY cell launch at the victim
    /// (executeSplit aims per-cell), instead of all cells sharing one
    /// direction computed from the owner centre — the main split-aim fix.
    func queueBotSplit(ownerID: UInt32, direction: SrvVec2, toward target: SrvVec2? = nil) {
        pendingBotSplits.append((ownerID, direction, target))
    }

    private func updateClassicBotAI(dt: Double, index: SrvCellIndex) {
        let ws = SrvRules.worldSize
        let globalSkill = max(0.3, min(2.0, settings.botSkill))

        var frames: [UInt32: BotOwnerFrame] = [:]
        for i in cells.indices {
            guard let owner = owners[cells[i].ownerID], owner.isBot, owner.kind != .rlBot else { continue }
            let oid = cells[i].ownerID
            let skill = min(2.25, max(0.30, globalSkill * owner.skillTier.multiplier))
            let c = cells[i]
            if var f = frames[oid] {
                f.mass += c.mass
                f.weightedX += c.position.x * c.mass
                f.weightedY += c.position.y * c.mass
                f.count += 1
                if cells[f.brainIndex].mass < c.mass { f.brainIndex = i }
                frames[oid] = f
            } else {
                frames[oid] = BotOwnerFrame(brainIndex: i, mass: c.mass,
                                            weightedX: c.position.x * c.mass,
                                            weightedY: c.position.y * c.mass,
                                            count: 1, skill: skill)
            }
            cells[i].aiThinkTimer -= dt
            if cells[i].aiSplitCooldown > 0 { cells[i].aiSplitCooldown -= dt }
            if cells[i].aiFeedCooldown > 0 { cells[i].aiFeedCooldown -= dt }
        }

        // nearest human centre, for feed bots
        var humanCentres: [SrvVec2] = []
        var humanCentreByID: [UInt32: SrvVec2] = [:]   // v5.8: personal feeder targets
        for (oid, owner) in owners where owner.kind == .human {
            if let c = ownerCentre(oid) { humanCentres.append(c); humanCentreByID[oid] = c }
        }

        for (oid, frame) in frames {
            let brainIdx = frame.brainIndex
            guard cells[brainIdx].aiThinkTimer <= 0 else { continue }
            let brain = cells[brainIdx]
            guard let owner = owners[oid] else { continue }
            let skill = frame.skill
            // High skill means reliable awareness, not merely a lucky
            // personality roll. Ruthless reacts at ~30–45 ms; Normal stays
            // human-like without the old 200 ms blind windows.
            let reaction = 0.145 - 0.072 * min(1.6, skill)
            cells[brainIdx].aiThinkTimer = max(0.032, reaction) *
                Double.random(in: skill >= 1.2 ? 0.94...1.06 : 0.86...1.14)

            let myPos = brain.position
            let myMass = brain.mass
            let myTotal = frame.mass
            let myR = brain.cachedRadius
            let myCells = frame.count
            let groupCentre = SrvVec2(x: frame.weightedX / max(frame.mass, 0.0001),
                                   y: frame.weightedY / max(frame.mass, 0.0001))
            let groupSpread = groupCentre.dist(myPos)

            // v5.8 feed bots: run at their player and ALL-IN — close the gap,
            // then spam splits into them so the player inhales the pieces;
            // leftovers too small to split get ejected point-blank instead.
            if owner.kind == .feedBot {
                var target: SrvVec2? = nil
                if let tid = owner.feedTarget { target = humanCentreByID[tid] }
                if target == nil { target = humanCentres.min { $0.distSq(myPos) < $1.distSq(myPos) } }
                cells[brainIdx].aiFleeing = false
                if let target = target {
                    if frame.mass >= 60 {
                        cells[brainIdx].aiMode = .feedPlayer
                        cells[brainIdx].aiSteerTarget = target
                        let dist = target.dist(myPos)
                        // a split piece launches ~3.6 radii + a bit; only
                        // all-in once the payload actually lands on them
                        let splitReach = myR * 3.6 + 200
                        if dist > 1, dist < splitReach, cells[brainIdx].aiFeedCooldown <= 0 {
                            if myCells < settings.maxCellsPerOwner,
                               brain.targetMass >= SrvRules.minSplitMass {
                                executeSplit(ownerID: oid, direction: .zero, toward: target)
                                cells[brainIdx].aiFeedCooldown = 0.12
                            } else if dist < myR + 120 {
                                // on top of the player, nothing left to split:
                                // drain the rest as point-blank pellets
                                if ejectMassFromBotOwner(oid, toward: target,
                                                         burstPresses: 2, reserveMass: 16) > 0 {
                                    cells[brainIdx].aiFeedCooldown = 0.08
                                }
                            }
                        }
                    } else {
                        cells[brainIdx].aiMode = .forage
                        cells[brainIdx].aiSteerTarget = foodGrid.bestFoodCluster(near: myPos, searchBuckets: 4) ?? target
                    }
                } else {
                    cells[brainIdx].aiMode = .forage
                    cells[brainIdx].aiSteerTarget = foodGrid.bestFoodCluster(near: myPos, searchBuckets: 4)
                }
                continue
            }

            // v8: plan-based utility brain (SrvBotMind.swift) — perception,
            // candidate scoring, committed plans, trick state machines.
            botMind.think(world: self, oid: oid, brainIdx: brainIdx, frame: frame,
                          skill: skill, index: index)
        }

        // steering — every classic-bot cell, every frame
        for i in cells.indices {
            let oid = cells[i].ownerID
            guard let frame = frames[oid] else { continue }
            let brainIdx = frame.brainIndex
            let mode = cells[brainIdx].aiMode
            let skill = frame.skill
            var desired = SrvVec2.zero
            // ONE owner-level world cursor, exactly like a human. Never let a
            // largest-cell/brain swap look like independently controlled cells.
            let sharedTarget = botMind.states[oid]?.moveTarget ??
                               cells[brainIdx].aiSteerTarget
            if let t = sharedTarget {
                desired = SrvVec2(x: t.x - cells[i].position.x, y: t.y - cells[i].position.y).normalized()
            }
            if frame.count > 1, frame.mass > 0 {
                let cx = (frame.weightedX / frame.mass) - cells[i].position.x
                let cy = (frame.weightedY / frame.mass) - cells[i].position.y
                let cohesion = SrvVec2(x: cx, y: cy).normalized()
                var pull = 0.04
                switch mode {
                case .regroup: pull = cells[i].canMerge ? 2.2 : 0.45
                case .flee: pull = cells[i].canMerge ? 0.9 : 0.06
                case .hunt: pull = cells[i].canMerge ? 0.5 : 0.05
                case .travel:
                    // A human cannot steer split pieces independently toward
                    // their centre. Pre-merge cohesion here was the hidden
                    // behaviour that made travel pieces collapse unnaturally.
                    pull = 0
                case .hold, .trick: pull = cells[i].canMerge ? 1.6 : 0.30
                default: pull = cells[i].canMerge ? 1.2 : 0.04
                }
                desired.x += cohesion.x * pull
                desired.y += cohesion.y * pull
            }
            // v8.4 hold: hold PINS the cursor, it does not freeze the owner.
            // Exactly like a human parking the mouse on the receiver: every
            // piece keeps walking onto the cursor at full speed and only the
            // pieces that have actually arrived stand still. The old blanket
            // damp froze all cells, so centre-feed stacks never compacted and
            // bots visibly stood around doing nothing.
            let holdMode = mode == .hold
            var arrived = false
            if let t = sharedTarget {
                if holdMode {
                    let stopR = max(30.0, cells[i].cachedRadius * 0.30)
                    if cells[i].position.dist(t) < stopR { arrived = true }
                } else if i == brainIdx, cells[i].position.dist(t) < 30 {
                    arrived = true
                }
            }
            if arrived && (holdMode || desired.x * desired.x + desired.y * desired.y < 0.05) {
                let damp = 1.0 - srvLerpFactor(base: 0.35, dt: dt)
                cells[i].aiMovementDirection = SrvVec2(x: cells[i].aiMovementDirection.x * damp,
                                                    y: cells[i].aiMovementDirection.y * damp)
                continue
            }
            if desired == .zero {
                desired = cells[i].aiMovementDirection == .zero
                    ? SrvVec2(x: 1, y: 0) : cells[i].aiMovementDirection
            }
            let targetDir = desired.normalized()
            let current = cells[i].aiMovementDirection
            let turnBase = min(0.55, (mode == .flee ? 0.30 : 0.18) * max(0.5, min(1.6, skill)))
            let turn = srvLerpFactor(base: turnBase, dt: dt)
            var next = SrvVec2(x: current.x + (targetDir.x - current.x) * turn,
                            y: current.y + (targetDir.y - current.y) * turn)
            // Gentle final approach onto a pinned hold cursor: full speed in,
            // easing over the last stretch, so pieces don't overshoot, get
            // shoved, and ping-pong back (read as oscillation in soaks).
            if holdMode, let t = sharedTarget {
                let stopR = max(30.0, cells[i].cachedRadius * 0.30)
                let cap = min(1.0, cells[i].position.dist(t) / (stopR * 2.5))
                next = SrvVec2(x: next.x * cap, y: next.y * cap)
            }
            cells[i].aiMovementDirection = next
        }
    }
}

