//
//  SrvBotMind.swift — v8 utility-tree brain for classic (scripted) bots.
//
//  Replaces the old additive-vector intent block in updateClassicBotAI with a
//  plan-based utility AI:
//    perceive -> generate candidate plans -> score by persona -> COMMIT ->
//    execute a small state machine until done or aborted.
//
//  Design rules (from Hudson, 2026-08-22):
//   * No jerky back-and-forth: conflicts are resolved at the PLAN level
//     (pick "detour left" / "split away" / "pass through" ONCE and commit),
//     never by adding opposing steering vectors every frame.
//   * No virus camping: hiding behind a virus has a hard time budget and a
//     loiter meter penalises any plan that keeps a bot parked near a virus.
//   * Personas: each bot draws an archetype (greedy / survivor / hunter /
//     showman / balanced) + weight jitter from its owner id, so two bots in
//     the same spot make different choices. Skill tier gates which tricks a
//     bot even knows and how precisely it executes them.
//
//  The whole file is self-contained on top of the sim (SrvWorld / SrvVec2 / SrvRules)
//  so gen_nearbysim.py can carry it to the iPad nearby host unchanged.
//


final class SrvBotMind {

    // MARK: - Persona

    enum Archetype: UInt8, CaseIterable { case greedy, survivor, hunter, showman, balanced }

    struct Persona {
        var archetype: Archetype
        var wMass: Double
        var wSafety: Double
        var wSpeed: Double
        var wStyle: Double
        var patience: Double        // seconds of setup it tolerates
        var trickLevel: Int         // 0 rookie ... 4 elite
        var macroPresses: Int       // eject presses per burst (macro speed)
        var ejectControl: Double    // 0..1 pellet speed-control precision
        var aimJitter: Double       // radians of split-aim error
    }

    /// Deterministic per-owner persona: same bot keeps its personality for
    /// its whole life (and across respawns of the same owner id).
    static func makePersona(owner: SrvOwner, skill: Double, globalSkill: Double) -> Persona {
        var h = UInt64(owner.id) &* 0x9E3779B97F4A7C15
        func roll() -> Double {           // deterministic 0..1 stream
            h ^= h >> 33; h = h &* 0xFF51AFD7ED558CCD; h ^= h >> 33
            return Double(h % 10_000) / 10_000.0
        }
        let baseTier: Int
        switch owner.skillTier {
        case .rookie: baseTier = 0
        case .casual: baseTier = 1
        case .skilled: baseTier = 2
        case .expert: baseTier = 3
        case .elite: baseTier = 4
        }
        // The lobby slider is a real competence floor, not just reaction
        // speed. Normal bots know core mechanics; Ruthless bots ALL get the
        // elite vocabulary while personalities still vary their choices.
        let floorTier = globalSkill >= 1.45 ? 4 : globalSkill >= 1.20 ? 3
                      : globalSkill >= 0.90 ? 2 : globalSkill >= 0.65 ? 1 : 0
        let tier = max(baseTier, floorTier)
        let pick = roll()
        let arch: Archetype
        if tier >= 3 && pick < 0.22 { arch = .showman }
        else if pick < 0.25 { arch = .greedy }
        else if pick < 0.45 { arch = owner.aiCaution > 0.55 ? .survivor : .hunter }
        else if pick < 0.65 { arch = owner.aiAggression > 0.55 ? .hunter : .survivor }
        else { arch = .balanced }
        var wMass = 1.0, wSafety = 1.0, wSpeed = 1.0, wStyle = 0.6
        switch arch {
        case .greedy:   wMass = 1.35; wSafety = 0.55; wSpeed = 0.95; wStyle = 0.40
        case .survivor: wMass = 0.70; wSafety = 1.55; wSpeed = 0.60; wStyle = 0.30
        case .hunter:   wMass = 1.10; wSafety = 0.60; wSpeed = 1.15; wStyle = 0.60
        case .showman:  wMass = 0.85; wSafety = 0.70; wSpeed = 0.80; wStyle = 1.45
        case .balanced: wMass = 1.0;  wSafety = 1.0;  wSpeed = 1.0;  wStyle = 0.70
        }
        // personal jitter +-15% and aggression/caution modulation
        wMass   *= (0.85 + roll() * 0.30) * (0.85 + owner.aiAggression * 0.30)
        wSafety *= (0.85 + roll() * 0.30) * (0.70 + owner.aiCaution * 0.60)
        wSpeed  *= 0.85 + roll() * 0.30
        wStyle  *= 0.85 + roll() * 0.30
        let presses = max(1, min(6, Int(1.0 + skill * 1.4 + Double(tier) * 0.7)))
        return Persona(archetype: arch, wMass: wMass, wSafety: wSafety,
                       wSpeed: wSpeed, wStyle: wStyle,
                       patience: 1.6 + roll() * 3.4 + Double(tier) * 0.6,
                       trickLevel: tier,
                       macroPresses: presses,
                       ejectControl: min(1.0, 0.30 + Double(tier) * 0.16 + roll() * 0.1),
                       aimJitter: max(0, 1.25 - min(max(skill, globalSkill * 0.9), 1.25)) * 0.16)
    }

    // MARK: - Plans

    enum Kind: UInt8 {
        case roam, forage, regroup, recombine,
             hunt, splitKill, bait, travel, virusShoot, escape
    }

    // recombine variants
    static let recCentre = 0, recWall = 1, recMoving = 2, recInsta = 3
    // splitKill variants
    static let skSingle = 0, skDouble = 1, skMacroDouble = 2
    // travel variants
    static let tvPlain = 0, tvSplitRun = 1, tvMacroSplitRun = 2, tvWallRun = 3
    // escape variants
    static let esRun = 0, esDetour = 1, esThrough = 2, esSplitAway = 3,
               esSurf = 4, esHide = 5

    struct Plan {
        var kind: Kind = .roam
        var variant: Int = 0
        var stage: Int = 0
        var stageT: Double = 0
        var bornAt: Double = 0
        var commitUntil: Double = 0
        var target: SrvVec2 = .zero
        var enemyOwner: UInt32? = nil
        var enemyCell: UInt32? = nil
        var virusID: UInt32? = nil
        var side: Double = 1
        var invested: Double = 0
        var baseCellCount: Int = 0
        var score: Double = 0
    }

    struct BotState {
        var persona: Persona
        var plan = Plan()
        var loiter: Double = 0            // virus-camp meter (seconds-ish)
        var loiterVirus: UInt32? = nil
        var loiterDist: Double = 1e9
        var lastDir = SrvVec2.zero           // anti-jitter metric sampling
        var sampleT: Double = 0
        var oscillations: Int = 0         // reversal within 1.5s of a reversal
        var lastReversalAt: Double = -1e9
        var escapeLane = SrvVec2.zero        // committed flee lane (anti-flip)
        var banVirus: UInt32? = nil       // over-loitered virus: no hide/through
        var banUntil: Double = 0
        var postEscapeUntil: Double = 0   // just fled: don't sprint straight back
        var lastRecombineAt: Double = -1e9
        var recStartShare: Double = 0     // largest-cell mass share when recombine began
        var macroStartResolved: Int = 0
        var macroStartOrphaned: Int = 0
        var moveTarget = SrvVec2.zero         // one shared player-style cursor target
        var lastMacroAt: Double = -1e9
        var lastMacroTarget = SrvVec2.zero
        var roamTarget = SrvVec2.zero
        var roamUntil: Double = 0
        var planLockUntil: Double = 0
        var huntOwner: UInt32? = nil
        var huntTarget = SrvVec2.zero
        var lastTargetDir = SrvVec2.zero
        var reversals: Int = 0
        var thinkSeconds: Double = 0
        var lastThinkAt: Double = 0
        // v8.3 exam/diagnostic telemetry. The old lobby soak only proved a
        // trick happened somewhere; it could not tell us that ordinary bots
        // spent nearly every decision chasing and almost never offered one.
        var decisions = 0
        var planChoices: [String: Int] = [:]
        var trickOpportunities: [String: Int] = [:]
        var trickChoices: [String: Int] = [:]
        // A trick family owns the next suitable window in a rotating deck.
        // This prevents the utility scalar from selecting the same safe
        // centre-feed forever while doubles, travel mechanics and wall play
        // exist only as theoretical candidates.
        var trickDeckIndex = 0
        var lastVisibleTrickAt = -1e9
        var forcedVirusExitUntil = -1e9
        var recombineReceiver: UInt32? = nil
        var recombineFeedDone = false
        var lastSplitAt = -1e9
    }

    var states: [UInt32: BotState] = [:]
    /// Trick counters, read by the `bottest` soak harness.
    var stats: [String: Int] = [:]
    var sharedCursorViolations = 0
    @inline(__always) private func bump(_ key: String) { stats[key, default: 0] += 1 }
    @inline(__always) private func planKey(_ p: Plan) -> String {
        switch p.kind {
        case .recombine: return p.variant == SrvBotMind.recWall ? "wallrecombine" : "centrerecombine"
        case .splitKill:
            if p.variant == SrvBotMind.skMacroDouble { return "macrodouble" }
            if p.variant == SrvBotMind.skDouble { return "doublesplit" }
            return "splitkill"
        case .travel:
            if p.variant == SrvBotMind.tvMacroSplitRun { return "macrosplitrun" }
            if p.variant == SrvBotMind.tvWallRun { return "wallrun" }
            if p.variant == SrvBotMind.tvSplitRun { return "splitrun" }
            return "travel"
        case .bait: return "bait"
        default: return String(describing: p.kind)
        }
    }
    @inline(__always) private func isTrick(_ p: Plan) -> Bool {
        p.kind == .recombine || p.kind == .splitKill || p.kind == .bait ||
        (p.kind == .travel && p.variant != SrvBotMind.tvPlain)
    }
    private let trickDeck = [
        "splitkill", "doublesplit", "macrodouble", "centrerecombine",
        "macrosplitrun", "wallrecombine", "splitrun", "wallrun", "bait"
    ]

    // MARK: - Perception

    struct Threat {
        var pos = SrvVec2.zero, vel = SrvVec2.zero
        var mass = 0.0, dist = 1e9
        var canSplitKill = false
        var ownerID: UInt32 = 0
        var severity = 0.0
    }
    struct Prey {
        var id: UInt32 = 0, ownerID: UInt32 = 0
        var pos = SrvVec2.zero, vel = SrvVec2.zero
        var mass = 0.0, dist = 1e9
        var isBot = true, isFeedBot = false
        var ownerTotalNearby = 0.0
        var ownerCellsNearby = 0
    }
    struct Neutral {
        var ownerID: UInt32 = 0
        var pos = SrvVec2.zero
        var radius = 0.0
        var dist = 1e9
    }
    struct Sense {
        var threats: [Threat] = []
        var worst: Threat? = nil
        var threatScore = 0.0
        var fleeDir = SrvVec2.zero
        var prey: [Prey] = []
        var neutrals: [Neutral] = []
        var giants: [(ownerID: UInt32, pos: SrvVec2, mass: Double, dist: Double)] = []
        var viruses: [(id: UInt32, pos: SrvVec2, targetMass: Double, dist: Double, radius: Double)] = []
        var food: SrvVec2? = nil
        var pile: SrvVec2? = nil
        var token: SrvVec2? = nil
        var wallDist = 1e9
        var crowdMass = 0.0     // enemy mass nearby (any size)
    }

    private func perceive(world: SrvWorld, oid: UInt32, brain: SrvCell, frame: SrvWorld.BotOwnerFrame,
                          skill: Double, index: SrvCellIndex) -> Sense {
        let ws = SrvRules.worldSize
        var s = Sense()
        let myPos = brain.position
        let myMass = brain.mass
        let myR = brain.cachedRadius
        let owner = world.owners[oid]
        let caution = owner?.aiCaution ?? 0.5
        let perceptionScale = min(1.22, max(0.74, 0.74 + skill * 0.28))
        let perception = min(4200, (1450 + myR * 7) * perceptionScale)
        var enemyOwnerMass: [UInt32: (mass: Double, count: Int)] = [:]

        index.forEach(near: myPos, radius: perception) { other in
            if other.ownerID == oid { return }
            let rawDX = other.x - myPos.x, rawDY = other.y - myPos.y
            let rawDistSq = rawDX * rawDX + rawDY * rawDY
            if rawDistSq > perception * perception { return }
            let rawDist = max(rawDistSq.squareRoot(), 1)
            var e = enemyOwnerMass[other.ownerID] ?? (0, 0)
            e.mass += other.mass; e.count += 1
            enemyOwnerMass[other.ownerID] = e
            s.crowdMass += other.mass
            let lead = min(rawDist / 700.0, 1.2) * min(1.5, skill)
            let px = min(ws, max(0, other.x + other.vx * 60.0 * lead))
            let py = min(ws, max(0, other.y + other.vy * 60.0 * lead))
            let dx = px - myPos.x, dy = py - myPos.y
            let dist = max((dx * dx + dy * dy).squareRoot(), 40)
            let otherR = other.solidRadius

            if other.mass > myMass * 1.15 {
                if other.mass >= 200 { s.giants.append((other.ownerID, SrvVec2(x: other.x, y: other.y), other.mass, dist)) }
                let contact = otherR + myR
                let canSplitKill = (other.mass / 2.0) > myMass * 1.30
                let reach = canSplitKill ? (otherR * 4.2 + 240) : (contact * 1.7)
                if dist < reach {
                    var t = Threat()
                    t.pos = SrvVec2(x: other.x, y: other.y)
                    t.vel = SrvVec2(x: other.vx, y: other.vy)
                    t.mass = other.mass; t.dist = dist
                    t.canSplitKill = canSplitKill
                    t.ownerID = other.ownerID
                    var severity = (1.0 - dist / reach) * (0.55 + caution * 0.9)
                    if canSplitKill { severity *= 1.7 }
                    if !other.isBot { severity *= 1.15 }
                    t.severity = severity
                    s.threats.append(t)
                    s.threatScore += severity
                    s.fleeDir.x -= (dx / dist) * severity
                    s.fleeDir.y -= (dy / dist) * severity
                    if s.worst == nil || t.mass > s.worst!.mass { s.worst = t }
                }
            } else if myMass > other.mass * 1.22 {
                var p = Prey()
                p.id = other.id; p.ownerID = other.ownerID
                p.pos = SrvVec2(x: px, y: py)
                p.vel = SrvVec2(x: other.vx, y: other.vy)
                p.mass = other.mass; p.dist = dist
                p.isBot = other.isBot; p.isFeedBot = other.isFeedBot
                s.prey.append(p)
            } else if dist < myR + otherR + 900 {
                s.neutrals.append(Neutral(ownerID: other.ownerID,
                                          pos: SrvVec2(x: other.x, y: other.y),
                                          radius: otherR, dist: dist))
            }
        }
        for i in s.prey.indices {
            let e = enemyOwnerMass[s.prey[i].ownerID] ?? (0, 0)
            s.prey[i].ownerTotalNearby = e.mass
            s.prey[i].ownerCellsNearby = e.count
        }
        s.prey.sort { $0.dist < $1.dist }
        if s.prey.count > 10 { s.prey.removeLast(s.prey.count - 10) }
        s.neutrals.sort { $0.dist < $1.dist }
        if s.neutrals.count > 6 { s.neutrals.removeLast(s.neutrals.count - 6) }

        for v in world.viruses {
            let d = v.position.dist(myPos)
            if d < 2200 {
                s.viruses.append((v.id, v.position, v.targetMass, d, v.radius))
            }
        }
        s.viruses.sort { $0.dist < $1.dist }
        s.food = world.foodGrid.bestFoodCluster(near: myPos, searchBuckets: 4)
        s.pile = world.nearestStaticEjected(near: myPos, radius: 1100)
        s.token = world.nearestToken(near: myPos, radius: 1300)
        s.wallDist = min(myPos.x, ws - myPos.x, myPos.y, ws - myPos.y)
        return s
    }

    // MARK: - Geometry helpers

    /// First virus whose disc blocks the corridor from `from` toward `dir`
    /// within `length` (corridor width = cell radius + margin).
    private func virusBlockingLane(_ sense: Sense, from: SrvVec2, dir: SrvVec2,
                                   length: Double, myR: Double) -> (id: UInt32, pos: SrvVec2, radius: Double)? {
        guard dir != .zero else { return nil }
        for v in sense.viruses {
            let rel = SrvVec2(x: v.pos.x - from.x, y: v.pos.y - from.y)
            let along = rel.x * dir.x + rel.y * dir.y
            if along < 0 || along > length { continue }
            let perp = abs(rel.x * dir.y - rel.y * dir.x)
            if perp < v.radius + myR + 24 { return (v.id, v.pos, v.radius) }
        }
        return nil
    }

    @inline(__always)
    private func clampTarget(_ t: SrvVec2) -> SrvVec2 {
        let m = 120.0, ws = SrvRules.worldSize
        return SrvVec2(x: min(ws - m, max(m, t.x)), y: min(ws - m, max(m, t.y)))
    }

    // MARK: - Main entry (called on the brain cell's think cadence)

    func think(world: SrvWorld, oid: UInt32, brainIdx: Int, frame: SrvWorld.BotOwnerFrame,
               skill: Double, index: SrvCellIndex) {
        guard let owner = world.owners[oid] else { return }
        let now = world.time
        var st = states[oid] ?? BotState(persona: SrvBotMind.makePersona(
            owner: owner, skill: skill, globalSkill: world.settings.botSkill))
        let dtThink = st.lastThinkAt > 0 ? min(0.5, now - st.lastThinkAt) : 0.1
        st.lastThinkAt = now
        st.thinkSeconds += dtThink
        let brain = world.cells[brainIdx]
        let sense = perceive(world: world, oid: oid, brain: brain, frame: frame,
                             skill: skill, index: index)
        // Structural invariant: only the owner-state target is authoritative.
        // Clear stale targets on former brain cells when largest mass changes.
        for i in world.cells.indices where world.cells[i].ownerID == oid && i != brainIdx {
            world.cells[i].aiSteerTarget = nil
        }

        // ---- anti-jitter metric (direction reversals per bot-minute)
        st.sampleT += dtThink
        if st.sampleT >= 0.30 {
            let d = brain.aiMovementDirection
            if d != .zero && st.lastDir != .zero {
                let dot = d.normalized().x * st.lastDir.x + d.normalized().y * st.lastDir.y
                // Count only a genuine near-U-turn. Tactical bends around
                // prey and viruses are normal play, not back/forth jitter.
                if dot < -0.65 {
                    st.reversals += 1
                    if now - st.lastReversalAt < 1.5 {
                        st.oscillations += 1   // back-AND-forth, the real jitter
                        bump("osc_\(st.plan.kind)_v\(st.plan.variant)")
                    }
                    st.lastReversalAt = now
                }
            }
            st.lastDir = d.normalized()
            st.sampleT = 0
        }

        // ---- virus-camp meter: parked near the same virus while not
        // actively farming/shooting it -> loiter grows; moving away decays it.
        if let v = sense.viruses.first,
           v.dist < min(brain.cachedRadius + v.radius + 220, max(420, brain.cachedRadius * 0.55 + v.radius + 160)) {
            let excused = st.plan.kind == .virusShoot && st.plan.virusID == v.id
            if st.loiterVirus == v.id && !excused {
                // Proximity alone is not camping: a large cell can remain
                // geometrically close while actively moving away. Accumulate
                // only when it fails to make outward progress.
                if v.dist > st.loiterDist + 2 {
                    st.loiter = max(0, st.loiter - dtThink * 2)
                } else {
                    st.loiter += dtThink
                }
            } else if st.loiterVirus != v.id {
                st.loiterVirus = v.id
                st.loiter = excused ? 0 : st.loiter * 0.5
            }
            st.loiterDist = v.dist
            if st.loiter > min(st.persona.patience, 4.0) + 1.5 {
                st.banVirus = v.id; st.banUntil = now + 10.0   // hard anti-camp
            }
            // Farming is gone: after a short accidental overlap, force a
            // committed exit even without an enemy. No plan may idle in one.
            if st.loiter > 3.0 && st.plan.kind != .escape {
                var away = SrvVec2(x: brain.position.x - v.pos.x,
                                y: brain.position.y - v.pos.y).normalized()
                if away == .zero { away = SrvVec2(x: 1, y: 0) }
                var exit = Plan()
                exit.kind = .travel; exit.variant = SrvBotMind.tvPlain
                exit.bornAt = now; exit.commitUntil = now + 2.0
                exit.target = clampTarget(SrvVec2(x: brain.position.x + away.x * 1200,
                                               y: brain.position.y + away.y * 1200))
                st.plan = exit
                st.forcedVirusExitUntil = now + 2.0
            }
        } else {
            st.loiter = max(0, st.loiter - dtThink * 2.0)
            if st.loiter == 0 {
                st.loiterVirus = nil
                st.loiterDist = 1e9
            }
        }

        // ---- escape is a hard override with hysteresis
        let fleeing = st.plan.kind == .escape
        let fleeEnter = fleeing ? 0.16 : 0.30
        if sense.threatScore > fleeEnter {
            escapeThink(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                        sense: sense, st: &st, now: now)
            if let target = world.cells[brainIdx].aiSteerTarget { st.moveTarget = target }
            states[oid] = st
            return
        } else if fleeing {
            st.plan = Plan()            // threat gone: fall through to re-plan
            st.postEscapeUntil = now + 2.5   // keep the lane; bias against U-turns
        }
        // ---- v8.6 pressure drift: a bigger cell parked at contact range is
        // never something to idle beside. Below the flee threshold nothing
        // used to force motion, so an arrived roam/forage damped the bot to a
        // vibrating standstill right next to Hudson. If a close giant is
        // watching and the current plan is not actively taking us anywhere,
        // swap in a committed walk-away.
        if sense.threatScore <= fleeEnter,
           let g = sense.giants.min(by: { $0.dist < $1.dist }),
           g.dist < brain.cachedRadius * 2.6 + 420 {
            let toTarget = SrvVec2(x: st.plan.target.x - brain.position.x,
                                y: st.plan.target.y - brain.position.y)
            let tLen = (toTarget.x * toTarget.x + toTarget.y * toTarget.y).squareRoot()
            let awayG = SrvVec2(x: brain.position.x - g.pos.x,
                             y: brain.position.y - g.pos.y).normalized()
            let idleKinds: Bool
            switch st.plan.kind {
            case .roam, .forage, .regroup, .travel: idleKinds = true
            default: idleKinds = false
            }
            let goingNowhere = tLen < 300
            let walkingIn = tLen >= 300 &&
                (toTarget.x / tLen) * awayG.x + (toTarget.y / tLen) * awayG.y < -0.5
            if idleKinds, goingNowhere || (st.plan.kind == .roam && walkingIn) {
                var drift = Plan()
                drift.kind = .travel; drift.variant = SrvBotMind.tvPlain
                drift.bornAt = now; drift.commitUntil = now + 1.6
                drift.target = clampTarget(SrvVec2(x: brain.position.x + awayG.x * 1100,
                                                y: brain.position.y + awayG.y * 1100))
                st.plan = drift
                bump("pressure_drift")
            }
        }
        if now < st.forcedVirusExitUntil {
            executePlan(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                        sense: sense, st: &st, now: now, dtThink: dtThink)
            if let target = world.cells[brainIdx].aiSteerTarget { st.moveTarget = target }
            states[oid] = st
            return
        }

        // ---- continue a live committed plan
        if st.plan.kind != .roam || st.plan.commitUntil > now {
            if planStillValid(world: world, oid: oid, brainIdx: brainIdx,
                              sense: sense, st: st, now: now) {
                executePlan(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                            sense: sense, st: &st, now: now, dtThink: dtThink)
                if let target = world.cells[brainIdx].aiSteerTarget { st.moveTarget = target }
                states[oid] = st
                return
            }
        }

        // ---- pick a new plan
        var best = candidatePlans(world: world, oid: oid, brainIdx: brainIdx,
                                  frame: frame, sense: sense, st: &st, now: now)
        best.bornAt = now
        st.decisions += 1
        st.planChoices[planKey(best), default: 0] += 1
        if isTrick(best) { st.trickChoices[planKey(best), default: 0] += 1 }
        st.plan = best
        st.planLockUntil = now + (best.kind == .forage ? 0.32 :
                                  best.kind == .hunt ? 0.18 :
                                  isTrick(best) ? 0.45 : 0.30)
        if best.kind == .roam {
            st.roamTarget = best.target
            st.roamUntil = best.commitUntil
        }
        executePlan(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                    sense: sense, st: &st, now: now, dtThink: dtThink)
        // Player parity: the owner chooses ONE world-space cursor. Every
        // piece's movement is derived from that same point in SrvWorld steering.
        if let target = world.cells[brainIdx].aiSteerTarget { st.moveTarget = target }
        states[oid] = st
    }

    // MARK: - Opportunity & split-safety (shared by validity + candidates)

    /// An armed, immediately-cashable kill: prey basically touching us, or
    /// prey inside a ready split's reach. Pausable plans (regroup, travel,
    /// a recombine that has not fed yet) must yield to this — standing
    /// still next to free mass is the opposite of pro play.
    private func armedOpportunity(_ sense: Sense, brain: SrvCell) -> Bool {
        let myR = brain.cachedRadius
        let half = brain.targetMass / 2
        for p in sense.prey {
            if p.dist < myR * 2.6 + 140, brain.mass > p.mass * 1.35 { return true }
            if brain.aiSplitCooldown <= 0, brain.targetMass >= SrvRules.minSplitMass * 2,
               half > p.mass * 1.30, p.dist < myR * 3.4 + 160 { return true }
        }
        return false
    }

    /// Committing halves/quarters into a lane where a bigger cell can punish
    /// them is the classic over-split. Directional: only cells near the
    /// piece landing zone (target / lane midpoint) veto — a giant safely
    /// behind us is not a reason to pass up a clean split. `pieces` is the
    /// piece count the split would leave (2 = single, 4 = double).
    private func splitPunishable(_ sense: Sense, brain: SrvCell, pieces: Double,
                                 toward t: SrvVec2) -> Bool {
        let pieceMass = brain.targetMass / pieces
        let mid = SrvVec2(x: (brain.position.x + t.x) * 0.5,
                       y: (brain.position.y + t.y) * 0.5)
        func nearLane(_ pos: SrvVec2, _ range: Double) -> Bool {
            min(pos.dist(t), pos.dist(mid)) < range
        }
        // anything bigger than us (giants covers cells too far to threaten
        // the WHOLE bot but plenty close enough to inhale the pieces)
        for g in sense.giants where g.mass > pieceMass * 1.20 {
            let canSplitPiece = g.mass / 2 > pieceMass * 1.30
            if nearLane(g.pos, canSplitPiece ? 1250 : 720) { return true }
        }
        // smaller-than-us cells that still out-mass a piece
        for p in sense.prey where p.mass > pieceMass * 1.15 && nearLane(p.pos, 700) {
            return true
        }
        // similar-size neighbours cannot eat US, but quarters are food
        if pieces >= 4, sense.neutrals.contains(where: { nearLane($0.pos, 780) }) {
            return true
        }
        return false
    }

    // MARK: - Plan validity (cheap abort checks)

    private func planStillValid(world: SrvWorld, oid: UInt32, brainIdx: Int,
                                sense: Sense, st: BotState, now: Double) -> Bool {
        let p = st.plan
        // hard time budget: nothing runs past its patience window
        let budget: Double
        switch p.kind {
        case .bait: budget = st.persona.patience * 4
        case .virusShoot: budget = st.persona.patience * 2.5
        case .recombine: budget = 2.5 + st.persona.patience * 2
        default: budget = st.persona.patience * 3
        }
        if now - p.bornAt > budget { return false }
        let locked = now < st.planLockUntil
        switch p.kind {
        case .roam:
            // Roam is merely a fallback heading, never a multi-second veto on
            // seeing a player or recognizing a newly-opened mechanic.
            return p.commitUntil > now && world.cells[brainIdx].position.dist(p.target) > 260 &&
                   sense.prey.isEmpty && sense.threats.isEmpty
        case .forage:
            if p.commitUntil <= now { return false }
            if locked { return true }
            // SrvFood is not a reason to stay blind to a real player or a safe
            // multi-cell setup. Re-open the utility tree immediately.
            if !sense.prey.isEmpty || world.ownerCellCount(oid) > 1 { return false }
            return p.variant == 1 ? sense.pile != nil
                 : p.variant == 0 ? sense.food != nil : sense.token != nil
        case .hunt, .splitKill, .bait:
            if locked { return true }
            guard let eo = p.enemyOwner else { return false }
            // target owner must still have nearby cells
            if !sense.prey.contains(where: { $0.ownerID == eo }) &&
               !sense.threats.contains(where: { $0.ownerID == eo }) { return false }
            if p.kind == .hunt {
                // A plain chase must periodically yield to the tactical tree.
                // Otherwise its 0.55s lock consumes every split window while
                // the bot visibly runs straight at the victim.
                return now - p.bornAt < 0.42
            }
            return true
        case .virusShoot:
            guard let vid = p.virusID else { return false }
            if st.banVirus == vid && st.banUntil > now { return false }
            return sense.viruses.contains { $0.id == vid }
        case .recombine:
            if sense.threatScore > 0.30 { return false }   // consolidate later, live now
            // Before any pellet is committed, a recombine is pausable: an
            // armed kill right next to us always outranks tidying up.
            if !st.recombineFeedDone, st.plan.stage == 0,
               armedOpportunity(sense, brain: world.cells[brainIdx]) {
                bump("interrupt_for_kill")
                return false
            }
            if now - st.lastSplitAt <= 1.05 { return false }
            if now - (world.owners[oid]?.bornAt ?? now) <= 3.0 { return false }
            return world.ownerCellCount(oid) > 1
        case .travel, .regroup:
            // Neither is a reason to walk past free mass: yield to an armed
            // kill as soon as the short lock lapses. Regroup also expires
            // like any plan instead of running to its whole time budget.
            if !locked, armedOpportunity(sense, brain: world.cells[brainIdx]) {
                bump("interrupt_for_kill")
                return false
            }
            return p.commitUntil > now
        case .escape:
            return true
        }
    }

    // MARK: - Escape (plan-level conflict resolution, committed variants)

    private func escapeThink(world: SrvWorld, oid: UInt32, brainIdx: Int,
                             frame: SrvWorld.BotOwnerFrame, sense: Sense,
                             st: inout BotState, now: Double) {
        let ws = SrvRules.worldSize
        let brain = world.cells[brainIdx]
        let myPos = brain.position
        let myR = brain.cachedRadius
        let myMass = brain.mass
        let popsOnVirus = myMass >= SrvRules.virusPopMinMass
        let persona = st.persona

        // keep an already-chosen escape variant committed for a beat so the
        // route cannot flip-flop; re-evaluate at most every 0.8s
        if st.plan.kind == .escape, st.plan.commitUntil > now {
            executeEscape(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                          sense: sense, st: &st, now: now)
            return
        }
        // sticky hide: while ducked behind a live virus with time budget left,
        // stay ducked — re-rolling the variant every beat was the main
        // back-and-forth jitter source for small bots.
        if st.plan.kind == .escape, st.plan.variant == SrvBotMind.esHide,
           st.loiter < min(st.persona.patience, 3.5),
           let w0 = sense.worst,
           let hv = sense.viruses.first(where: { $0.id == st.plan.virusID }) {
            let away = SrvVec2(x: hv.pos.x - w0.pos.x, y: hv.pos.y - w0.pos.y).normalized()
            let orbitR = hv.radius + brain.cachedRadius * 0.4
            let fresh = SrvVec2(x: hv.pos.x + away.x * orbitR, y: hv.pos.y + away.y * orbitR)
            // STRAFE around the virus toward the safe side (rotation-limited)
            // instead of jumping across it (that jump caused oscillation
            // whenever the circling threat flipped the safe side).
            if fresh.dist(st.plan.target) > 150 {
                let cur = atan2(st.plan.target.y - hv.pos.y, st.plan.target.x - hv.pos.x)
                let want = atan2(fresh.y - hv.pos.y, fresh.x - hv.pos.x)
                var d = want - cur
                while d > .pi { d -= 2 * .pi }
                while d < -.pi { d += 2 * .pi }
                let a = cur + max(-0.95, min(0.95, d))
                st.plan.target = SrvVec2(x: hv.pos.x + cos(a) * orbitR,
                                      y: hv.pos.y + sin(a) * orbitR)
            }
            st.plan.commitUntil = now + 0.5
            executeEscape(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                          sense: sense, st: &st, now: now)
            return
        }

        // base flee direction: away from threats + wall repulsion
        var dir = sense.fleeDir
        let edge = 900.0
        if myPos.x < edge { dir.x += (1 - myPos.x / edge) * 1.4 }
        if myPos.x > ws - edge { dir.x -= (1 - (ws - myPos.x) / edge) * 1.4 }
        if myPos.y < edge { dir.y += (1 - myPos.y / edge) * 1.4 }
        if myPos.y > ws - edge { dir.y -= (1 - (ws - myPos.y) / edge) * 1.4 }
        var lane = dir.normalized()
        if lane == .zero { lane = SrvVec2(x: ws / 2 - myPos.x, y: ws / 2 - myPos.y).normalized() }
        // v8.6 gap lane: when threats surround the bot the summed flee vector
        // cancels toward zero (ring) or points into a wall (corner pin), and
        // the bot froze in place / dived into a mouth — Hudson's "stand still
        // and vibrate". A weak or wall-blocked resultant now picks the lane
        // with the most CLEARANCE instead: sample 16 directions, keep threats
        // and walls off the whole path, prefer the committed lane.
        let rawMag = (dir.x * dir.x + dir.y * dir.y).squareRoot()
        let laneAhead = SrvVec2(x: myPos.x + lane.x * 700, y: myPos.y + lane.y * 700)
        let laneWallD = min(laneAhead.x, ws - laneAhead.x, laneAhead.y, ws - laneAhead.y)
        if !sense.threats.isEmpty,
           rawMag < max(0.45, sense.threatScore * 0.8) || laneWallD < myR + 60 {
            var bestLane = lane
            var bestScore = -1e18
            for k in 0..<16 {
                let a = Double(k) * .pi / 8
                let cand = SrvVec2(x: cos(a), y: sin(a))
                var sc = 0.0
                for f in [300.0, 650.0, 1000.0] {
                    let probe = SrvVec2(x: myPos.x + cand.x * f, y: myPos.y + cand.y * f)
                    var nearest = 1e9
                    for t in sense.threats { nearest = min(nearest, probe.dist(t.pos)) }
                    sc += min(nearest, 1400)
                    let wallD = min(probe.x, ws - probe.x, probe.y, ws - probe.y)
                    if wallD < myR + 40 { sc -= 4000 } else { sc += min(wallD, 420) * 0.4 }
                }
                if cand.x * st.escapeLane.x + cand.y * st.escapeLane.y > 0.5 { sc += 350 }
                if sc > bestScore { bestScore = sc; bestLane = cand }
            }
            lane = bestLane
        }
        // hard anti-camp: once a virus is banned (over-loitered), fleeing
        // actively pushes AWAY from it so a sieging whale can't pin us there.
        if let bv = st.banVirus, st.banUntil > now,
           let v = sense.viruses.first(where: { $0.id == bv }), v.dist < 620 {
            let awayV = SrvVec2(x: myPos.x - v.pos.x, y: myPos.y - v.pos.y).normalized()
            lane = SrvVec2(x: lane.x + awayV.x * 0.9, y: lane.y + awayV.y * 0.9).normalized()
        }
        // anti-flip: two threats sandwiching a bot make the raw flee vector
        // swing 180 degrees between thinks — the root cause of jerky
        // back-and-forth. Keep the committed lane unless the new one is
        // roughly compatible (or the old one runs into a wall).
        if st.plan.kind == .escape, st.escapeLane != .zero {
            let dot = lane.x * st.escapeLane.x + lane.y * st.escapeLane.y
            if dot < -0.15 {
                let ahead = SrvVec2(x: myPos.x + st.escapeLane.x * 420,
                                 y: myPos.y + st.escapeLane.y * 420)
                let wallAhead = min(ahead.x, ws - ahead.x, ahead.y, ws - ahead.y) < 160
                if !wallAhead { lane = st.escapeLane }
            } else {
                lane = SrvVec2(x: st.escapeLane.x * 0.65 + lane.x * 0.35,
                            y: st.escapeLane.y * 0.65 + lane.y * 0.35).normalized()
            }
        }
        st.escapeLane = lane

        var plan = Plan()
        plan.kind = .escape
        plan.bornAt = st.plan.kind == .escape ? st.plan.bornAt : now
        plan.variant = SrvBotMind.esRun
        plan.commitUntil = now + 0.8

        let cornered = sense.wallDist < myR * 1.8 && sense.threatScore > 0.55
        let worst = sense.worst

        if let blocker = virusBlockingLane(sense, from: myPos, dir: lane,
                                           length: 760, myR: myR) {
            let banned = st.banVirus == blocker.id && st.banUntil > now
            if !popsOnVirus && !banned {
                // small cells pass straight through/behind the virus — the
                // pursuer (usually poppable) has to break off or shatter.
                plan.variant = SrvBotMind.esThrough
                plan.virusID = blocker.id
                plan.target = SrvVec2(x: blocker.pos.x + lane.x * 620,
                                   y: blocker.pos.y + lane.y * 620)
                if st.plan.variant != plan.variant { bump("escape_through") }
            } else if persona.trickLevel >= 3, cornered, blocker.pos.dist(myPos) < 500,
                      let w = worst, w.canSplitKill {
                // last resort: deliberately shatter on the virus — a 16-way
                // scatter beats being inhaled whole.
                plan.variant = SrvBotMind.esSurf
                plan.virusID = blocker.id
                plan.target = blocker.pos
                if st.plan.variant != plan.variant { bump("escape_surf") }
            } else {
                // committed tangent detour around the virus; side chosen ONCE
                let toV = SrvVec2(x: blocker.pos.x - myPos.x, y: blocker.pos.y - myPos.y)
                let cross = lane.x * toV.y - lane.y * toV.x
                var side: Double = cross > 0 ? -1 : 1     // steer to the empty side
                if st.plan.kind == .escape, st.plan.variant == SrvBotMind.esDetour,
                   st.plan.virusID == blocker.id { side = st.plan.side }
                plan.variant = SrvBotMind.esDetour
                plan.virusID = blocker.id
                plan.side = side
                let perp = SrvVec2(x: -lane.y * side, y: lane.x * side)
                let clearance = blocker.radius + myR + 170
                plan.target = SrvVec2(x: blocker.pos.x + perp.x * clearance + lane.x * 260,
                                   y: blocker.pos.y + perp.y * clearance + lane.y * 260)
                plan.commitUntil = now + 1.1
                if st.plan.variant != plan.variant { bump("escape_detour") }
            }
        } else if persona.trickLevel >= 2, let w = worst, !w.canSplitKill,
                  w.mass < myMass * 1.55, w.dist < myR * 3.2,
                  frame.count * 2 <= world.settings.maxCellsPerOwner,
                  brain.targetMass >= SrvRules.minSplitMass * 2, sense.wallDist > 700,
                  virusBlockingLane(sense, from: myPos, dir: lane, length: 900, myR: myR * 0.7) == nil {
            // threat can eat us but NOT our halves in one bite, and it's on
            // top of us: split away for the burst of speed.
            plan.variant = SrvBotMind.esSplitAway
            plan.target = SrvVec2(x: myPos.x + lane.x * 1200, y: myPos.y + lane.y * 1200)
            plan.commitUntil = now + 1.2
            if st.plan.variant != plan.variant { bump("escape_splitaway") }
        } else {
            // Do not orbit/hide on viruses. Even as a defensive tactic that
            // could read as farming and produced visible reversals; committed
            // run/detour/through lanes are cleaner and more reliable.
            plan.target = SrvVec2(x: myPos.x + lane.x * 1400, y: myPos.y + lane.y * 1400)
            // perpendicular dodge against an incoming split lane
            if let w = worst, w.canSplitKill {
                let vMag = (w.vel.x * w.vel.x + w.vel.y * w.vel.y).squareRoot()
                if vMag > 0.30 {
                    let lx = w.vel.x / vMag, ly = w.vel.y / vMag
                    let toMe = SrvVec2(x: myPos.x - w.pos.x, y: myPos.y - w.pos.y).normalized()
                    if toMe.x * lx + toMe.y * ly > 0.72 {
                        var px = -ly, py = lx
                        if toMe.x * px + toMe.y * py < 0 { px = -px; py = -py }
                        let dodge = SrvVec2(x: lane.x + px * 1.2, y: lane.y + py * 1.2).normalized()
                        plan.target = SrvVec2(x: myPos.x + dodge.x * 1400, y: myPos.y + dodge.y * 1400)
                    }
                }
            }
        }
        // keep an existing identical variant's commitment (no re-flip)
        if st.plan.kind == .escape, st.plan.variant == plan.variant,
           st.plan.virusID == plan.virusID {
            plan.stage = st.plan.stage
            plan.stageT = st.plan.stageT
        }
        st.plan = plan
        executeEscape(world: world, oid: oid, brainIdx: brainIdx, frame: frame,
                      sense: sense, st: &st, now: now)
    }

    private func executeEscape(world: SrvWorld, oid: UInt32, brainIdx: Int,
                               frame: SrvWorld.BotOwnerFrame, sense: Sense,
                               st: inout BotState, now: Double) {
        let brain = world.cells[brainIdx]
        world.cells[brainIdx].aiMode = .flee
        world.cells[brainIdx].aiFleeing = true
        world.cells[brainIdx].aiSteerTarget = clampTarget(st.plan.target)
        switch st.plan.variant {
        case SrvBotMind.esSplitAway:
            if st.plan.stage == 0 {
                let lane = SrvVec2(x: st.plan.target.x - brain.position.x,
                                y: st.plan.target.y - brain.position.y).normalized()
                world.queueBotSplit(ownerID: oid, direction: lane)
                st.lastSplitAt = now
                st.plan.stage = 1
            }
        case SrvBotMind.esSurf:
            break   // steering INTO the virus is the whole plan
        case SrvBotMind.esHide:
            // time-budgeted: once the loiter meter passes patience the
            // validity check flips it to a plain run on the next think.
            if st.loiter > st.persona.patience {
                st.plan.variant = SrvBotMind.esRun
                let away = SrvVec2(x: brain.position.x - (sense.worst?.pos.x ?? 0),
                                y: brain.position.y - (sense.worst?.pos.y ?? 0)).normalized()
                st.plan.target = SrvVec2(x: brain.position.x + away.x * 1500,
                                      y: brain.position.y + away.y * 1500)
                world.cells[brainIdx].aiSteerTarget = clampTarget(st.plan.target)
            }
        default: break
        }
    }

    // MARK: - Candidate generation & scoring

    private struct Candidate {
        var plan: Plan
        var massEV: Double      // expected mass gain
        var risk: Double        // 0..1
        var time: Double        // seconds to payoff
        var style: Double       // 0..1 trick appeal
        var priority: Double    // tactical mechanic bonus after prerequisites pass
    }

    private func score(_ c: Candidate, persona: Persona, myTotal: Double,
                       current: Plan, loiter: Double) -> Double {
        let evN = c.massEV / (c.massEV + max(60, myTotal * 0.5))
        let speedN = 1.0 / (1.0 + c.time / 6.0)
        var s = persona.wMass * evN + persona.wSpeed * speedN * 0.55
              + persona.wStyle * c.style * 0.22 - persona.wSafety * c.risk
              + c.priority
        if c.plan.kind == current.kind && c.plan.enemyOwner == current.enemyOwner
            && c.plan.virusID == current.virusID { s += 0.18 }   // hysteresis
        // anti-camp: virus-anchored plans get taxed once the loiter meter runs
        if loiter > 2.0, c.plan.kind == .virusShoot {
            s -= (loiter - 2.0) * 0.25
        }
        return s
    }

    private func candidatePlans(world: SrvWorld, oid: UInt32, brainIdx: Int,
                                frame: SrvWorld.BotOwnerFrame, sense: Sense,
                                st: inout BotState, now: Double) -> Plan {
        let ws = SrvRules.worldSize
        let brain = world.cells[brainIdx]
        let myPos = brain.position
        let myMass = brain.mass
        let myTotal = frame.mass
        let myR = brain.cachedRadius
        let myCells = frame.count
        let persona = st.persona
        let baseRisk = min(1.0, sense.threatScore * 2.2)
        var cands: [Candidate] = []

        // Equal-size people are neither prey nor split-kill threats, but
        // blindly driving the shared cursor through their centre looks
        // brain-dead and can hand them the first split. Give the ordinary
        // planner a shoulder lane unless an actual eat is armed.
        let neutralAvoid = sense.neutrals.first

        func add(_ inputPlan: Plan, ev: Double, risk: Double, time: Double, style: Double,
                 priority: Double = 0) {
            var plan = inputPlan
            var r = risk
            // just fled: a target straight back the way we came is a U-turn
            // into the very threat we escaped — tax it hard.
            let toT = SrvVec2(x: plan.target.x - myPos.x, y: plan.target.y - myPos.y).normalized()
            if let n = neutralAvoid, plan.kind != .splitKill, plan.kind != .escape,
               plan.kind != .bait, toT != .zero {
                let rel = SrvVec2(x: n.pos.x - myPos.x, y: n.pos.y - myPos.y)
                let along = rel.x * toT.x + rel.y * toT.y
                let perp = abs(rel.x * toT.y - rel.y * toT.x)
                if along > 0, along < max(700, n.dist + 260),
                   perp < myR + n.radius + 90 {
                    let side = (toT.x * rel.y - toT.y * rel.x) >= 0 ? -1.0 : 1.0
                    let tangent = SrvVec2(x: -toT.y * side, y: toT.x * side)
                    let clearance = myR + n.radius + 150
                    plan.target = clampTarget(SrvVec2(x: n.pos.x + tangent.x * clearance +
                                                   toT.x * 240,
                                                   y: n.pos.y + tangent.y * clearance +
                                                   toT.y * 240))
                    r += 0.04
                }
            }
            if now < st.postEscapeUntil, st.escapeLane != .zero {
                if toT.x * st.escapeLane.x + toT.y * st.escapeLane.y < -0.30 { r += 0.40 }
            }
            // momentum: humans don't hairpin for marginal targets — a target
            // behind the current heading pays a tax (kills, piles etc. can
            // still win on EV; pellets behind us usually shouldn't).
            let heading = brain.aiMovementDirection
            if heading != .zero {
                let h = heading.normalized()
                let dot = toT.x * h.x + toT.y * h.y
                if dot < -0.35 { r += 0.26 * (-dot) }
            }
            cands.append(Candidate(plan: plan, massEV: ev,
                                   risk: min(1, max(0, r)), time: max(0.2, time),
                                   style: style, priority: priority))
            if isTrick(plan) {
                st.trickOpportunities[planKey(plan), default: 0] += 1
            }
        }

        // ---- forage (food cluster / eject pile / token)
        if let f = sense.food {
            var p = Plan(); p.kind = .forage; p.target = f; p.commitUntil = now + 2.2
            add(p, ev: 26, risk: baseRisk, time: f.dist(myPos) / 260, style: 0)
        }
        if let pile = sense.pile {
            // direction-aware: pellets AHEAD are near-free, pellets BEHIND are
            // not worth a U-turn (that flip-flop read as jitter in soaks)
            let mv = brain.aiMovementDirection.normalized()
            let toPile = SrvVec2(x: pile.x - myPos.x, y: pile.y - myPos.y).normalized()
            let ahead = mv == .zero ? 1.0 : max(0.0, mv.x * toPile.x + mv.y * toPile.y)
            var p = Plan(); p.kind = .forage; p.variant = 1; p.target = pile
            p.commitUntil = now + 2.2
            add(p, ev: 24 + 44 * ahead, risk: baseRisk, time: pile.dist(myPos) / 260, style: 0)
        }
        if let t = sense.token {
            var p = Plan(); p.kind = .forage; p.variant = 2; p.target = t
            p.commitUntil = now + 2.2
            add(p, ev: 12, risk: baseRisk, time: t.dist(myPos) / 280, style: 0)
        }

        // ---- hunt / splitKill per prey
        let halfMass = brain.targetMass / 2
        for prey in sense.prey.prefix(6) {
            let wallDistP = min(prey.pos.x, ws - prey.pos.x, prey.pos.y, ws - prey.pos.y)
            var evBoost = 1.0
            if prey.isFeedBot { evBoost = 1.6 }
            if !prey.isBot { evBoost *= 1.0 + (world.owners[oid]?.aiAggression ?? 0.5) * 0.7 }
            if wallDistP < 700 { evBoost *= 1.25 }   // cornered prey
            if prey.mass < myTotal * 0.02 { evBoost *= 0.35 }
            let hunterBoost = persona.archetype == .hunter ? 1.3 : 1.0
            let preyRisk = min(1.0, baseRisk + (prey.ownerTotalNearby > myTotal * 0.8 ? 0.35 : 0))

            // plain engulf chase
            // engulf chases are only fast when the prey is MUCH smaller
            // (smaller cells move faster) or pinned against a wall
            let ratio = prey.mass / max(myMass, 1)
            let catchF = max(0.06, min(1.0, (0.85 - ratio) * 1.6))
            var chaseTime = prey.dist / (230 * catchF)
            if wallDistP < 500 { chaseTime *= 0.55 }
            // consciousness: prey practically touching us is near-free mass
            if prey.dist < myR * 2.6 + 120 { evBoost *= 1.55 }
            var hp = Plan(); hp.kind = .hunt; hp.enemyOwner = prey.ownerID
            hp.enemyCell = prey.id; hp.target = prey.pos; hp.commitUntil = now + 1.2
            add(hp, ev: prey.mass * evBoost * hunterBoost, risk: preyRisk,
                time: chaseTime, style: 0)

            // split kills
            let reach = (myR * 3.4 + 160) * (0.75 + (world.owners[oid]?.aiAggression ?? 0.5) * 0.5)
            let laneDir = SrvVec2(x: prey.pos.x - myPos.x, y: prey.pos.y - myPos.y).normalized()
            let laneBlocked = virusBlockingLane(sense, from: myPos, dir: laneDir,
                                                length: min(prey.dist, reach * 1.1),
                                                myR: myR * 0.62) != nil
            if brain.aiSplitCooldown <= 0, myCells < 8, myMass >= 90, !laneBlocked,
               brain.targetMass >= SrvRules.minSplitMass * 2 {
                let punish2 = splitPunishable(sense, brain: brain, pieces: 2, toward: prey.pos)
                let punish4 = splitPunishable(sense, brain: brain, pieces: 4, toward: prey.pos)
                if halfMass > prey.mass * 1.30, prey.dist < reach, !punish2 {
                    var p = Plan(); p.kind = .splitKill; p.variant = SrvBotMind.skSingle
                    p.enemyOwner = prey.ownerID; p.enemyCell = prey.id; p.target = prey.pos
                    add(p, ev: prey.mass * evBoost * hunterBoost,
                        risk: preyRisk + 0.08, time: 0.75, style: 0.25,
                        priority: persona.trickLevel >= 3 ? 0.34 : 0.18)
                }
                if persona.trickLevel >= 2, halfMass / 2 > prey.mass * 1.30,
                   prey.dist < reach * 1.9, prey.dist > reach * 0.9, myCells < 5, !punish4 {
                    var p = Plan(); p.kind = .splitKill; p.variant = SrvBotMind.skDouble
                    p.enemyOwner = prey.ownerID; p.enemyCell = prey.id; p.target = prey.pos
                    add(p, ev: prey.mass * evBoost * hunterBoost,
                        risk: preyRisk + 0.20, time: 1.05, style: 0.55,
                        priority: 0.42)
                }
                if persona.trickLevel >= 3, halfMass / 2 > prey.mass * 1.15,
                   prey.dist < reach * 3.0, prey.dist > reach * 1.05, myCells < 5,
                   myTotal > 220, prey.dist < myR + 1050, !punish4 {
                    var p = Plan(); p.kind = .splitKill; p.variant = SrvBotMind.skMacroDouble
                    p.enemyOwner = prey.ownerID; p.enemyCell = prey.id; p.target = prey.pos
                    add(p, ev: prey.mass * evBoost * hunterBoost,
                        risk: preyRisk + 0.22, time: 1.35, style: 0.85,
                        priority: 0.48)
                }
            }

        }

        // ---- bait (elite): scatter same-size pieces, punish the greedy split
        if persona.trickLevel >= 4, myCells <= 2, sense.threatScore < 0.08,
           brain.aiSplitCooldown <= 0 {
            for prey in sense.prey.prefix(6) {
                let vMass = prey.mass
                guard prey.ownerCellsNearby == 1, vMass > 60,
                      myTotal > vMass * 3.4, myTotal < vMass * 9.5,
                      prey.dist < 1100,
                      // bait pieces are victim-sized: a covering giant makes
                      // the whole ruse free food — same over-commit as a
                      // punished doublesplit.
                      !splitPunishable(sense, brain: brain,
                                       pieces: max(4.0, myTotal / max(vMass, 40)),
                                       toward: prey.pos) else { continue }
                var p = Plan(); p.kind = .bait
                p.enemyOwner = prey.ownerID; p.enemyCell = prey.id; p.target = prey.pos
                p.baseCellCount = prey.ownerCellsNearby
                add(p, ev: vMass * 1.6, risk: 0.35, time: 4.5, style: 1.0)
            }
        }

        // SrvVirus farming is removed. Tactical virus shots are also disabled
        // for solo scripted bots until a complete fire-position + moving-
        // victim outcome test can guarantee the hit. Pro means no speculative
        // mass donation to a virus.

        // ---- recombine (variants by situation, rate-limited per bot)
        let oldestSplitAge = now - st.lastSplitAt
        let spreadNow = SrvVec2(x: frame.weightedX / max(frame.mass, 0.0001),
                             y: frame.weightedY / max(frame.mass, 0.0001)).dist(myPos)
        // Consolidation is an occasional deliberate move, not a metronome:
        // over-offering it froze bots into visible stop-feed loops.
        if myCells >= 2, sense.threatScore < 0.14, oldestSplitAge > 1.05,
           now - (world.owners[oid]?.bornAt ?? now) > 3.0,
           myCells >= 3 || spreadNow > myR * 1.2,
           !armedOpportunity(sense, brain: brain),
           now - st.lastRecombineAt > max(7.0, persona.patience * 2.5) {
            let spread = SrvVec2(x: frame.weightedX / max(frame.mass, 0.0001),
                              y: frame.weightedY / max(frame.mass, 0.0001)).dist(myPos)
            let consolidationValue = min(220.0, myTotal * 0.14) *
                                     (1.0 + spread / (myR * 4))
            if persona.trickLevel >= 1, myTotal >= 180, spread > myR * 0.35 {
                var p = Plan(); p.kind = .recombine; p.variant = SrvBotMind.recCentre
                p.target = myPos
                add(p, ev: consolidationValue, risk: baseRisk + 0.10, time: 2.4,
                    style: 0.8, priority: persona.trickLevel >= 3 ? 0.22 : 0.08)
            }
            if persona.trickLevel >= 2, myTotal >= 220,
               sense.wallDist < 650, spread < myR * 3.2 {
                // Wall recombine has a real receiver: compact on the nearest
                // wall, eject from ALL pieces toward the largest piece, then
                // stay with that receiver through the pickup grace.
                var p = Plan(); p.kind = .recombine; p.variant = SrvBotMind.recWall
                p.target = nearestWallPoint(myPos)
                add(p, ev: consolidationValue * 1.10,
                    risk: baseRisk + 0.05, time: 2.0, style: 0.7,
                    priority: 0.30)
            }
            // Moving/insta remain disabled until each clears its own
            // receiver-contract evaluation.
        }
        // regroup (walk pieces together, elite bots hold a compact stack)
        if myCells > 1, brain.canMerge {
            let centre = SrvVec2(x: frame.weightedX / max(frame.mass, 0.0001),
                              y: frame.weightedY / max(frame.mass, 0.0001))
            if centre.dist(myPos) > myR * 2.5 {
                var p = Plan(); p.kind = .regroup; p.target = centre
                p.commitUntil = now + 1.2
                add(p, ev: 30, risk: baseRisk, time: 1.6, style: 0)
            }
        }

        // ---- travel when local pickings are thin
        let farJourney = (sense.food.map { $0.dist(myPos) } ?? 9e9) > 1400
        let dest = forwardWaypoint(from: myPos, heading: brain.aiMovementDirection,
                                   reach: 2200...3800)
        if sense.food == nil || sense.crowdMass > myTotal * 6 || farJourney {
            var p = Plan(); p.kind = .travel; p.variant = SrvBotMind.tvPlain
            p.target = dest; p.commitUntil = now + 3.0
            add(p, ev: 30, risk: baseRisk * 0.6, time: dest.dist(myPos) / 240, style: 0)
        }
        // Travel mechanics are real options even while food exists. Nesting
        // them under "no nearby food" made a dense offline map mathematically
        // suppress every split-run/wall-run branch.
        // Split-running is an EMPTY-MAP travel mechanic (Hudson: run the wall
        // "over and over if theres no people"). With a bigger cell in sight,
        // shattering for speed is the over-commit he flagged.
        // v8.6: the blanket giant-free-screen requirement erased travel
        // tricks exactly where Hudson watches (near his own big cell). The
        // directional punish check is the correct safety: pieces may fly
        // anywhere no bigger cell covers the landing lane.
        let runDir = SrvVec2(x: dest.x - myPos.x, y: dest.y - myPos.y).normalized()
        let runLanding = SrvVec2(x: myPos.x + runDir.x * 600, y: myPos.y + runDir.y * 600)
        // Travel tricks are for GOING somewhere: with a worthwhile prey in
        // hunting range, split-running away is itself a missed opportunity.
        let preyNearby = sense.prey.contains {
            ($0.mass >= 40 || $0.mass > myTotal * 0.10) && $0.dist < 1200
        }
        let runSafe = !preyNearby &&
                      !splitPunishable(sense, brain: brain, pieces: 2, toward: runLanding)
        if persona.trickLevel >= 3, myCells <= 2, myTotal > 260, runSafe,
           sense.threatScore < 0.05, brain.aiSplitCooldown <= 0 {
            var q = Plan(); q.kind = .travel; q.variant = SrvBotMind.tvMacroSplitRun
            q.target = dest; q.commitUntil = now + 2.2
            add(q, ev: 30, risk: 0.15, time: dest.dist(myPos) / 420,
                style: 0.9, priority: 0.34)
        }
        if persona.trickLevel >= 3, sense.wallDist < max(950, myR * 2.2), myCells <= 3,
           myTotal > 220, runSafe, sense.threatScore < 0.05, brain.aiSplitCooldown <= 0 {
            var q = Plan(); q.kind = .travel; q.variant = SrvBotMind.tvWallRun
            q.target = wallRunDest(from: myPos, dest: dest); q.commitUntil = now + 3.0
            add(q, ev: 26, risk: 0.14, time: dest.dist(myPos) / 400,
                style: 0.85, priority: 0.38)
        }
        if persona.trickLevel >= 2, myCells <= 2, myTotal > 220, runSafe,
           sense.threatScore < 0.04, brain.aiSplitCooldown <= 0 {
            var q = Plan(); q.kind = .travel; q.variant = SrvBotMind.tvSplitRun
            q.target = dest; q.commitUntil = now + 2.2
            add(q, ev: 26, risk: 0.18, time: dest.dist(myPos) / 380,
                style: 0.6, priority: 0.26)
        }

        // ---- roam fallback: wander FORWARD (a cone around the current
        // heading), so plan churn can't produce hairpin turns
        var roam = Plan(); roam.kind = .roam
        let keepRoam = st.roamUntil > now && st.roamTarget != .zero &&
                       myPos.dist(st.roamTarget) > 280
        roam.target = keepRoam ? st.roamTarget
                               : forwardWaypoint(from: myPos, heading: brain.aiMovementDirection)
        roam.commitUntil = keepRoam ? st.roamUntil : now + Double.random(in: 6...10)
        add(roam, ev: 8, risk: baseRisk * 0.5, time: 4, style: 0)

        // ---- pick the winner
        var bestPlan = roam
        var bestScore = -1e9
        var scored: [(candidate: Candidate, score: Double)] = []
        scored.reserveCapacity(cands.count)
        for c in cands {
            let s = score(c, persona: persona, myTotal: myTotal,
                          current: st.plan, loiter: st.loiter)
            scored.append((c, s))
            if s > bestScore { bestScore = s; bestPlan = c.plan }
        }
        // A pro bot should visibly use its vocabulary, not merely have trick
        // branches lose a scalar contest thousands of times. Ruthless cycles
        // through the next mechanically valid family after a short cooldown;
        // lower tiers still require the normal utility win.
        let deckCooldown: Double = persona.trickLevel >= 3 ? 1.8 : 4.2
        // While a kill is armed, only kill-family tricks may be forced —
        // rotating in a recombine/travel filler over free mass was the top
        // "missed opportunity" source.
        let killFamilies: Set<String> = ["splitkill", "doublesplit", "macrodouble"]
        let armedNow = armedOpportunity(sense, brain: brain)
        if persona.trickLevel >= 2, now - st.lastVisibleTrickAt > deckCooldown {
            let available = scored.filter {
                isTrick($0.candidate.plan) &&
                (!armedNow || killFamilies.contains(planKey($0.candidate.plan)))
            }
            if !available.isEmpty {
                var forced: (candidate: Candidate, score: Double)? = nil
                for offset in 0..<trickDeck.count {
                    let idx = (st.trickDeckIndex + offset) % trickDeck.count
                    let key = trickDeck[idx]
                    if let pick = available.filter({ planKey($0.candidate.plan) == key })
                        .max(by: { $0.score < $1.score }) {
                        forced = pick
                        st.trickDeckIndex = (idx + 1) % trickDeck.count
                        break
                    }
                }
                if let forced = forced {
                    bestPlan = forced.candidate.plan
                    bestScore = forced.score
                }
            }
        }
        // Any SHOWY trick that ends up chosen — forced OR won on utility —
        // charges the deck cooldown. Plain splitkills are everyday play
        // (1600+ per soak): letting them recharge the cooldown starved the
        // deck rotation and Hudson stopped seeing tricks (v8.5 regression).
        if isTrick(bestPlan), planKey(bestPlan) != "splitkill" {
            st.lastVisibleTrickAt = now
        }
        bestPlan.score = bestScore
        return bestPlan
    }

    /// waypoint in a +-55 degree cone around the current heading (random
    /// direction if standing still), clamped into the arena
    private func forwardWaypoint(from p: SrvVec2, heading: SrvVec2,
                                 reach: ClosedRange<Double> = 1200...2600) -> SrvVec2 {
        let ws = SrvRules.worldSize
        var base: Double
        if heading == .zero {
            // Stable cold-start heading from position. Re-rolling 0...2π
            // whenever a slow/held bot replanned caused visible 180° flips.
            let seed = sin(p.x * 0.013 + p.y * 0.021) * 43758.5453
            base = (seed - floor(seed)) * 2 * .pi
        }
        else { base = atan2(heading.y, heading.x) }
        // near a wall, bias the cone back toward the middle
        let centreDir = atan2(ws / 2 - p.y, ws / 2 - p.x)
        let wallDist = min(p.x, ws - p.x, p.y, ws - p.y)
        if wallDist < 900 {
            let t = 1.0 - wallDist / 900
            var d = centreDir - base
            while d > .pi { d -= 2 * .pi }
            while d < -.pi { d += 2 * .pi }
            base += d * t * 0.8
        }
        let a = base + Double.random(in: -0.62...0.62)
        let dist = Double.random(in: reach)
        return SrvVec2(x: min(ws - 400, max(400, p.x + cos(a) * dist)),
                    y: min(ws - 400, max(400, p.y + sin(a) * dist)))
    }

    private func nearestWallPoint(_ p: SrvVec2) -> SrvVec2 {
        let ws = SrvRules.worldSize
        let d = [p.x, ws - p.x, p.y, ws - p.y]
        switch d.firstIndex(of: d.min()!)! {
        case 0: return SrvVec2(x: 130, y: p.y)
        case 1: return SrvVec2(x: ws - 130, y: p.y)
        case 2: return SrvVec2(x: p.x, y: 130)
        default: return SrvVec2(x: p.x, y: ws - 130)
        }
    }

    private func wallRunDest(from: SrvVec2, dest: SrvVec2) -> SrvVec2 {
        // project the destination onto the wall lane we're hugging
        let ws = SrvRules.worldSize
        let d = [from.x, ws - from.x, from.y, ws - from.y]
        switch d.firstIndex(of: d.min()!)! {
        case 0: return SrvVec2(x: 130, y: dest.y)
        case 1: return SrvVec2(x: ws - 130, y: dest.y)
        case 2: return SrvVec2(x: dest.x, y: 130)
        default: return SrvVec2(x: dest.x, y: ws - 130)
        }
    }

    // MARK: - Execution state machines

    private func executePlan(world: SrvWorld, oid: UInt32, brainIdx: Int,
                             frame: SrvWorld.BotOwnerFrame, sense: Sense,
                             st: inout BotState, now: Double, dtThink: Double) {
        let brain = world.cells[brainIdx]
        let myPos = brain.position
        let myR = brain.cachedRadius
        let myTotal = frame.mass
        let persona = st.persona
        let aggression = world.owners[oid]?.aiAggression ?? 0.5
        st.plan.stageT += dtThink

        func steer(_ t: SrvVec2, _ mode: SrvBotMode) {
            var target = clampTarget(t)
            var dir = SrvVec2(x: target.x - myPos.x, y: target.y - myPos.y).normalized()
            if mode != .flee, mode != .hold, dir != .zero,
               st.lastTargetDir != .zero,
               dir.x * st.lastTargetDir.x + dir.y * st.lastTargetDir.y < -0.55 {
                // Ordinary plans may bend but cannot instantly invert the
                // shared cursor. Escape owns true emergency U-turns.
                dir = SrvVec2(x: st.lastTargetDir.x * 0.82 + dir.x * 0.18,
                           y: st.lastTargetDir.y * 0.82 + dir.y * 0.18).normalized()
                target = clampTarget(SrvVec2(x: myPos.x + dir.x * max(500, myPos.dist(target)),
                                          y: myPos.y + dir.y * max(500, myPos.dist(target))))
            }
            if dir != .zero { st.lastTargetDir = dir }
            world.cells[brainIdx].aiSteerTarget = target
            st.moveTarget = target
            world.cells[brainIdx].aiMode = mode
            world.cells[brainIdx].aiFleeing = false
        }
        func hold() {
            world.cells[brainIdx].aiSteerTarget = myPos
            st.moveTarget = myPos
            world.cells[brainIdx].aiMode = .hold
            world.cells[brainIdx].aiFleeing = false
        }
        /// hold with the cursor pinned on a specific point (the recombine
        /// receiver): pieces converge onto it at full speed and stop there.
        func holdAt(_ t: SrvVec2) {
            let target = clampTarget(t)
            world.cells[brainIdx].aiSteerTarget = target
            st.moveTarget = target
            world.cells[brainIdx].aiMode = .hold
            world.cells[brainIdx].aiFleeing = false
        }
        func finish() {
            st.plan = Plan(); st.plan.commitUntil = now
            st.recombineReceiver = nil
            st.recombineFeedDone = false
        }
        func splitAt(_ t: SrvVec2, cooldown: Double) {
            var dir = SrvVec2(x: t.x - myPos.x, y: t.y - myPos.y).normalized()
            if persona.aimJitter > 0.005, dir != .zero {
                let a = atan2(dir.y, dir.x) + Double.random(in: -persona.aimJitter...persona.aimJitter)
                dir = SrvVec2(x: cos(a), y: sin(a))
            }
            world.queueBotSplit(ownerID: oid, direction: dir, toward: t)
            world.cells[brainIdx].aiSplitCooldown = cooldown
            st.lastSplitAt = now
        }
        /// exact eject-speed control: presses at the persona's macro rate,
        /// pellet flight distance scaled by `speed` (0.4 short drip ... 1.0 full)
        @discardableResult
        func macro(toward t: SrvVec2, presses: Int, reserve: Double, speed: Double,
                   goal: SrvWorld.BotMacroTrace.Goal, centre: Bool = false) -> Int {
            guard world.cells[brainIdx].aiFeedCooldown <= 0 else { return 0 }
            // Never layer fresh volleys onto an unresolved cloud. Pro macro
            // speed is rapid presses inside one burst, not blind repeated
            // bursts every think.
            if now - st.lastMacroAt < 0.75 && t.dist(st.lastMacroTarget) < 260 {
                return 0
            }
            // A macro must name a live, geometrically reachable receiver.
            // This veto is the difference between a trick and dumping mass.
            switch goal {
            case .ownCell(let id):
                guard let receiver = world.cells.first(where: { $0.id == id && $0.ownerID == oid }),
                      receiver.position.dist(t) < 80 else { return 0 }
            case .enemyOwner(let enemy):
                guard sense.prey.contains(where: { $0.ownerID == enemy && $0.pos.dist(t) < 320 })
                else { return 0 }
            case .virus(let id):
                guard sense.viruses.contains(where: { $0.id == id && $0.pos.dist(t) < 80 })
                else { return 0 }
            case .splitRecollect:
                guard st.plan.kind == .splitKill || st.plan.kind == .travel else { return 0 }
            }
            let jitteredSpeed = min(1.6, max(0.35,
                speed + (1.0 - persona.ejectControl) * Double.random(in: -0.18...0.18)))
            let ids = world.ejectMassFromBotOwnerTracked(
                oid, toward: t, burstPresses: presses, reserveMass: reserve,
                centerConverge: centre, speedScale: jitteredSpeed)
            let n = ids.count
            if n > 0 {
                world.registerBotMacro(ids: ids, ownerID: oid, goal: goal)
                st.lastMacroAt = now
                st.lastMacroTarget = t
                world.cells[brainIdx].aiFeedCooldown =
                    max(0.045, 0.17 - Double(persona.trickLevel) * 0.028)
            }
            return n
        }
        func preyNow() -> Prey? {
            guard let eo = st.plan.enemyOwner else { return nil }
            if let cid = st.plan.enemyCell,
               let exact = sense.prey.first(where: { $0.id == cid }) { return exact }
            return sense.prey.filter { $0.ownerID == eo }.min { $0.dist < $1.dist }
        }
        func ownCellIndices() -> [Int] {
            var out: [Int] = []
            for i in world.cells.indices where world.cells[i].ownerID == oid { out.append(i) }
            return out
        }

        switch st.plan.kind {

        case .roam:
            steer(st.plan.target, .wander)

        case .forage:
            // refresh the anchor only if the fresher target is basically the
            // same spot — swinging to a new best-cluster every think was a
            // jerky-movement source. Otherwise finish and re-plan cleanly.
            let fresh = st.plan.variant == 1 ? sense.pile : (st.plan.variant == 0 ? sense.food : sense.token)
            if let f = fresh, f.dist(st.plan.target) < 320,
               myPos.dist(st.plan.target) > 500 {
                st.plan.target = f      // refine only while approaching from afar
            }
            steer(st.plan.target, .forage)
            if myPos.dist(st.plan.target) < max(60, myR * 0.7) || st.plan.stageT > 5 { finish() }

        case .regroup:
            steer(st.plan.target, .regroup)
            if myPos.dist(st.plan.target) < myR { finish() }

        case .travel:
            switch st.plan.variant {
            case SrvBotMind.tvSplitRun:
                steer(st.plan.target, .travel)
                if st.plan.stage == 0 { bump("splitrun"); st.plan.stage = 1 }
                if frame.count <= 2, brain.aiSplitCooldown <= 0,
                   brain.targetMass >= SrvRules.minSplitMass * 2, sense.threatScore < 0.06 {
                    let d = SrvVec2(x: st.plan.target.x - myPos.x,
                                 y: st.plan.target.y - myPos.y).normalized()
                    let landing = SrvVec2(x: myPos.x + d.x * 600, y: myPos.y + d.y * 600)
                    if !splitPunishable(sense, brain: brain, pieces: 2, toward: landing) {
                        splitAt(st.plan.target, cooldown: 1.2)
                    }
                }
            case SrvBotMind.tvMacroSplitRun:
                // Conserved-mass split run. The old post-split W volley was
                // not mechanically guaranteed to consolidate, so it is
                // disabled until a receiver-perfect version earns its way
                // back through the contract tests.
                steer(st.plan.target, .travel)
                if st.plan.stage == 0, brain.aiSplitCooldown <= 0,
                   brain.targetMass >= SrvRules.minSplitMass * 2 {
                    let d = SrvVec2(x: st.plan.target.x - myPos.x,
                                 y: st.plan.target.y - myPos.y).normalized()
                    let landing = SrvVec2(x: myPos.x + d.x * 600, y: myPos.y + d.y * 600)
                    guard !splitPunishable(sense, brain: brain, pieces: 2, toward: landing) else { finish(); return }
                    splitAt(st.plan.target, cooldown: 1.0)
                    bump("macrosplitrun")
                    st.plan.stage = 1; st.plan.stageT = 0
                } else if st.plan.stageT > 1.4 {
                    finish()
                }
            case SrvBotMind.tvWallRun:
                // Wall running is conserved-mass movement: split along the
                // edge. Decorative pre-feed was the exact "macro and leave"
                // failure Hudson saw, so it is gone.
                steer(st.plan.target, .travel)
                if st.plan.stage == 0 { bump("wallrun"); st.plan.stage = 1; st.plan.stageT = 0 }
                if st.plan.stageT > 0.65, frame.count <= 4, brain.aiSplitCooldown <= 0,
                   brain.targetMass >= SrvRules.minSplitMass * 2, sense.threatScore < 0.06 {
                    let d = SrvVec2(x: st.plan.target.x - myPos.x,
                                 y: st.plan.target.y - myPos.y).normalized()
                    let landing = SrvVec2(x: myPos.x + d.x * 600, y: myPos.y + d.y * 600)
                    if !splitPunishable(sense, brain: brain, pieces: 2, toward: landing) {
                        splitAt(st.plan.target, cooldown: 1.1)
                        st.plan.stageT = 0
                    }
                }
            default:
                steer(st.plan.target, .travel)
            }
            if myPos.dist(st.plan.target) < 300 { finish() }

        case .hunt:
            guard let prey = preyNow() else { finish(); return }
            // Track one owner's lead with a damped cursor. Re-targeting the
            // nearest split piece every think could ping-pong 180° inside a
            // multi-cell victim and looked like blindness.
            if st.huntOwner != prey.ownerID {
                st.huntOwner = prey.ownerID
                st.huntTarget = prey.pos
            } else {
                st.huntTarget = SrvVec2(x: st.huntTarget.x * 0.72 + prey.pos.x * 0.28,
                                     y: st.huntTarget.y * 0.72 + prey.pos.y * 0.28)
            }
            st.plan.target = st.huntTarget
            steer(st.huntTarget, .hunt)

        case .splitKill:
            guard let prey = preyNow() else { finish(); return }
            st.plan.target = prey.pos
            steer(prey.pos, .hunt)
            let reach = (myR * 3.4 + 160) * (0.75 + aggression * 0.5)
            let laneDir = SrvVec2(x: prey.pos.x - myPos.x, y: prey.pos.y - myPos.y).normalized()
            if virusBlockingLane(sense, from: myPos, dir: laneDir,
                                 length: min(prey.dist, reach * 1.1), myR: myR * 0.62) != nil {
                finish(); return   // lane got blocked since planning: veto, replan
            }
            switch st.plan.variant {
            case SrvBotMind.skDouble:
                if st.plan.stage == 0, prey.dist < reach * 1.9,
                   brain.targetMass >= SrvRules.minSplitMass * 2 {
                    guard !splitPunishable(sense, brain: brain, pieces: 4, toward: prey.pos) else { finish(); return }
                    splitAt(prey.pos, cooldown: 0.4)
                    st.plan.stage = 1; st.plan.stageT = 0
                } else if st.plan.stage == 1, st.plan.stageT > 0.22 {
                    // The second launch is not a promise. Re-verify the mark
                    // is still inside the follow-up envelope and still loses
                    // to a quarter — firing blind at where it USED to be was
                    // the visible over-commit.
                    if prey.dist < reach * 1.35, brain.targetMass / 2 > prey.mass * 1.30,
                       !splitPunishable(sense, brain: brain, pieces: 2, toward: prey.pos) {
                        splitAt(prey.pos, cooldown: 1.6 - aggression * 0.6)
                        bump("doublesplit"); finish()
                    } else if st.plan.stageT > 0.7 {
                        bump("doublesplit_held"); finish()
                    }
                }
            case SrvBotMind.skMacroDouble:
                if st.plan.stage == 0 {
                    // Atomic macro→double: do not spend one pellet until the
                    // target is inside the actual follow-up envelope.
                    guard prey.dist < reach * 2.6,
                          brain.targetMass / 4 > prey.mass * 1.30 else {
                        finish(); return
                    }
                    // Macro-double is a mass-charge trick: W into the small
                    // target first, then split the now-larger target. Calling
                    // this "recollect" made the pellets land in empty space.
                    let n = macro(toward: prey.pos,
                                  presses: min(3, persona.macroPresses),
                                  reserve: myTotal * 0.68, speed: 1.0,
                                  goal: .enemyOwner(prey.ownerID))
                    if n > 0 {
                        st.plan.stage = 1; st.plan.stageT = 0
                    } else if st.plan.stageT > 0.6 { finish() }
                } else if st.plan.stage == 1, prey.dist < reach * 1.9,
                          st.plan.stageT > 0.24 {
                    guard brain.targetMass / 2 > prey.mass * 1.25,
                          !splitPunishable(sense, brain: brain, pieces: 2, toward: prey.pos) else {
                        bump("macrodouble_held"); finish(); return
                    }
                    splitAt(prey.pos, cooldown: 1.6 - aggression * 0.6)
                    bump("macrodouble"); finish()
                } else if st.plan.stage == 1, st.plan.stageT > 0.65 {
                    finish()
                }
            default:
                if prey.dist < reach, brain.targetMass / 2 > prey.mass * 1.30,
                   !splitPunishable(sense, brain: brain, pieces: 2, toward: prey.pos) {
                    splitAt(prey.pos, cooldown: 1.4 - aggression * 0.6)
                    bump("splitkill"); finish()
                } else if st.plan.stageT > 2.0 { finish() }
            }

        case .bait:
            guard let prey = preyNow() else { finish(); return }
            switch st.plan.stage {
            case 0:
                // scatter into victim-sized pieces
                let want = max(4, min(8, Int((myTotal / max(prey.mass, 40)).rounded())))
                if frame.count < want, brain.aiSplitCooldown <= 0,
                   brain.targetMass >= SrvRules.minSplitMass * 2 {
                    let a = Double.random(in: 0...(2 * .pi))
                    world.queueBotSplit(ownerID: oid,
                                        direction: SrvVec2(x: cos(a), y: sin(a)))
                    world.cells[brainIdx].aiSplitCooldown = 0.25
                } else if frame.count >= want {
                    st.plan.stage = 1; st.plan.stageT = 0
                    st.plan.baseCellCount = prey.ownerCellsNearby
                    bump("bait_set")
                }
                steer(SrvVec2(x: prey.pos.x + (myPos.x - prey.pos.x) * 0.6,
                           y: prey.pos.y + (myPos.y - prey.pos.y) * 0.6), .trick)
            case 1:
                // lure: drift loosely beside the mark, look edible
                steer(SrvVec2(x: prey.pos.x + (myPos.x - prey.pos.x) * 0.55,
                           y: prey.pos.y + (myPos.y - prey.pos.y) * 0.55), .trick)
                if prey.ownerCellsNearby > st.plan.baseCellCount {
                    st.plan.stage = 2; st.plan.stageT = 0   // they split: spring it
                }
            default:
                // flip: pump everything into the piece closest to their lead
                let own = ownCellIndices()
                guard let receiver = own.min(by: {
                    world.cells[$0].position.distSq(prey.pos) <
                    world.cells[$1].position.distSq(prey.pos) }) else { finish(); return }
                let rPos = world.cells[receiver].position
                macro(toward: rPos, presses: persona.macroPresses,
                      reserve: myTotal * 0.15, speed: 0.8,
                      goal: .ownCell(world.cells[receiver].id), centre: true)
                steer(prey.pos, .trick)
                if st.plan.stageT > 1.6 { bump("bait_flip"); finish() }
            }

        case .virusShoot:
            // No candidate currently emits this plan; retained wire-compatible
            // enum case only. Do not eject speculatively.
            finish()

        case .recombine:
            let own = ownCellIndices()
            guard own.count > 1 else { bump("recombine_done"); finish(); return }
            var largest = own[0]
            for i in own where world.cells[i].targetMass > world.cells[largest].targetMass { largest = i }
            if let receiverID = st.recombineReceiver,
               let pinned = own.first(where: { world.cells[$0].id == receiverID }) {
                largest = pinned
            } else {
                st.recombineReceiver = world.cells[largest].id
            }
            let lPos = world.cells[largest].position
            switch st.plan.variant {
            case SrvBotMind.recWall:
                if st.plan.stage == 0 {
                    // Charge the attempt on ENTRY. Charging it only on a stage
                    // some owners could never reach re-offered recombine every
                    // re-plan and looped the bot into standing still.
                    st.lastRecombineAt = now
                    steer(st.plan.target, .trick)
                    if sense.wallDist < myR * 1.3 {
                        st.plan.stage = 1; st.plan.stageT = 0
                        bump("recombine_wall")
                        st.macroStartResolved = world.owners[oid]?.botMacroResolved ?? 0
                        st.macroStartOrphaned = world.owners[oid]?.botMacroOrphaned ?? 0
                        st.recombineFeedDone = false
                    }
                } else {
                    // Wall recombine has a real receiver, not an empty point
                    // beyond the wall. Compact against the wall (cursor pinned
                    // on the receiver so pieces actually converge), then feed
                    // inward to the largest piece and remain on it.
                    holdAt(lPos)
                    let compact = own.allSatisfy {
                        world.cells[$0].position.dist(lPos) <
                            world.cells[largest].cachedRadius +
                            world.cells[$0].cachedRadius + 120
                    }
                    if compact && !st.recombineFeedDone {
                        let fired = macro(toward: lPos, presses: min(3, persona.macroPresses),
                              reserve: max(80, myTotal * 0.42), speed: 0.35,
                              goal: .ownCell(world.cells[largest].id), centre: true)
                        if fired > 0 {
                            // Pin the cursor on the PILE, not the live receiver:
                            // converging pieces shove the receiver around, and a
                            // shoved receiver drifting off its own pellets was the
                            // top orphan source. The receiver walks back onto the
                            // pinned pile and absorbs it when the grace lapses.
                            st.plan.target = lPos
                            st.recombineFeedDone = true
                            st.plan.stageT = 0
                        }
                    }
                    if st.recombineFeedDone { holdAt(st.plan.target) }
                    let resolved = (world.owners[oid]?.botMacroResolved ?? 0) - st.macroStartResolved
                    let orphaned = (world.owners[oid]?.botMacroOrphaned ?? 0) - st.macroStartOrphaned
                    if resolved >= 2 { bump("recombine_wall_ok"); finish() }
                    else if st.plan.stageT > (st.recombineFeedDone ? 3.4 : 2.4) { finish() }
                }
            case SrvBotMind.recMoving:
                // pellets only fly ~200u from each cell's rim, so feeding
                // "forward" from a spread stack never reaches the collector.
                // Real technique: tighten the stack first, THEN drip pellets
                // right at the lead cell while everyone keeps rolling forward.
                steer(st.plan.target, .trick)
                let lane = SrvVec2(x: st.plan.target.x - myPos.x,
                                y: st.plan.target.y - myPos.y).normalized()
                var lead = own[0]; var leadDot = -1e9
                for i in own {
                    let d = (world.cells[i].position.x - myPos.x) * lane.x +
                            (world.cells[i].position.y - myPos.y) * lane.y
                    if d > leadDot { leadDot = d; lead = i }
                }
                let leadPos = world.cells[lead].position
                let leadR = world.cells[lead].cachedRadius
                var spreadM = 0.0
                for i in own { spreadM = max(spreadM, world.cells[i].position.dist(leadPos)) }
                if st.plan.stage == 0 {
                    bump("recombine_moving"); st.lastRecombineAt = now
                    st.recStartShare = Double(world.owners[oid]?.consolidationFeeds ?? 0)
                    st.macroStartResolved = world.owners[oid]?.botMacroResolved ?? 0
                    st.macroStartOrphaned = world.owners[oid]?.botMacroOrphaned ?? 0
                    st.plan.stage = 1; st.plan.stageT = 0
                }
                if st.plan.stage == 1 {
                    // .trick cohesion (1.6) pulls the stack tight while we roll
                    if spreadM < leadR + 180 { st.plan.stage = 2; st.plan.stageT = 0 }
                    else if st.plan.stageT > 2.4 { finish() }
                } else if st.plan.stage == 2 {
                    // Feed the verified leading receiver, then keep the common
                    // cursor on that receiver during the grace window. No
                    // arbitrary point 1200u ahead and no walking away.
                    let n = macro(toward: leadPos, presses: min(3, persona.macroPresses),
                                  reserve: max(80, myTotal * 0.42), speed: 0.68,
                                  goal: .ownCell(world.cells[lead].id), centre: true)
                    if n > 0 {
                        st.plan.target = leadPos
                        st.plan.stage = 3; st.plan.stageT = 0
                    } else if st.plan.stageT > 0.8 {
                        finish()
                    }
                } else {
                    steer(leadPos, .trick)
                    let resolved = (world.owners[oid]?.botMacroResolved ?? 0) - st.macroStartResolved
                    let orphaned = (world.owners[oid]?.botMacroOrphaned ?? 0) - st.macroStartOrphaned
                    if resolved >= 2 || orphaned > 0 || st.plan.stageT > 1.9 {
                        let feeds = Double(world.owners[oid]?.consolidationFeeds ?? 0)
                        if feeds >= st.recStartShare + 3 && resolved >= 2 {
                            bump("recombine_moving_ok")
                        }
                        finish()
                    }
                }
            case SrvBotMind.recInsta:
                // Disabled: with ordinary ALL-CELLS W input, a moving insta
                // receiver cannot be guaranteed. Falling back to the compact,
                // stationary receiver path is less flashy and actually pro.
                st.plan.variant = SrvBotMind.recCentre
                st.plan.stage = 0; st.plan.stageT = 0
                hold()
            default:   // recCentre: the classic stop-and-converge consolidation
                if st.plan.stage == 0 {
                    // Charge the attempt on ENTRY (see recWall) so an aborted
                    // compact can never re-offer instantly and freeze the bot.
                    st.lastRecombineAt = now
                    // centre feed is a STOP trick: pin the cursor on the
                    // receiver — every piece converges onto it at full speed
                    // and stops on arrival, like a human parking the mouse.
                    holdAt(lPos)
                    let compact = own.allSatisfy {
                        world.cells[$0].position.dist(lPos) <
                            world.cells[largest].cachedRadius +
                            world.cells[$0].cachedRadius + 90
                    }
                    if compact {
                        st.plan.stage = 1; st.plan.stageT = 0
                        bump("recombine_centre")
                        st.recStartShare = Double(world.owners[oid]?.consolidationFeeds ?? 0)
                        st.macroStartResolved = world.owners[oid]?.botMacroResolved ?? 0
                        st.macroStartOrphaned = world.owners[oid]?.botMacroOrphaned ?? 0
                        st.recombineFeedDone = false
                    } else if st.plan.stageT > 2.4 { finish() }
                } else {
                    if !st.recombineFeedDone {
                        holdAt(lPos)
                        let n = macro(toward: lPos, presses: min(3, persona.macroPresses),
                                      reserve: max(80, myTotal * 0.45), speed: 0.35,
                                      goal: .ownCell(world.cells[largest].id), centre: true)
                        if n > 0 {
                            // Pin the pile (see recWall): the receiver gets
                            // shoved by converging pieces, so hold the cursor on
                            // where the pellets actually settle.
                            st.plan.target = lPos
                            st.recombineFeedDone = true
                            st.plan.stageT = 0
                        }
                    } else {
                        holdAt(st.plan.target)
                    }
                    let resolved = (world.owners[oid]?.botMacroResolved ?? 0) - st.macroStartResolved
                    if resolved >= 2 || st.plan.stageT > (st.recombineFeedDone ? 3.4 : 1.2) {
                        let feeds = Double(world.owners[oid]?.consolidationFeeds ?? 0)
                        if feeds >= st.recStartShare + 3 && resolved >= 2 {
                            bump("recombine_centre_ok")
                        }
                        finish()
                    }
                }
            }

        case .escape:
            break   // handled by escapeThink
        }
    }

    // MARK: - Housekeeping & metrics

    func forget(_ oid: UInt32) { states.removeValue(forKey: oid) }

    /// Test-only visibility into the planner. Production code still enters
    /// through `think`; the deterministic BotExam uses this to prove that a
    /// concrete human-present setup selects (not merely offers) its mechanic.
    func debugPlan(world: SrvWorld, oid: UInt32, brainIdx: Int,
                   frame: SrvWorld.BotOwnerFrame, skill: Double,
                   index: SrvCellIndex) -> Plan? {
        guard let owner = world.owners[oid] else { return nil }
        var st = states[oid] ?? BotState(persona: SrvBotMind.makePersona(
            owner: owner, skill: skill, globalSkill: world.settings.botSkill))
        let sense = perceive(world: world, oid: oid, brain: world.cells[brainIdx],
                             frame: frame, skill: skill, index: index)
        let plan = candidatePlans(world: world, oid: oid, brainIdx: brainIdx,
                                  frame: frame, sense: sense, st: &st, now: world.time)
        states[oid] = st
        return plan
    }

    func debugPlanName(_ p: Plan) -> String { planKey(p) }

    /// Test-only: the plan a live bot is ACTUALLY executing right now
    /// (debugPlan re-plans; this reads the committed state, so escapes and
    /// their variants are visible to the harness).
    func debugLivePlanName(_ oid: UInt32) -> String {
        guard let st = states[oid] else { return "none" }
        if st.plan.kind == .escape {
            return "escape.v\(st.plan.variant)"
        }
        return planKey(st.plan)
    }

    func metricsReport(world: SrvWorld) -> String {
        var totalThinkMinutes = 0.0
        var totalReversals = 0
        var totalLoiter = 0.0
        var decisions = 0
        var choices: [String: Int] = [:]
        var opportunities: [String: Int] = [:]
        var trickChoices: [String: Int] = [:]
        for (_, s) in states {
            totalThinkMinutes += s.thinkSeconds / 60.0
            totalReversals += s.reversals
            totalLoiter += s.loiter
            decisions += s.decisions
            for (k, v) in s.planChoices { choices[k, default: 0] += v }
            for (k, v) in s.trickOpportunities { opportunities[k, default: 0] += v }
            for (k, v) in s.trickChoices { trickChoices[k, default: 0] += v }
        }
        var lines: [String] = []
        lines.append(String(format: "bot-minutes observed   %.1f", totalThinkMinutes))
        lines.append(String(format: "direction reversals    %.2f per bot-minute",
                            totalThinkMinutes > 0 ? Double(totalReversals) / totalThinkMinutes : 0))
        lines.append(String(format: "live virus-loiter sum  %.1fs across %d bots",
                            totalLoiter, states.count))
        lines.append("new-plan decisions      \(decisions)")
        for k in Set(choices.keys).union(opportunities.keys).sorted() {
            let c = choices[k, default: 0], o = opportunities[k, default: 0]
            if o > 0 || c > 0 {
                lines.append(String(format: "plan %-16@ chose %5d / offered %5d",
                                    k as NSString, c, o))
            }
        }
        let tc = trickChoices.values.reduce(0, +)
        lines.append(String(format: "visible trick choices  %d (%.1f%% of new plans)",
                            tc, decisions > 0 ? 100 * Double(tc) / Double(decisions) : 0))
        let keys = stats.keys.sorted()
        for k in keys { lines.append(k.padding(toLength: 22, withPad: " ", startingAt: 0) + " \(stats[k]!)") }
        return lines.joined(separator: "\n")
    }
}


